WordHunterWoW_QuestEN[39614] = { title = "Fish Out of Water", description = "The drogbar are on a rampage! They're smashing everything they can find and are throwing fish to the shore.\n\nWorst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.", objectives = "Return 8 Whitewater Carp to the river.", progress = "We used to supply the drogbar with most of their food between our fish and crops. What will the fools eat now?", completion = "Thank you. You saved enough fish that they can breed a new population." }
