WordHunterWoW_QuestEN[39645] = { title = "Calibration Experts", description = "It will take the cooperation of several highly skilled sorts to calibrate these burettes.\n\nMyshalla Streambreeze in Feralas has demonstrated admirable attention to detail.\n\nI loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision.\n\nAnd while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.", objectives = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", completion = "Yes, I'd say these burettes look well-calibrated.\n\nI knew those three would be meticulous. Never underestimate the value of someone who obsesses over tiny details, <name>!" }
WordHunterWoW_QuestEN[39646] = { title = "Albino Elderhorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[39647] = { title = "Get the Little Ones!", description = "", objectives = "" }
WordHunterWoW_QuestEN[39648] = { title = "Where Are the Children?", description = "The children have gone missing!\n\nThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!\n\nOur scouts have spotted him over in Frostfire Ridge.", objectives = "Save 6 Kidnapped Children.", progress = "Thank you for all the help! Their families will be so happy to see them.", completion = "Thank you for all the help! Their families will be so happy to see them." }
WordHunterWoW_QuestEN[39649] = { title = "Menacing Grumplings", description = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus.\n\nIf you're able to remove the threat I'm sure rescuing the children won't be much of a problem.", objectives = "Kill 8 Grumplings.", progress = "Well that was fast! Grumpus is gonna have a hard time continuing his work without his minions.\n\nTake these. I had them specially crafted to withstand any climate.\n\nYou never know what you'll run into out here in Draenor!", completion = "Well that was fast! Grumpus is gonna have a hard time continuing his work without his minions.\n\nTake these. I had them specially crafted for ya.\n\nYou never know what you'll run into out here in Draenor!" }
WordHunterWoW_QuestEN[39651] = { title = "Grumpus", description = "One of Draenor's oldest stories is the legend of Grumpus.\n\nThe story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions.\n\nBut Grumpus is no legend, he's real and he's taken our children! Please, you have to slay him!", objectives = "Slay Grumpus.", completion = "Thanks, <name>. I couldn't have done it without you.\n\nTake these as a token of my appreciation.\n\nHappy holidays!" }
WordHunterWoW_QuestEN[39652] = { title = "Where Dragons Rule", description = "Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes.\n\nShe has gathered our brood at the top of Thorim's Peak to prepare for a counterattack. \n\nWould you join us?", objectives = "Speak to Vethir to fly to the top of Thorim's Peak.", completion = "You are truly a hero to my brood.  \n\nYou have gained a powerful ally today, outsider. The God-King has reason to fear you." }
WordHunterWoW_QuestEN[39654] = { title = "Odyn and the Valarjar", description = "Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself.\n\nI will take you to Odyn now, follow me.", objectives = "Follow Danica to see Odyn.", completion = "Now all here know who you are. It is time for armaments befitting my champion." }
WordHunterWoW_QuestEN[39655] = { title = "If At First You Fail, Try Again!", description = "Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.\n\nLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.", objectives = "Meet Yanas Seastrike at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission.", progress = "Get that replacement Destroyer built?", completion = "That was an amazing turn around commander!  Great work." }
WordHunterWoW_QuestEN[39656] = { title = "Wolf Pack Attack", description = "It's time to attack the pack! I've preloaded the hand cannon. All you have to do is point and shoot.\n\nThe critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders.\n\nHappy hunting!", objectives = "Shoot the Critter Hand Cannon near wolf packs so that they scatter, allowing the packleaders to be singled out.", progress = "The critter hand cannon is loaded and ready for use! Just aim for one of the packs nearby. The packleaders should be easy to kill once the howlers are distracted.", completion = "You made it back without any scratches. It looks like the backfire issue from the last prototype worked itself out.\n\nA few more tweaks and I'd say this hand cannon is ready for mass production. Thanks for the help, <name>." }
WordHunterWoW_QuestEN[39657] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[39658] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[39659] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[39661] = { title = "Lifespring Cavern", description = "The drogbar have taken over my cavern. It is where we Rivermane practice our water magic and get much of the purest healing water in Highmountain.\n\nMeet me there and we will cleanse that sacred place of these dark-dwellers.", objectives = "Meet Jale Rivermane at Lifespring Cavern.", completion = "Are you ready? We are about to enter a cave... and the drogbar are at home in such dark places." }
WordHunterWoW_QuestEN[39663] = { title = "On Felbat Wings", description = "It is time. We have dealt the Legion's forces a crippling blow from which they will never recover.\n\nQuickly, let us mount up and take the fight to Tyranna's command center.", objectives = "Grab a felbat from Illidari Whitemoon and fly up to the Fel Hammer.", completion = "Can you sense her power? It will take all of you combined.\n\nEven so... I better go secure our way out of here." }
WordHunterWoW_QuestEN[39665] = { title = "A True Naval Commander", description = "Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blocade and expand our control of the Draenor seas.", objectives = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission.", progress = "Get that equipment installed?", completion = "Equipment can really make a difference out there!" }
WordHunterWoW_QuestEN[39666] = { title = "Equipping Our Fleet", description = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Salty Jorren down at the docks, he should be able to help us out.", objectives = "Meet Salty Jorren at the docks.", progress = "Yes?", completion = "Equipment can really make a difference out there, let's see what I can do to help ya out." }
WordHunterWoW_QuestEN[39667] = { title = "Where's Lyndras: Leyflame Larceny", description = "The guards here must have seen Lyndras come through. The trail of ley dust isn't exactly hard to miss either.\n\nPerhaps one of the guards knows what became of Lyndras.", objectives = "Ask the Violet Hold guards about Lyndras.", completion = "You looking for that crazed elf? Sorry to say he's been locked up.\n\nWe found him hunched in the corner making all sorts of noise and when we approached him, he attacked one of our guards.\n\nWe also found him with an item that was reported stolen. We had no choice but to lock him up in Violet Hold." }
WordHunterWoW_QuestEN[39668] = { title = "What Horrible Presents!", description = "That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable.\n\nTake this spirit bomb. Toss it on some of Grumpus's unusual gifts and take them out for good!\n\nWe're in this together, {name}. Now go and save the spirit of the holiday!", objectives = "Destroy 5 Unusual Gifts.", progress = "Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what those were made of.", completion = "Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what was inside some of those packages." }
WordHunterWoW_QuestEN[39670] = { title = "Critter Scatter Shot", description = "The howlers in these hills travel in packs. Three against one isn't a fight I want to pick.\n\nLuckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo...\n\nSnatch me some rabbits from the meadow south of here, and I'll let you be the first to try out the hand cannon.", objectives = "Catch rabbits in Sunfrost Glade.", progress = "Have you snatched the rabbits yet?", completion = "Hrm, these rabbits are a bit bigger than I thought, but we should still be able to stuff a few of them into the hand cannon." }
WordHunterWoW_QuestEN[39671] = { title = "Guards and Criswold", description = "", objectives = "" }
WordHunterWoW_QuestEN[39674] = { title = "If At First You Fail, Try Again!", description = "Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.\n\nLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.", objectives = "Meet Solog Roark at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission.", progress = "Get that replacement Destroyer built?", completion = "That was an amazing turn around commander!  Great work." }
WordHunterWoW_QuestEN[39675] = { title = "Equipping Our Fleet", description = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Kronk Rustspark down at the docks, he should be able to help us out.", objectives = "Meet Kronk Rustspark at the docks.", progress = "Find Kronk?", completion = "Equipment can really make a difference out there, let's see what I can do to help ya out." }
WordHunterWoW_QuestEN[39676] = { title = "A True Naval Commander", description = "Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blockade and expand our control of the Draenor seas.", objectives = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission.", progress = "Get that equipment installed?", completion = "Equipment can really make a difference out there!" }
WordHunterWoW_QuestEN[39680] = { title = "Between the Hammer...", description = "{name}, I fear that my spirit will remain bound to this place unless I am made whole again.\n\nLong ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled.\n\nI need that hammer back if I am to be at peace.", objectives = "Bring Saris' Hammer back to his shop.", progress = "Any luck retrieving my hammer?", completion = "Thank you, <name>. Words cannot express what this means to me.\n\nAnd as promised, here is a gift of knowledge to you." }
WordHunterWoW_QuestEN[39681] = { title = "The Properties of Leystone", description = "I've never seen anything like this \"leystone\" ore. It's light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium.\n\nLet's try making something with it. How about a nice pair of gauntlets?", objectives = "Observe Alard as he attempts to work with the leystone ore.", completion = "Are you alright? Most of my stock seems to be unharmed by the flames. It's a good thing this wasn't the tailoring shop.\n\nThe explosion seemed to happen when I applied the flux.\n\nNo flux means no welding. That's a shame. Without the ability to weld, we're limited to crafting belts and bracers." }
WordHunterWoW_QuestEN[39682] = { title = "Grand Theft Felbat", description = "You heard what Maiev said. We need to get out of here.\n\nThere is an elevator shaft at the far end of these caverns. Let us make our way there.", objectives = "Ride a felbat to the upper vault.", completion = "Kayn and Altruis said you would be coming. Just in time, <name>." }
WordHunterWoW_QuestEN[39683] = { title = "Forged in Fire", description = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. \n\nSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.\n\nThe demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.\n\nI believe that person could be you, {name}.", objectives = "Kill Immolanth and take his power.", completion = "Yes... just look you... surging with new power and knowledge!" }
WordHunterWoW_QuestEN[39684] = { title = "Beam Me Up", description = "To the east is an intricate prison chamber designed to contain the beholder, Glazer.\n\nIt began malfunctioning shortly after the breach.\n\nYou will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer's impenetrable shield.\n\nHurry. Altruis went ahead to assist the others, but we are losing the fight.", objectives = "Break Glazer's shield.", completion = "I had no doubt you would know what to do." }
WordHunterWoW_QuestEN[39685] = { title = "Frozen in Time", description = "The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul'dan's forces have breached the walls, it's proving rather... inconvenient.\n\nMany of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don't have the means to take it down. However, we might be able to reactivate the room's containment field.\n\nGo join up with Kayn. Do whatever it takes to seal that chamber!", objectives = "Activate the Countermeasures in the Vault of Ice.", completion = "I knew you could do it, <name>. We could not let that creature escape." }
WordHunterWoW_QuestEN[39686] = { title = "All The Way Up", description = "Kor'vas went ahead to meet up with Kayn and Altruis.\n\nStep onto the elevator when it arrives, and meet them in the Hall of Judgment above.", objectives = "Ride the elevator to the Hall of Judgment.", completion = "This is serious. Their core ideals are in direct conflict.\n\nI fear they will take this duel to the death." }
WordHunterWoW_QuestEN[39687] = { title = "Harbingers of the Past", description = "<name>, you must stop this argument before the damage is irreparable.\n\nKayn and Altruis must be reminded of their common bonds.\n\nThe Pool of Judgment can reflect memories of the past. Touch it, and draw upon your own recollections. \n\nRemind them what it meant to fight under Lord Illidan. Remind them why we took the demon hunter's path.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gaze into the Pool of Judgment." }
WordHunterWoW_QuestEN[39688] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "Kill Bastillax and take his power.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar." }
WordHunterWoW_QuestEN[39689] = { title = "Illidari, We Are Leaving", description = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", objectives = "Speak to Archmage Khadgar.The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", completion = "If you are ready, I will take you to our destination.\n\nAre you prepared to leave?" }
WordHunterWoW_QuestEN[39690] = { title = "Illidari, We Are Leaving", description = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", objectives = "Speak to Archmage Khadgar.The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.\n \nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.\n\nI only ask that you come with me. Further instructions await you on the other side.", completion = "If you are ready, I will take you to our destination.\n\nAre you prepared to leave?" }
WordHunterWoW_QuestEN[39691] = { title = "The Call of War", description = "Today, sorrow grips Stormwind, bastion of the Light. \n\nKing Varian Wrynn has fallen in battle, leaving the crown to his son Anduin.\n\nThe leaders of the Alliance have gathered to pay their respects. No doubt they will have need of your unique skills.\n\nYou will find the king upon the throne of Stormwind Keep, attended by one of your fellow Illidari. I am needed in Dalaran.\n\nGood luck, {name}.", objectives = "Speak to Jace Darkweaver in Stormwind Keep.", completion = "Dark times have fallen upon Stormwind, <name>.\n\nWith King Varian Wrynn slain on the Broken Shore, uncertainty and tension grip the Alliance leaders.\n\nThe timing of this tragedy is no accident. The Burning Legion seeks to sow disorder amongst its enemies, weakening its prey from within.\n\nWe must act." }
WordHunterWoW_QuestEN[39692] = { title = "The Call of War", description = "The Warchief Vol'jin is expecting you.\n\nEnter Grommash Hold straight ahead, and make your introduction.", objectives = "Speak to the Warchief.The Warchief Vol'jin is expecting you.\n\nEnter Grommash Hold straight ahead, and make your introduction.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39693] = { title = "The Path of Huln", description = "The drogbar have a tool of the titans in their possession, and it falls to us to find a way to get around that.\n\nTo that end, I recommend we walk the Path of Huln to the place our people first recovered the hammer so many generations ago.\n\nI have asked for the aid of Brann in this endeavor as there are few in the living world more acquainted with titan artifacts.\n\nThe road is dangerous, and we could use your aid upon it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Escort Spiritwalker Ebonhorn on the Path of Huln." }
WordHunterWoW_QuestEN[39694] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "Kill Bastillax and take his power.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar." }
WordHunterWoW_QuestEN[39695] = { title = "FLAG - Vantus Rune Used", description = "", objectives = "" }
WordHunterWoW_QuestEN[39696] = { title = "Rise, Champions", description = "", objectives = "Highlord, so long as the Order of the Silver Hand stands, we will do everything in our power to destroy the Legion's foothold on Azeroth.\n\nTo succeed, we will need to enlist the best of our order.\n\nLet me be the first to serve, <name>. I will act as your eyes and blade where you are not; I will carry out your will until my dying breath." }
WordHunterWoW_QuestEN[39697] = { title = "Master vs. Commander", description = "I've been doing a little digging - or whatever you call digging in naval terms. Snorkeling?\n\nGul'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul'dan's hands, it could be catastrophic.\n\nScramble the fleet, {name}! Hunt down his infamous flagship, \"The Master's Call,\" and steal that map before they complete their mission. Hurry!", objectives = "Complete the legendary shipyard missions until you defeat the Master's Call and acquire a Draenic Sea Chart.", progress = "I hope the Master's Call hasn't sent too many of your ships to the bottom of the sea...?", completion = "Yes yes, this is it. This map is invaluable. By triangulating these oceanic junction points we can graph out Draenor's key ley lines. Hmmm... there's where I built my tower, of course. Energy also seems to converge near Karabor. And here, by the throne of elements.\n\nOh very good, we'll be able to put this to use very soon." }
WordHunterWoW_QuestEN[39698] = { title = "Making the Rounds", description = "As you can see, we have spared no expense in showing our support of your great quest.\n\nFinal preparations are being made - come, walk with me.", objectives = "Follow Lady Sylvanas Windrunner and prepare her ship to set sail.", progress = "As soon as preparations are complete, we set out for Stormheim.", completion = "Do you understand the gravity of our task? If we do not fight for our future, we will not have one." }
WordHunterWoW_QuestEN[39699] = { title = "Ironhorn Leysmithing", description = "I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares.\n\nThere is also a technique in how you hammer such quantities of leystone that I will instruct you on.\n\nUse our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.", objectives = "Gather scrap metal around the Ironhorn Enclave. Then use the Greenhoof's Anvil and Forge to craft a Scrapmetal Handguard, a Scrapmetal Palmplate, a Scrapmetal Cuffplate, and 1 Scrapmetal Fingerplates.", progress = "I'm waiting, outsider.", completion = "Your hammerwork is solid, outsider. You have separated yourself from the chaff." }
WordHunterWoW_QuestEN[39702] = { title = "Legend of Black Rook Hold", description = "{name}, have you heard of Saris Swifthammer?\n\nHe was a legendary blacksmith amongst the elves of Black Rook Hold. I wonder if any of his research still exists.\n\nI want you to travel there and see if you can discover anything about Saris, or see if he left anything we can research here at my shop.", objectives = "Go to Black Rook Hold and search for Saris Swifthammer.", completion = "Thank you again for freeing me, stranger. I see you wish to discuss the art of blacksmithing." }
WordHunterWoW_QuestEN[39709] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39710] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39711] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39712] = { title = "Mistletoe and Stockings", description = "", objectives = "" }
WordHunterWoW_QuestEN[39713] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39714] = { title = "Where Are the Children?", description = "The children have gone missing!\n\nThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!\n\nOur scouts have spotted him over in Frostfire Ridge.You will receive:", objectives = "Help save the children." }
WordHunterWoW_QuestEN[39715] = { title = "Menacing Grumplings", description = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus.\n\nIf you're able to remove the threat I'm sure rescuing the children won't be much of a problem.You will receive:", objectives = "Remove the grumpling threat." }
WordHunterWoW_QuestEN[39716] = { title = "Smashing Squashlings", description = "The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor.\n\nNow, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.", objectives = "Kill 6 Growing Squashlings.", completion = "I bet it felt great to smash those things! Smash, squish, squash!" }
WordHunterWoW_QuestEN[39717] = { title = "Scouting Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39718] = { title = "Paradise Lost", description = "Archmage Khadgar was planning an expedition to Azsuna - you should seek him out at Krasus' Landing in Dalaran immediately.", objectives = "Speak with Archmage Khadgar at Krasus' Landing in Dalaran.", completion = "Perfect. Up for a little trip down to Azsuna?" }
WordHunterWoW_QuestEN[39719] = { title = "Mutiny on the Boneship", description = "Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet.\n\nThe Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor.\n\nSeek out Bonerender and defeat him, before he sails back into the mist once again.", objectives = "Kill Bonerender.", completion = "Finally, he's returned to the briny deep. I'm sure we'll see him again, but for now let's celebrate!" }
WordHunterWoW_QuestEN[39720] = { title = "Foul Fertilizer", description = "The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked.\n\nThe stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.", objectives = "Destroy 8 kegs of Dread Fertilizer.", completion = "Thinking what goes into normal fertilizer, I don't even want to know what was in THAT stuff." }
WordHunterWoW_QuestEN[39721] = { title = "Culling the Crew", description = "If we're going to protect Draenor from the Bonefleet menace, we'll need to thin out the crew.\n\nSee to a swift reduction in their numbers, and we might just push them back into the sea for another year.", objectives = "Destroy 12 Boneship crew members.", completion = "We're lucky you were around to take care of those bony brutes!" }
WordHunterWoW_QuestEN[39722] = { title = "Forging New Strength", description = "Even the most nefarious Legion lords fear your presence on the battlefield. Yet they are relentless, fashioning ever more terrible horrors and fiends in hopes of countering your might.\n\nHighlord, we must augment your power to maintain our edge over the enemy.\n\nThe altar before you holds within it the essence of the countless heroes of the Light buried in these sacred halls. Place your weapon upon the altar and imbue it with new strength.", objectives = "Imbue your weapon with a new power.", completion = "I will continue beseeching the Light to bolster the power of your weapon.\n\nFor now, its newfound strength should be more than enough." }
WordHunterWoW_QuestEN[39723] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39724] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39725] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39726] = { title = "...And the Anvil", description = "If you truly wish to see my work then you'll have to go and retrieve it as my shop has been raided of everything I've made.\n\nThe breastplates of the Black Rook soldiers were one of my greatest accomplishments. They're light, yet strong and offer great mobility\n\nRelinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.", objectives = "Gather 5 Black Rook Breastplates from the elves of Black Rook Hold.", progress = "Have you acquired any breastplates?", completion = "These pieces will do fine as examples. Now, let me explain how I crafted them..." }
WordHunterWoW_QuestEN[39727] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39728] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39729] = { title = "The Knowledge of Black Rook", description = "You have honored me with your help and now I wish to return those favors to you. On that pedestal there is all my research. Take it with you and learn from it so you may carry on my legacy.\n\nThank you again, {name}.", objectives = "Bring Saris' research back to Alard in Dalaran.", progress = "Were you able to find him?", completion = "This is... this is amazing! There are techniques in here I'd never imagined trying. Good work, <name>!" }
WordHunterWoW_QuestEN[39730] = { title = "Scouting Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39731] = { title = "The Tranquil Forest", description = "Archmage Khadgar sent word about Val'sharah not long ago. It sounds like he has good news.\n\nYou should meet him on Krasus' Landing in Dalaran as soon as you are able.", objectives = "Speak to Archmage Khadgar on Krasus' Landing in Dalaran.", completion = "<Archmage Khadgar smiles.>\n\nI rarely get to say this, but I have good news for you, <name>." }
WordHunterWoW_QuestEN[39732] = { title = "Scouting Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39733] = { title = "The Lone Mountain", description = "Our sources tell us that a Highmountain tauren emissary has recently arrived in Dalaran. We don't know his intentions, but his people could be an invaluable contact in the region.\n\nKhadgar is greeting the emissary at Krasus' Landing in Dalaran - you should seek him out.", objectives = "Speak to Warbrave Oro at Krasus' Landing in Dalaran.", completion = "Greetings champion. I am Warbrave Oro of the Highmountain tauren. I come on the winds of war to find you." }
WordHunterWoW_QuestEN[39734] = { title = "Scouting Mission Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[39735] = { title = "Stormheim", description = "Sky Admiral Rogers has sent word for you to meet her in Dalaran.\n\nShe should be waiting for you in the Violet Citadel. It sounded important.", objectives = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", completion = "It's an honor, <name>." }
WordHunterWoW_QuestEN[39736] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39737] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39738] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39739] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39740] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39741] = { title = "Into Our Ranks", description = "I feel that we should quickly welcome Akama into our ranks. It's important that the others see him treated as one of us, rather than as an outsider.\n\nKor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies.\n\nIt is time to officially raise them up as champions.", objectives = "Recruit Akama and Kor'vas Bloodthorn as your champions.", completion = "Up until now, the Illidari have been a fairly exclusive club. Demon hunters only. But, as you have so clearly demonstrated, my dear, if we are to move forward trusting one-another, then bringing Akama in is an important step.\n\nIt gives one hope.\n\nAnd, of course, making Kor'vas one of your champions is the obvious choice. No one fights as well as she does.\n\nWhat's that?" }
WordHunterWoW_QuestEN[39742] = { title = "Vault of the Wardens", description = "", objectives = "" }
WordHunterWoW_QuestEN[39743] = { title = "Valhallas Heroic Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39744] = { title = "Valhallas Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39745] = { title = "Khadgar Teleport", description = "", objectives = "" }
WordHunterWoW_QuestEN[39746] = { title = "A Ring Unbroken", description = "Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters.\n\nThe elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. {name}, your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever.\n\nJoin me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus' Landing here in Dalaran.", objectives = "Aid the shaman of the Earthen Ring at the Maelstrom. Stormcaller Mylra will fly you there from Krasus' Landing in Dalaran.", completion = "Thank you, <name>. You saved me. You saved us all.\n\nI was... outmatched. My relationship with the elements has changed since the events on Draenor. I have some soul-searching to do. <name>, you must carry the Earthen Ring forward without me. You are the leader they need." }
WordHunterWoW_QuestEN[39748] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39749] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39750] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39751] = { title = "Tracking Quest", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[39752] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39753] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[39756] = { title = "A Sound Plan", description = "The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back.\n\nLet's prove them wrong.\n\nWe've been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault.\n\nOnce you've had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast.\n\nWe will end this madness for good. Light help us all.", objectives = "Select your first assault point on the Broken Isles.", completion = "Good luck out there! We're all in this together." }
WordHunterWoW_QuestEN[39757] = { title = "Keeping Your Edge", description = "Greetings, Deathlord. The blades you hold, while magnificent, have much untapped potential. As you harvest the souls of your enemies their power will continue to grow.\n\nGrand Master Corvus has studied new techniques that may be of use to you, <my lord/my lady>.\n\nYou can find him working the forges on the upper level.", objectives = "Speak with Grand Master Siegesmith Corvus in Acherus.", completion = "Ah this weapon is amazing! Do you see the souls of the damned dancing along its edge? Oh how they scream for release!\n\nYes... in their forms I can see how the blade must be shaped." }
WordHunterWoW_QuestEN[39758] = { title = "Festive Fighters Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[39759] = { title = "Creepy Crawlers Active", description = "", objectives = "" }
WordHunterWoW_QuestEN[39761] = { title = "Advanced Runecarving", description = "I've been working for many years to improve the forges. This weapon will be the perfect demonstration of the Soul Forge, their latest design!\n\nWe can take your artifact to the forge and shape it to make use of the power it contains, provided you've fed your weapon enough souls first. Let's give it a little try, eh?", objectives = "Use the Soul Forge to empower your Artifact.", completion = "Oh yes... that will do nicely!\n\nReturn after you've fed your blade another feast of souls and we will make it the most powerful weapon that's ever existed!" }
WordHunterWoW_QuestEN[39762] = { title = "Feltotem Warlock", description = "", objectives = "" }
WordHunterWoW_QuestEN[39763] = { title = "For Whom the Fel Tolls", description = "<Matthew eyes you up and down, growling slightly>\n\nYou wish me to help you understand this rock? First you do something for me.\n\nThe legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution.\n\nBring me some cores and I'll give you the information you need.", objectives = "Obtain 10 Fel Energy Cores from Wyrmtongue Minions in Suramar. Bring them back to Matthew in Dalaran when you are finished.", progress = "Have you acquired what I requested?", completion = "<Matthew lets out a gleeful howl>\n\nImpressive." }
WordHunterWoW_QuestEN[39764] = { title = "Shiny, But Deadly", description = "Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds.\n\nThose mindless vermin made off with the soul chambers that house our demonic captives.\n\nThe crystals may be shiny, but they're also deadly. If they are damaged in any way, the demons trapped within may escape.\n\nHead into the cave nearby and recover the soul chambers before it's too late.", objectives = "Collect Soul Chambers from kobolds within Mucksnout Den.", progress = "Have you recovered the soul chambers yet?", completion = "Is this all you could find?\n\nWhile I'm grateful to have these gems in my possession once again, it seems that there are still a few missing. I fear they've been broken, which means the demons within have escaped." }
WordHunterWoW_QuestEN[39765] = { title = "Wax On, Wax Off", description = "I've been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head!\n\nHe's down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself.\n\nKill one of their Skullcaptains and recover his Skull of Bossing Around, and they may let you into the cave.", objectives = "Recover the Skull of Bossing Around from the Bluewax Skullcaptain.", progress = "The desecration...", completion = "This will work perfectly, I believe." }
WordHunterWoW_QuestEN[39766] = { title = "Treasure Worm", description = "", objectives = "" }
WordHunterWoW_QuestEN[39767] = { title = "Sleigh and Snowfighters", description = "", objectives = "" }
WordHunterWoW_QuestEN[39768] = { title = "Candle to the Grave", description = "These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on.\n\nI can do nothing to stop them! Please rid this sacred burial ground of the kobold.", objectives = "Slay 7 Bluewax Graverobbers.", completion = "Some of them seem to be digging less enthusiastically, at the very least." }
WordHunterWoW_QuestEN[39769] = { title = "The Gates of Wax", description = "Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.", objectives = "Speak with the Bluewax Gatekeeper and see if he will let you in to meet the Candleking.", completion = "What you want, stinky?" }
WordHunterWoW_QuestEN[39770] = { title = "Burn the Candle at Both Ends [NOT USED]", description = "You no come in yet! You need yellow candle and green candle before let in to Candleking!", objectives = "Acquire the Yellow Candle and Green Candle." }
WordHunterWoW_QuestEN[39771] = { title = "The Voice of Thunder", description = "The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm.\n\nNow you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans.\n\nCome! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!", objectives = "Travel to the Temple of the White Tiger and prove yourself worthy to wield the weapons of storm!", progress = "We have trained our whole lives for this, <name>. We cannot fail.", completion = "You really are the chosen one, <name>. I will gladly lay down my life for you.\n\nWherever you take the Earthen Ring, I will follow!" }
WordHunterWoW_QuestEN[39772] = { title = "Can't Hold a Candle To You", description = "Okay guess you can go say hi to Candleking now.", objectives = "Recover Oenia's Skull from the Candleking.", progress = "Have you found my skull?", completion = "Thank the spirits! These kobolds do not honor their ancestors in the way we do. I can rest peacefully now." }
WordHunterWoW_QuestEN[39773] = { title = "The Soulkeeper's Fate", description = "Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst.\n\nPlease find Uriah. He is the only one who knows how to trap the demons.", objectives = "Find Soulkeeper Uriah within Mucksnout Den.", completion = "Uriah would not want me to waste time with tears. My mourning can wait until the escaped demons are trapped once again." }
WordHunterWoW_QuestEN[39774] = { title = "Demon Detainment", description = "The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail.\n\nI've seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I'll just need you to subdue them first.", objectives = "Weaken demons so Apprentice Rosalyn can trap them within a soul chamber.", progress = "You must weaken the demons so I am able to trap them.", completion = "Thank you for you help, <name>. I will honor Uriah's memory by completing our journey to Azsuna and delivering the demon prisoners to Allari as planned." }
WordHunterWoW_QuestEN[39775] = { title = "Stormforged Grapple Launcher", description = "", objectives = "This looks like one of the grapple launchers the local vrykul use to scale the steep ridges in Stormheim.\n\nThis could come in handy.You will receive:" }
WordHunterWoW_QuestEN[39776] = { title = "Battle Worms", description = "Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation.\n\nThe drogbar are using worms to burrow their way to the surface and deploy their troops.\n\nI am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.", objectives = "Slay Naxa, Arxas, and Xist.", progress = "Worms. Why did it have to be worms? I hate worms.", completion = "That should slow these invaders down." }
WordHunterWoW_QuestEN[39777] = { title = "Buy Us Time", description = "We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers?\n\nI will direct my healers to get everyone that is unable to fight to safety.", objectives = "Slay 10 Mightstone drogbar.", progress = "We need all the time you can buy us.", completion = "Excellent. Thank you, Champion.\n\nWe have managed to get the children and the wounded to safety thanks to your efforts." }
WordHunterWoW_QuestEN[39780] = { title = "The Underking", description = "Mayla already chased the Underking into his cave. That is something we tell our children never to do.\n\nReckless child, but hey, who wants to live forever? Let us join her in battle.", objectives = "Assault Dargrul the Underking.", completion = "Dargrul is just postponing the inevitable." }
WordHunterWoW_QuestEN[39781] = { title = "Neltharion's Lair: Death to the Underking", description = "I will direct my people to clear a path through this rubble and assault Dargrul's forces directly.\n\nIt will be a ruse.\n\nNavarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul.\n\nMuster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz'goroth before that villain brings the mountain down on top of us.\n\nWe will provide the distraction you need to get a shot.", objectives = "Recover the Hammer of Khaz'goroth.", progress = "The war continues.", completion = "It was a hard fight, but necessary. <name>, on behalf of the Rivermane, the Skyhorn, the Stonedark, I thank you for your efforts.\n\nBut where one battle ends, another begins. When you stand against the coming of the Burning Legion, know that the tribes of Highmountain stand with you." }
WordHunterWoW_QuestEN[39782] = { title = "The Exiled Shaman", description = "", objectives = "" }
WordHunterWoW_QuestEN[39783] = { title = "Battle Pet - Terky", description = "", objectives = "" }
WordHunterWoW_QuestEN[39784] = { title = "Beastmaster Pao'lek", description = "", objectives = "" }
WordHunterWoW_QuestEN[39786] = { title = "A Stone Cold Gamble", description = "The second target is a basilisk called Stonefang that lives off the bank of the nearby river. \n\nI put a bigger wager on him, so if you can take him out I'll make sure you get a cut.\n\nI'll need his jaw to verify the kill. Hurry, before those tauren get him first!", objectives = "Collect Stonefang's Jaw from Stonefang in Stonescar Gorge.", progress = "Did you take him out?", completion = "Well, well. I half expected to find your statue on the riverbank. You're gonna get a nice payout once those tauren get back...\n\nYou haven't seen them around, have you?" }
WordHunterWoW_QuestEN[39787] = { title = "Rigging the Wager", description = "Care to help settle a bet, chum?\n\nThose tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn't be able to take out some of the biggest beasts in Stormheim.\n\nIf you take em out before they do, I'll split the wager. Deal?\n\nThe first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he's up pretty high, so you'll need a grapple gun to get there. I think there's one of them layin around here...", objectives = "Lure down and defeat Spitefeather to collect Spitefeather's Beak in the Stormtorn Foothills.", progress = "You got my trophy yet?", completion = "So you took him out, eh? Those tauren are gonna be so jealous when they get back!  \n\nNaturally, you'll have to wait till the tauren get back and pay their wager before I can give you your cut. But in the meantime, I've got another target for you." }
WordHunterWoW_QuestEN[39788] = { title = "The Runewood's Revenge", description = "The Bonespeakers...they are corrupt... hungry for power.\n\nCut them from my woods...", objectives = "Kill 8 Bonespeaker Runeaxes and 8 Bonespeaker Carvers in the Runewood.", progress = "Has the corruption been removed?", completion = "The Runewood will know peace once more with these Bonespeakers removed from the land. \n\nIt is a good beginning." }
WordHunterWoW_QuestEN[39789] = { title = "Eating Into Our Business", description = "Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you.\n\nAs you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels.\n\nI can't take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.", objectives = "Kill 10 Duskpelt worg in Amberfall Mesa.", completion = "Oh, hey! You must be lookin for them tauren was camped here. They just stepped out for a bit, but Snaggle here and I - we can take care of ya!\n\nYou say they were gonna pay you for killin' some worgs, huh? No prob, bub!\n\nI ain't got a lot of gold, but these goods are pretty valuable. Take your pick!" }
WordHunterWoW_QuestEN[39790] = { title = "Infernal Brimstone Theory", description = "I've gone through all the research ye gathered for me and I've come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes.\n\nBut the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown.\n\nIf we're wantin' to test this out, we'll have to get the help of some magic-users.\n\nTake this brimstone back and go see Matthew Rabis. He may know how to breathe life into it.", objectives = "Take the brimstone sample to Matthew Rabis in the Underbelly.\n\nProvided item:", completion = "<Sniff sniff> I smell something...fel." }
WordHunterWoW_QuestEN[39791] = { title = "Lay Them to Rest", description = "I would ask a favor, outsider.\n\nAs you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well.\n\nTake this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.", objectives = "Use the Branch of the Runewood to send 8 weakened Restless Ancestors back to the earth.", completion = "I see you carry a branch of the Runewood. Then it was you who laid the spirits to rest? \n\nThough I do not know your purpose, outsider, I appreciate what you have done for our people." }
WordHunterWoW_QuestEN[39792] = { title = "A Stack of Racks", description = "So while we're waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I'm sure they'd be thankful to have more.\n\nI hear that musken ribs are the specialty here.  The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out!\n\nDon't worry, I'm pretty sure there aren't any dragons over there...", objectives = "Collect 8 Meaty Racks of Musken Ribs from Stout Highland Runehorns in Jotunnwood.", progress = "Aint nothin like some good old meaty musken ribs, eh pal?", completion = "Oh hey, it's... you again! Of course you didn't have any trouble with those musken. You're a big, tough hero after all!\n\nThe tauren still aren't back, though. I'm a bit worried that they may have gone off and hunted a bit more that they can chew.\n\nOh, I'll take those ribs, though. What do you want for em?" }
WordHunterWoW_QuestEN[39793] = { title = "Only the Finest", description = "Say, you're a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I'm sure they'd appreciate it when they got back!\n\nI hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there.\n\nWhy don't you go and fetch some? I'm sure them tauren would pay you handsomely!", objectives = "Collect 18 Patches of Fine Goat Hair from Silvertail Mountain Goats in Nastrondir.", progress = "Make sure to get the good stuff!", completion = "You're back? \n\nI mean... hey, you're back!\n\nWell, the tauren haven't come back yet, but no worries, I'll take that stuff off your hands! Let me show you some of my prime trade goods." }
WordHunterWoW_QuestEN[39794] = { title = "Lord Maxwell Tyrosus Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39795] = { title = "Vindicator Boros Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39796] = { title = "To Haustvald", description = "Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate!\n\nIt is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.", objectives = "Meet with Vydhar in the Runewood.", completion = "Bound... twisted... \n\nThe Bonespeakers..." }
WordHunterWoW_QuestEN[39797] = { title = "Aponi Brightmane Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39798] = { title = "Lady Liadrin Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39799] = { title = "Our Next Move", description = "Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion!\n\nUnder cover of this fog we've been able to send out scouting teams who've put together a fairly comprehensive map of the Broken Isles.\n\nChoose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.", objectives = "Select your order's first assault point.", completion = "A fine choice, Deathlord." }
WordHunterWoW_QuestEN[39800] = { title = "Greymane's Gambit", description = "The Skyfire is prepared to make way to Stormheim. Should we become engaged, I will require my best fighters on the front line.\n\nThis includes you, {class}.", objectives = "Complete Greymane's mission aboard the Skyfire.", completion = "It seems you were spared the brunt of the explosion. If only Greymane were so lucky...\n\nOn your feet! We had better get a move on before the Forsaken are on top of us!" }
WordHunterWoW_QuestEN[39801] = { title = "The Splintered Fleet", description = "Preparations have been made, and we are ready to set sail.\n\nWe must strike out at once. Do not dally, or you will be left behind.", objectives = "Complete Sylvanas' mission to bring the fleet to Stormheim.", completion = "Hey, you're alive! I guess Withers isn't as crazy as I thought.\n\nIt's a miracle you escaped the Skyfire alive! The pieces of that thing must be scattered all over these mountains after that explosion!" }
WordHunterWoW_QuestEN[39802] = { title = "Hartli the Snatcher", description = "", objectives = "" }
WordHunterWoW_QuestEN[39803] = { title = "The Trials Continue", description = "<Havi's voice continues in your head as the raven stares on>\n\nIf valor you seek, then to the bones you must speak! \n\nBut first you must prepare!", objectives = "Meet with Havi in Valdisdall.", completion = "Ah, the hero of the hour! We must waste no time! \n\nOur business at hand is most important if you wish to succeed in your trials!" }
WordHunterWoW_QuestEN[39804] = { title = "Speaking of Bones", description = "The Trial of Valor will be your next test, and test you it will!\n\nBut only a fool fights on an empty stomach. Are you a fool, outsider?\n\nNo? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.", objectives = "Help Havi butcher the moose and learn about your next trial.", completion = "A fine cut, I must say. \n\nYes, you will do well against the Bonespeakers, I think." }
WordHunterWoW_QuestEN[39805] = { title = "Drogbar Spellcaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[39806] = { title = "Crawshuk the Hungry", description = "", objectives = "" }
