WordHunterWoW_QuestEN[39825] = { title = "Stonedark Grotto Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39826] = { title = "Witchwood Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39827] = { title = "Haglands Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39828] = { title = "Horseman and Guards Shared Criteria", description = "", objectives = "" }
WordHunterWoW_QuestEN[39829] = { title = "Sleigh and Guards Shared Criteria", description = "", objectives = "" }
WordHunterWoW_QuestEN[39830] = { title = "Hellfire Citadel: Hellfire and Brimstone", description = "When Khadgar's group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself.\n\nPerhaps there's somethin' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.", objectives = "Gather a group and storm Hellfire Citadel once more. Defeat Archimonde and recover the Infernal Codex.", progress = "Don't go alone, lad. That place is teemin' with demons.", completion = "You actually found something?!\n\n<Mama Diggs thumbs through the codex, a stern look on her face as she reads each page.>\n\nAye, here it is. All the answers are within these pages..." }
WordHunterWoW_QuestEN[39832] = { title = "Plans and Preparations", description = "Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential.\n\nSiouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.", objectives = "Speak to Siouxsie the Banshee.", completion = "Deathlord, I've prepared a brief report on all we've discovered about this new land.\n\nYou should find it quite interesting." }
WordHunterWoW_QuestEN[39833] = { title = "The Ruins of Azsuna", description = "{class}t, I've obtained word that Archmage Khadgar has been able to form a portal that will enable access to the isle of Azsuna. He requests an audience with you at the earliest opportunity.\n\nThe Kirin Tor have also constructed a permanent waygate to enable speedy redeployment of our Knights between here and Dalaran - you can find it on the balcony should you wish to use it.", objectives = "" }
WordHunterWoW_QuestEN[39837] = { title = "An Unworthy Task", description = "This place is Helheim, the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it.\n\nWe should not be here.\n\nWe must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.", objectives = "Search among the caged vrykul in Helheim for one who can help your escape.", completion = "Free at last! \n\nThe kvaldir caught me while I was tryin' to put together a plan to sneak past that foul dog, Guarm, and have had me locked up ever since! \n\nI thought surely my fate was sealed." }
WordHunterWoW_QuestEN[39838] = { title = "Fire!", description = "You! Adventurer! Give us a hand! The wagon's caught fire!", objectives = "Use Camille Kleister's Water Buckets to put out the fire.", progress = "Why are you just staring at me with your mouth hanging open! Give us a hand!", completion = "That was... unexpected. Fel flames? I'd say this warrants further investigation." }
WordHunterWoW_QuestEN[39839] = { title = "Mysterious Dust", description = "Nearly everything in the wagon was obliterated by the fire. All that remains is a small pile of dust.\n\nThe cart belonged to Trader Caelen. Perhaps he knows more about what happened.\n\nAs for the dust - either the inscription trainers or the alchemy trainers might have some insight.", objectives = "Speak with Trader Caelen, Professor Pallin, and Deucus Valdera about the Mysterious Dust.", completion = "This powder... I think I know what this is. I had theorized its existence, but...\n\nHey, Vanessa! You'd better come take a look at this." }
WordHunterWoW_QuestEN[39840] = { title = "The Council's Approval", description = "Those results certainly were disappointing. Calcination is a tricky process, better reserved for alchemists and blacksmiths. Still, I thought we'd get more than a measly TWO GRAINS of obliterum.\n\nFor a more efficient reaction, we'll need a special forge, and to get that...\n\n...we'll need permission from the Council of Six.", objectives = "Speak with Khadgar in Dalaran, and ask for permission to build an Obliterum Forge.", progress = "I am intrigued...", completion = "I like the way you think, <race>. I've long tried to convince the council that winning this war against the Legion means occasionally stooping to their level.\n\nThe Kirin Tor could use more mavericks like you." }
WordHunterWoW_QuestEN[39841] = { title = "Friends in Low Places", description = "My contact is one Oxana Demonslay. She has declined invitation to Dalaran proper, preferring to stay in the sewers of the Underbelly.\n\nIf there is anybody on this rock that knows how to properly build an Obliterum Forge, it is her.\n\nOh, and watch your back while you're down there, <name>.", objectives = "Report to Oxana Demonslay in the Underbelly.", completion = "The archmage sent you? Hmph.\n\nWas he afraid to come down and visit me personally? Or is he worried that the sewer water might touch the hem of his robe?" }
WordHunterWoW_QuestEN[39842] = { title = "One Mage's Trash", description = "I can help you build your forge. I can even supply the metal for it. I do, however, require a few more... difficult-to-acquire components.\n\nI need an alchemical heat source, some sort of insulator, and a calefactor. I'm certain that all of these can be found here in the Underbelly... if the guards are looking the other way.", objectives = "Find a vial of Alchemical Flame, a roll of Spellbound Insulation, and a Decommissioned Calefactor.\n\nThese items can only be obtained while the Dalaran Sewer Guards are off duty.", progress = "Don't let those guards see you. They may be corrupt, but they're vigilant.", completion = "I hope these weren't too much trouble to obtain." }
WordHunterWoW_QuestEN[39843] = { title = "The Muck Stops Here", description = "For my next project - sticking the forge's components to one another - I need a magical adherent. And I've found that the built-up sludge of Dalaran's sewers works perfectly for just that.\n\nIt cakes up on the feet, boots, and slithering bellies of Dalaran's more long-lived residents. Scrape some off and bring it here.", objectives = "Obtain 20 vials of Spellsludge.\n\nSpellsludge can be found on the powerful Underbelly creatures that appear while the Dalaran Sewer Guards are on duty.", progress = "When you live in a sewer, you have to be ready to improvise.", completion = "Let's not make a big deal out of this. You wanted a forge... I'm making one for you. The ends will justify the means." }
WordHunterWoW_QuestEN[39844] = { title = "Cold Hard Coin", description = "I am not interested in gold. Your aboveground currencies have little use down here.\n\nI am, however interested in Sightless Eyes. I will gladly accept some as payment for my services.", objectives = "Obtain 100 Sightless Eyes.", progress = "Sightless Eyes, <name>.", completion = "<The demon hunter accepts the coins.>" }
WordHunterWoW_QuestEN[39845] = { title = "The Obliterum Forge", description = "The components of the forge are assembled and, as I understand it, Archmage Karlain has secured a location for us to begin construction: aboveground, near the blacksmith.\n\nCome back and visit sometime, <name>.", objectives = "Finalize the construction of the Obliterum Forge in Dalaran.", progress = "Let's get a move on, <name>. I am needed at the Violet Citadel.", completion = "Look at the horns on that thing. And glowing eyes?\n\nThose demon hunters sure do have a flair for the dramatic, don't they?" }
WordHunterWoW_QuestEN[39846] = { title = "7.0 Dalaran - Treasure 001 - Burnt Cart", description = "", objectives = "" }
WordHunterWoW_QuestEN[39847] = { title = "Sign This", description = "Ah, a fellow scribe!\n\nYou don't look too dim, so how 'bout you and I work together in an effort to discover what we can about the Broken Isles?\n\n(That's the big mass of islands we're floating over.)\n\nHowever! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we're in business.", objectives = "Sign Professor Pallin's contract.", progress = "Did you remember to cross your t's and dot your lower case j's?", completion = "Hey, look at that, you know how to spell your name correctly.\n\nGood job, now we can begin!" }
WordHunterWoW_QuestEN[39848] = { title = "A Desperate Bargain", description = "It looks like your friend didn't make it. A pity, but we must move on.\n\nYou'll want to plead our case to Helya. She is the ruler here. I would accompany you, but I'm afraid I wouldn't help your case.\n\nMeet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.", objectives = "Confront Helya and ask to be freed from Helheim.", progress = "<The air hangs silent as you approach.>", completion = "<Helya's voice fills the air as you stand>\n\nNobody leaves Helheim without my approval! Entertain me, and I may let you pass." }
WordHunterWoW_QuestEN[39849] = { title = "To Light the Way", description = "Helya must think her challenge unwinnable. We will show her different.\n\nI am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya's minions.\n\nI may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit.\n\nThere is a kvaldir ship nearby. See if you can find one there.", objectives = "Collect a Helheim Waylight from Bloodbeard in Helheim.", progress = "Were you able to secure the lantern?", completion = "This appears to be what we need. \n\nNow, we can prepare for the battle ahead." }
WordHunterWoW_QuestEN[39850] = { title = "Sundered", description = "I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit.\n\nHelya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free.\n\nBe careful, though. It is unlikely that Helya left your spirit fragments unguarded.", objectives = "Find and release the Fragment of Will, Fragment of Might, and Fragment of Valor in Helheim.", progress = "Have you recovered your power?", completion = "Yes, I can feel your power returned. \n\nHelya will regret the day she challenged one such as you." }
WordHunterWoW_QuestEN[39851] = { title = "Allies in Death", description = "Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us.\n\nEarlier, I had discovered several of them being tortured by the elemental forces of Helheim. You may think the dead can't drown, but with Helya's power, this is not the case. \n\nI could not release them then, but now that you possess the waylight, you may be able to.\n\nSeek them out and free them from an eternity of suffering!", objectives = "Release 8 Drowning Valkyra in Helheim.", progress = "Once unbound, my Valkyra will throttle these wretched minions.", completion = "It is good to have my shieldmaidens returned to my side. \n\nYou have gained allies today, but know you have also gained my gratitude." }
WordHunterWoW_QuestEN[39853] = { title = "Victory is Eternal", description = "There is no more cause for hesitation. Now is the time to strike.\n\nWe will defeat this foul behemoth and meet Helya's bargain. The path out of Helheim awaits, outsider. \n\nPrepare yourself.", objectives = "Defeat Geir in the Eternal Battlefield in Helheim.", progress = "Together, we can defeat this foe!", completion = "The day is won. Now, we must collect our reward. \n\nLet us hope that Helya keeps her side of the bargain." }
WordHunterWoW_QuestEN[39854] = { title = "Curse of the Sea", description = "[PH] <You find a strange glowing orb inside the treasure chest. A commanding voice emits from the orb-- it is Odyn.> \n\nVery good, <name>, you've found my orb. The souls of vrykul champions are unrightfully being transported to Helheim. These champions deserve a place in Valhallas, not an eternity alongside that witch.\n\nUse this cleansing orb on the cursed vrykul to free them. If the ship reaches the shores of Helheim before the curse is lifted, they will be doomed to serve an eternity as Helya's kvaldir.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Free cursed vyrkul." }
WordHunterWoW_QuestEN[39855] = { title = "Paid in Lifeblood", description = "We have fulfilled Helya's bargain. Now, we see if she will keep to her word.\n\nWhen you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now.\n\nI will follow your lead, outsider.", objectives = "Confront Helya and leave Helheim.", completion = "So the dead return from Helheim and back? An impressive feat. \n\nYour worth has been judged and the trial passed. \n\nNow, to your destiny. To the Halls of Valor!" }
WordHunterWoW_QuestEN[39856] = { title = "Vignette: Wraithtalon", description = "", objectives = "" }
WordHunterWoW_QuestEN[39857] = { title = "The Eternal Nemesis", description = "<Helya's voice echoes in the sky above the altar>\n\nYou say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? \n\nI cannot, so you must show me.\n\nBring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.", objectives = "Return to Ashildir and inform her of Helya's challenge.", completion = "You do not look good. \n\nI take it Helya did not prove lenient?" }
WordHunterWoW_QuestEN[39858] = { title = "Vignette: Dreadbog", description = "", objectives = "" }
WordHunterWoW_QuestEN[39859] = { title = "Note-Eating Goats", description = "I've followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales.\n\nBut my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle!\n\nHemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft!\n\nI have no hope of becoming a hunter if my manuscript isn't recovered.", objectives = "Recover Addie's manuscript from Sated Hillstriders within Pinerock Basin.", progress = "I've been waitin' all day for Addie to finish her first draft.\n\nHow hard can it be to write a few words about the greatest hunter who's ever lived?", completion = "I've been eager to get my hands on this manuscript! I was startin' to think the gnome had writer's block." }
WordHunterWoW_QuestEN[39860] = { title = "Rite of Blood", description = "Oakin Ironbull vouches for you. He's capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof.\n\nBefore we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me.\n\nEnter the depths of the cave. Defeat whatever foe appears and return to me.", objectives = "Complete the Rite of Blood.", progress = "Are you afraid of the dark?", completion = "Thank you for saving me. I hope now we can trust each other. We must if we are to defeat these Feltotem." }
WordHunterWoW_QuestEN[39861] = { title = "Tying Up Loose Ends", description = "Malfurion Stormrage managed to make landfall in Val'sharah and has already taken care of things there. It seems our fortune is finally turning around!\n\nHe's waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.", objectives = "Speak to Aludane Whitecloud at Krasus' Landing to secure a flight to Val'sharah. Speak to Malfurion Stormrage after you arrive in Lorlathil.", progress = "Highlord <name>! You couldn't have arrived at a better time.", completion = "Elune-Adore, <name>." }
WordHunterWoW_QuestEN[39862] = { title = "The Siegebrul", description = "Worms do not like battle or the surface. They only go where their master tells them.\n\nSo, when in war, kill the master.\n\nSiegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north.\n\nSlay him.", objectives = "Slay Siegebrul Olgrul.", progress = "Siegbrul Olgrul torments all who serve him. There are evil drogbar, and then there is this foul monster.", completion = "\"Siegebrul.\" Bah!\n\nBefore this war we had no need for such titles.\n\nOlgrul was always just a brute who takes pleasure in the pain of others." }
WordHunterWoW_QuestEN[39863] = { title = "Trial By Fel Fire", description = "The substance you hold is something that we call \"obliterum\". We had theorized its existence, but until now, we had never actually been able to produce any.\n\nYou say this came from a fire? Of COURSE! Calefaction! Why hadn't I thought of that sooner?\n\nWe'll need to reproduce these results before we take any further action. I know it's asking a lot, but I'll need you to get me some more high-quality armor, in a variety of styles.", objectives = "Obtain a set of Imbued Silkweave Bracers, Dreadleather Bindings, Gravenscale Armbands, and Demonsteel Armguards.", progress = "You needn't spend money on expensive breastplates or robes. Simple bracers will do.", completion = "You have the bracers? Very good, now stand back..." }
WordHunterWoW_QuestEN[39864] = { title = "Stormheim", description = "Nathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran.\n\nHe should be waiting for you in the Violet Citadel. It sounded urgent.", objectives = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", completion = "<Nathanos glances over at you, pausing for a moment before acknowledging your presence.>\n\nYes?" }
WordHunterWoW_QuestEN[39865] = { title = "A Tiny Scarecrow Costume", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39866] = { title = "Scout Harefoot", description = "", objectives = "" }
WordHunterWoW_QuestEN[39867] = { title = "I'm Not Lion!", description = "I've hunted many exotic beasts in my day, but I've never seen a lion like the one I encountered while scouting the basin.\n\nThe beast's amber eyes locked on mine, luring me closer. I was helpless to this predator's enchanting gaze. It was only when the lion pounced did the stupor break.\n\nI've told Hemet of this magical beast, but he laughs. I'm not lying, {name}! The lion exists.\n\nIf you find the beast, bring me a trophy of your kill, and I'll reward you handsomely.", objectives = "Collect a hunting trophy from the lion that Ellias claims to have seen in Pinerock Basin.", progress = "I'll have the last laugh when Hemet sees proof that this magical lion exists!", completion = "So I was right! The lion with the amber eyes did exist.\n\nHere's the gold as promised. This is worth every copper. You can't put a price on proving that you're right!\n\nI'll keep this eye, but I wouldn't want the rest of our prize to go to waste. Let's eat!" }
WordHunterWoW_QuestEN[39868] = { title = "Neltharion's Lair Heroic Reward Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39869] = { title = "Toll for the Soul", description = "[PH] As foretold, you have arrived... Helya is foolish to think I'll let her ferry me into Helheim. Odyn has already smiled upon me, my soul belongs in Valhallas. \n\nMake no mistake, I am not a prisoner. Before my death Odyn appeared to me in the form of a raven. He praised my battles in life and gave me a quest no vrykul could refuse. The Helerjar arrived... and I let them slay me.\n\nPrisoner-- nay, I am a liberator, sent by Odyn to free the souls of Valarjar.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Helya and free the Valarjar." }
WordHunterWoW_QuestEN[39870] = { title = "Vignette: Soulthirster", description = "", objectives = "" }
WordHunterWoW_QuestEN[39871] = { title = "Huntress Ellandryn", description = "", objectives = "" }
WordHunterWoW_QuestEN[39872] = { title = "The Beastly Boxer", description = "", objectives = "" }
WordHunterWoW_QuestEN[39873] = { title = "I Have a Bad Feeling About This", description = "You have no reason to trust me. My cousins led by Dargrul have gone mad with power.\n\nBut I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain, and that Torok and his Bloodtotem are going to be responsible.\n\nIf you don't believe me, look for yourself at the northern side of Cliff's Edge.", objectives = "Investigate Navarrogg's suspicions.", completion = "<The cage is empty. Navarrogg is gone.>" }
WordHunterWoW_QuestEN[39874] = { title = "Some Enchanted Evening", description = "Welcome! It's nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. \n\nArchmage Starsinger is in charge of the shop, but he's away on Kirin Tor business at the moment. He's a fine fellow... mostly.\n\nYour arrival is fortunate. We've run into a problem that we'd love to solve before the archmage returns. Interested in lending a hand?", objectives = "Speak to Ildine Sorrowspear inside the enchanting shop in Dalaran.", completion = "I'm relieved you've come, <name>. We could certainly use another enchanter in the shop at a time like this." }
WordHunterWoW_QuestEN[39875] = { title = "The Last Few", description = "As you can see, {name}, we're hard at work producing enchants for the battle against the Legion. Since you're here, we could really use your help wrapping up one of our orders.\n\nIf you could, acquire some vellums and start enchanting them with Versatility. Here, I'll teach you the formula.", objectives = "Create 2 Enchant Ring - Word of Versatility vellums for Ildine. You can acquire vellums from a scribe, or from the Auction House.", progress = "Almost done enchanting those vellums?", completion = "<You hand Ildine the vellums.>\n\nAnd that's the last of 'em. Thanks, <name>!" }
WordHunterWoW_QuestEN[39876] = { title = "Helping the Hunters", description = "Now, while I continue to fill the rest of our orders, I'd really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna.\n\nHe and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible.\n\nThanks, {name}!", objectives = "Deliver the crate of vellums to Jace Darkweaver in Azsuna.\n\nProvided item:", completion = "<Jace takes the crate from you and peers inside.>\n\nThe vellums! They're finally here." }
WordHunterWoW_QuestEN[39877] = { title = "In the Loop", description = "We could use your help down here, {name}. Some of our hunters would benefit greatly from having those vellums applied to their rings right now.\n\nHere take a few. I'll give the rest to one of my other soldiers to hand out.\n\nMy hunters probably won't stop to let you apply the enchants, so you'll just have to do your enchanting even if they're in the midst of battle.", objectives = "Use the enchanting vellums on 6 Demon Hunters at the Illidari Stand.", progress = "There's no time to waste. We need to get these enchantments out to as many of my hunters as possible.", completion = "That will certainly help us keep these demons at bay for much longer. We're in your debt, <name>." }
WordHunterWoW_QuestEN[39878] = { title = "Thunder Struck", description = "I've made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power.\n\nSeek out an enchanter named Twaintail and see if he will share his knowledge with us.\n\nTaurens are known for their sharing... right?", objectives = "Speak to Guron Twaintail in Thunder Totem.", completion = "The spirits told me of your coming, outlander. Let us see if you are indeed the hero this land needs.\n\n<The tauren clears his throat.>\n\nPardon me. I know I come off as a bit dramatic. It's just... well, these things have meaning for me." }
WordHunterWoW_QuestEN[39879] = { title = "Strong Like the Earth", description = "There are many types of spirits in this world, {name}. Some benevolent, some troubled.\n\nThey all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards.\n\nThey are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I'll show you what I mean.", objectives = "Defeat Enraged Ambershards and collect \n8 of their Ambershard Crystals. Bring them back to Guron in Thunder Totem.", progress = "Crystals aren't the only thing the spirits respond to. There are others, but that is another tale for another time.", completion = "These will do perfectly for my explanation.\n\n<Guron begins to describe the process of speaking to the spirits and how they interact with the crystal.>\n\nI believe you may have come across another type of crystal: the \"leylight shard\". That crystal works similarly, but resonates with different spirits." }
WordHunterWoW_QuestEN[39880] = { title = "Waste Not", description = "While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste.\n\nI'd like you to retrieve our braves' armor and disenchant them into the components from which they were imbued.\n\nBring me back the reagents so my tribe may use them to enchant new armor.", objectives = "Go to the Crystal Fissure and search for discarded armor. Disenchant the armor and bring back 15 Thunder Dust to Guron.", progress = "To waste what we are given, is to laugh at the spirits who gave it to us to begin with.", completion = "You honor our tribe with your deeds. I will see that this dust goes to good use." }
WordHunterWoW_QuestEN[39881] = { title = "Fey Enchantments", description = "The new dusts and crystals we've found in these lands are fascinating, as I'm sure you've already surmised. I'm positive we can expand their usefulness to more of our armor.\n\nI'd like you to go back out into the field and talk to a dryad in Val'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces.\n\nHer name is Nalamya. You'll find her near the Temple of Elune.", objectives = "Seek out Nalamya near the Temple of Elune in Val'sharah.", completion = "What is it you want, <race>?\n\n\n\nOh, I see now. You're an enchanter.\n\nI warn you though, if you take my enchantments like those foul elves of Black Rook and use them for evil, you shall feel my wrath one way or another." }
WordHunterWoW_QuestEN[39882] = { title = "Darkheart Thicket: The Glamour Has Faded", description = "I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor.\n\nArch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight.\n\nBefore his betrayal, I gave him my book of enchantments to study. I would very much like it back.\n\nI trust you with this task, enchanter. Bring my book back to me.", objectives = "Kill Arch-Druid Glaidalis in the Darkheart Thicket and recover Nalamya's Book of Enchantments.", progress = "If you're truly a friend in this war, then be my sword and strike down Glaidalis.", completion = "You found it? I trust Glaidalis fell in the process?\n\nWhile I feel relieved such a powerful foe has been defeated, I can't help but feel sad for what could have been...\n\nRegardless, you've proven yourself an ally. As a reward, I will teach you one of my enchantments." }
WordHunterWoW_QuestEN[39883] = { title = "Cloaked in Tradition", description = "You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles.\n\nHere, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you.\n\nPerhaps it will serve to help the greater cause of defeating the Legion.", objectives = "Take Guron's Journal to Nalthanis in Dalaran.", progress = "Welcome back, <name>. Did you make contact with the tauren?", completion = "I see you brought back a gift from Highmountain.\n\n<Nalthanis thumbs through the pages.>\n\nThis is fascinating! Look here, <name>, some formulas for cloak enchantments. I believe these would come in handy for us at this point in time." }
WordHunterWoW_QuestEN[39884] = { title = "No Longer Worthy", description = "The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter.\n\nSuch behavior is intolerable... especially after all the help they've received from my folk and the others of this land.\n\nI want you to do me a favor, {name}. Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.", objectives = "Kill night elves within the grounds of Black Rook Hold and collect their Enchanted Raven Sigils. Disenchant the sigils and bring back 8 Raven Dust to Nalamya as proof of their defeat.", progress = "Their behavior was so odd and sudden. It makes no sense why they'd turn their backs on us. Still, it's inexcusable.", completion = "<Nalamya takes the dust from you.>\n\nWell done, <race>." }
WordHunterWoW_QuestEN[39885] = { title = "Demon Hunt: Wingterror Ikzil", description = "We only caught a glimpse of him - the eredar known as Wingterror Ikzil prowls the skies above Val'Sharah.\n\nThe fiend is meeting a small cadre of harpies in a cave on the eastern edge of the Nightmare in Andu'talah not long from now - if you hurry you may be able to ambush him.", objectives = "" }
WordHunterWoW_QuestEN[39886] = { title = "Echoes of the Past", description = "Long ago, the titans created shrines linked to their greatest champions throughout the Broken Isles; legend has it that only those blessed by the Light can activate the immense power within them.\n\nThe device we found may be able to help us locate these shrines, {class}t - you should seek it out before it falls into the wrong hands.", objectives = "" }
WordHunterWoW_QuestEN[39887] = { title = "Call of the Priestess", description = "Priestess Taria has guarded an ancient hidden moon well in the depths of Val'Sharah for centuries, but now the forces of nightmare threaten to corrupt its sacred waters.\n\nHighlord, you should seek her out and help her protect the well. The Nightmare already threatens to overtake the forest; we cannot afford to lose another battle against it.", objectives = "" }
WordHunterWoW_QuestEN[39889] = { title = "Led Astray", description = "The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I've no doubt that the blame for their apathy rests heavily upon their commanders.\n\nI know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home.\n\nGo to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow. Let them be an example for those who can help, but wish to remain cowardly.", objectives = "Go to Black Rook Hold in Val'sharah and slay Trelan Shieldbreaker and Starlys Strongbow.", completion = "Don't worry about proving what you've done for me. I have my own eyes and ears to tell me of your deeds." }
WordHunterWoW_QuestEN[39890] = { title = "Lost Altar of the Lightbringer", description = "We aren't certain, but we believe we've found a long-lost altar to none other than Uther the Lightbringer, first champion of the Silver Hand!\n\nThat altar could hold untold power - you should seek it out and claim it as your own.", objectives = "" }
WordHunterWoW_QuestEN[39891] = { title = "Cursed, But Convenient", description = "I need you to return to Azsuna at once, {name}. I've only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments.\n\nGo to her and see what you can learn at once.", objectives = "Find Enchantress Ilanya at the Crumbled Palace in Azsuna.", completion = "Ah, a fellow enchanter. Come to earn the marks of my subordinates, have you?\n\nIf that's the case, then you may speak with my sentinel and druid. Earn their trust and they'll grant you their marks.\n\nI, however, have a different task for you..." }
WordHunterWoW_QuestEN[39892] = { title = "Stemming the Tide", description = "Highlord, we've found a small village of friendly vrykul who may be willing to work alongside us in Stormheim!\n\nYou'll need to head to their village on the eastern coastline quickly, we encountered several Legion scouts on our way into the area - I suspect an attack is imminent.", objectives = "" }
WordHunterWoW_QuestEN[39895] = { title = "Demon Hunt: Emissary Azathar", description = "The doom guard Emissary Azathar has been meeting with the less-fortunate Highmountain tauren in secret, offering them dark power in exchange for their fealty to his masters.\n\nThe Highmountain are our only allies in the region, Highlord. Azathar must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[39896] = { title = "DEPRECATED: The Ringer", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39900] = { title = "Lost Altar of the Lightbringer", description = "We aren't certain, but we believe we've found a long-lost altar to none other than Uther the Lightbringer, first champion of the Silver Hand!\n\nThat altar could hold untold power - you should seek it out and claim it as your own.", objectives = "" }
WordHunterWoW_QuestEN[39903] = { title = "An Enchanting Home", description = "The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders!\n\nIldine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day!\n\nInvestigating the home might uncover valuable knowledge, {name}.", objectives = "Investigate Tigrid's home in Stormheim.", completion = "So, <race>, you have discovered my home... all that is left of me.\n\nNot even enough to sustain my beloved enchantments..." }
WordHunterWoW_QuestEN[39904] = { title = "Halls of Valor: Revenge of the Enchantress", description = "For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left.\n\nIf you can recover my enchanting rod from the god-king's ghost, I will reward you in kind.", objectives = "Retrieve Tigrid's Enchanting Rod from the Halls of Valor and return it to her in Stormheim.", progress = "The rod is an extension of me, and I of it. It would be nice to hold it once more.", completion = "You have brought back to me my most prized possession. For this I will grant you a bit of my knowledge.\n\nShould you wish to learn more, you only need bring me a few, small components." }
WordHunterWoW_QuestEN[39905] = { title = "Ringing True", description = "While your presence here would continue to be of value to us, your master in Dalaran has called for you.\n\nI'd like to thank you again for all you've done for us. My hunters have been reminded that they're not alone in this war.", objectives = "Return to Nalthanis in Dalaran.", completion = "<name>, you're back. Excellent work down in Azsuna. Jace gave you high praises for your help with his troops and against the Legion.\n\nBefore you go, I wanted to share with you the other new formulas we have for ring enchantments. It would do our side good in this war if you were to share these with your fellow adventurers." }
WordHunterWoW_QuestEN[39906] = { title = "Prepping For Battle", description = "To earn my mark, {class}, you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him.\n\nBefore we go into battle together, I need your help as an enchanter to become stronger. I'm sure by now you have a bevy of enchantments in your repertoire.\n\nMake some for me so that I may become strong enough again to make a difference in this world.", objectives = "Craft an Enchant Cloak - Word of Strength vellum, an Enchant Ring - Word of Critical Strike vellum and an Enchant Ring - Word of Mastery vellum for Alynblaze.", progress = "Once I have the power I need, we shall test both our strengths.", completion = "<Alynblaze takes the vellums from you and applies them to his gear.>\n\nYes! I feel like I can take on the entire Legion now!\n\nWell, that may be a bit of an exaggeration, but I certainly feel up for some battle." }
WordHunterWoW_QuestEN[39907] = { title = "Elven Enchantments", description = "You have earned the marks of my most trusted companions. You have also returned my love to me.\n\nI am fortunate to have met you, {name}.\n\nNow return to your master and let him know of what you have learned.", objectives = "Return to Nalthanis in Dalaran.", completion = "<You tell Nalthanis of your time with the cursed elves and the enchantments you learned.>\n\nThat's fascinating! You managed, through enchantments, to create a bond with those elves and now they may come to your aid?\n\nThose are some truly powerful enchantments you were gifted, <name>. Don't let them go to waste." }
WordHunterWoW_QuestEN[39910] = { title = "The Druid's Debt", description = "In order to grant you my mark, {class}, I must first be made strong enough to come to your aid should you need it.\n\nWithin the ruins of Nar'thalas, my idols sit dormant. As I've said, I'm not strong enough to get them myself.\n\nBut you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home.\n\nFind my idols and return them to me. Do this and I will grant you my mark.", objectives = "Find Merrus' Idol of the Paw, Idol of the Claw and Idol of the Moon and return them to him at the Crumbled Palace.", progress = "Have you found them? Are they still intact?", completion = "<Merrus takes the idols from you and clutches them closely to his chest.>\n\nYou've no idea how long it's been since I've held these. Thank you, <name>.\n\nYou have earned my respect and as promised, you shall have my marks." }
WordHunterWoW_QuestEN[39914] = { title = "Sentinel's Final Duty", description = "Now that I'm stronger, it's time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill.\n\nHis name is Fathom-Commander Eksis. He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows.\n\nI've finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.", objectives = "Slay Fathom-Commander Eksis. Return to Alynblaze at the Crumbled Palace when you are through.", progress = "He will rue the day he ever set foot upon my homeland.", completion = "You fought bravely, <name>. I see that you truly are worthy of my marks and I hereby grant them to you.\n\nPerhaps one day we shall stand again side by side in battle." }
WordHunterWoW_QuestEN[39916] = { title = "Turnabout Betrayal", description = "Enchantress Ilanya remembers me?\n\n<The satyr pauses to wipe a tear away.>\n\nI made a fool's bargain ten millennia ago. I learned of the queen's alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals.\n\nNow the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.", objectives = "Defeat demons at the Felblaze Ingress. Take their Fel-crusted Runes and disenchant them into 5 Dust of Foul Lies. Return to where you met the Fallen Priestess when you are done.", progress = "The death screams of the Legion bring me some semblance of joy.", completion = "After watching these demons helplessly for so long, you have given me a chance to strike back at them!\n\nNow the real work begins." }
WordHunterWoW_QuestEN[39918] = { title = "The Absent Priestess", description = "After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, {name}, I can at last return.\n\nGo and speak to Enchantress Ilanya. I will let her know that you are worthy of my mark.", objectives = "Return to Enchantress Ilanya at the Crumbled Palace in Azsuna.", completion = "You have returned my love to me and for that I am forever grateful.\n\nAs she is with me now, she shall be at your beck and call should you need her. I grant to you her marks." }
WordHunterWoW_QuestEN[39919] = { title = "Imminent Loss", description = "The peaceful Wheathoof tribe are in great danger. Highlord. A Legion assault force is en route to their position - we don't have long before the entire village is lost.\n\nI suggest you embark for their lands immediately while they still have a chance.", objectives = "" }
WordHunterWoW_QuestEN[39920] = { title = "On Azure Wings", description = "I have some exciting news of my own to report, {name}. Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose.\n\nOne of the dragons, Kharmeera, is an enchanter who expressed interest in working with you to perfect some of our enchantments.\n\nI understand you were just down there working with the elves, but if you wouldn't mind returning, Kharmeera would enjoy working with you too.", objectives = "Speak to the dragon Kharmeera at Azurewing Repose in Azsuna.", completion = "I sense the power of enchantments about you, <name>. Yes, I think I will enjoy working with you!" }
WordHunterWoW_QuestEN[39921] = { title = "Neltharion's Lair: Rod of Azure", description = "Before we can begin though, there is a small favor I need to ask of you. I'm rather ashamed about this matter, to be honest, but it must be done in order for us to work together.\n\nWhen I was summoned to this land, I hadn't been given a chance to collect my things. Most importantly, I left behind my enchanting rod.\n\nInstead of retrieving it I believe it would be much simpler to reconstruct it.\n\nHere's what we'll need...", objectives = "Retrieve a Skystone Rod from Dargrul the Underking in Neltharion's Lair, a Radiant Zephyrite from Ozruk in The Stonecore and a pile of Ancient Arkhana from Scholomance.", progress = "How goes the hunt for the rod components?", completion = "Oh yes, that seems to be everything.\n\n<Kharmeera takes the components from you and assembles the rod.>\n\nNow, let's see what I can share with you." }
WordHunterWoW_QuestEN[39923] = { title = "Down to the Core", description = "The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings.\n\nAccording to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City.\n\nIf you were to gather some friends and defeat these constructs, you could take their cores for us to study.", objectives = "Retrieve the Power Cores from Oldus, Or'ell, Olmoore, and Oll'ison. Bring them back to Kharmeera when you have all four.", progress = "Remember to bring some friends with you, those constructs are incredibly powerful.", completion = "I'm truly amazed at what you're able to accomplish for such a young creature.\n\nShall we get to work then on learning from these cores?" }
WordHunterWoW_QuestEN[39925] = { title = "Emissary Azathar Looted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39926] = { title = "Lord Malus Looted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39927] = { title = "Wingterror Ikzil Looted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39928] = { title = "Uther's Spirit Honored", description = "", objectives = "" }
WordHunterWoW_QuestEN[39929] = { title = "Uther's Spirit Honored", description = "", objectives = "" }
WordHunterWoW_QuestEN[39930] = { title = "Uther's Spirit Honored", description = "", objectives = "" }
WordHunterWoW_QuestEN[39931] = { title = "Smashing Herbs", description = "Now that the formalities are out of the way, let's have you do something actually useful.\n\nOn the islands below, there's a plethora of new and exotic herbs that we've yet to experiment with.\n\nI'd like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I'll see what you've come up with.", objectives = "Obtain 20 Roseate Pigments and 2 Sallow Pigments. Pigments are obtained by milling herbs.", progress = "Well? Do you have the pigments, or are you just wasting my time?", completion = "Yes, these pigments look like they will do the trick. Well done, student.\n\nIn fact... I've been researching a new glyph that these pigments would work splendidly with. Why don't you give it a shot?" }
WordHunterWoW_QuestEN[39932] = { title = "Fish Ink", description = "You know, herbs aren't the only ways to obtain ink. Other materials can be inkified.\n\nSlightly related! I've been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I.\n\nTo do so, we'll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.", objectives = "Obtain 5 Mak'rana Oil, 5 Hatecoil Naga Oil, and 5 Salteye Oil, then combine them into a Piscine Pigment.", progress = "My pigment?", completion = "Holy mackerel! This stuff really puts the \"ink\" in \"stink\", doesn't it?" }
WordHunterWoW_QuestEN[39933] = { title = "The Card Shark", description = "We have the pigment, but we still require one more ingredient.\n\nVisitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.", objectives = "Collect 10 Hearthstone Cards at the Legerdemain Lounge.", progress = "The cards are just for reference, mostly...", completion = "And there we have it. Just as good as those witless Darkmoon cretins.\n\nWhile we owe this success almost exclusively to my genius, I feel you ought to be rewarded for doing the legwork. Here's the recipe for my newest masterpiece." }
WordHunterWoW_QuestEN[39934] = { title = "Our New Allies", description = "Have you seen those demon hunters yet? I'm not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them.\n\nEverybody needs glyphs, you know.\n\nGo see what you can discover about them. Azsuna is as good a place as any to start.\n\nPerhaps my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", objectives = "Go to Azsuna and find Allari the Souleater.", completion = "Are you here to reinforce us, <class>? We could always use your strength." }
WordHunterWoW_QuestEN[39935] = { title = "The Price of Power", description = "You wish to learn what it is to be a demon hunter? That may take some time.\n\nThe first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them.\n\nReturn to me when you are finished.", objectives = "Slay 15 demons at Illidari Strand.", progress = "Have you seen enough?", completion = "Some may condemn our methods. We simply do what we must to destroy the Burning Legion." }
WordHunterWoW_QuestEN[39936] = { title = "Inscription of the Body", description = "We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do.\n\nUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.", objectives = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", completion = "Allari sent you? I am about to start a ritual. I could use you, stranger.\n\nYou seem more ally than enemy. In this time, allies are more important than ever." }
WordHunterWoW_QuestEN[39937] = { title = "Opposites Repel", description = "There's a balance that must be struck, {name}, when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature.\n\nFel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check.\n\nYou are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.", objectives = "Collect 10 Ley Dust from the nightfallen and withered in the Ley-Ruins of Zarkhenar, then mix it into a Ley Pigment.", progress = "Even though they are opposites, one can not exist without the other.", completion = "If you can believe it, that was the easy part. The next part will be a bit more challenging\n\n...at least, for me it will." }
WordHunterWoW_QuestEN[39938] = { title = "Containing the Demon Within", description = "Now that we have all the essential pieces, let's begin the ritual.\n\nI'll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", objectives = "Assist Baric in completing the ritual.", completion = "It is done. I fear that if I had waited any longer to improve my wards, the demon in me may have taken over.\n\nThank you again, <name>." }
WordHunterWoW_QuestEN[39939] = { title = "Scribal Knowledge", description = "We do not simply fight the demons, {name}. We observe them.\n\nOne of my best demon hunters, Zaria Shadowheart, is currently gathering intel on the demons in Felblaze Ingress.\n\nGo to her. She will teach you what she has learned from the demons invading that region.", objectives = "Find Zaria Shadowheart near the Felblaze Ingress in Azsuna.", completion = "Allari has sent you to learn from me? In that case, I have much to tell." }
WordHunterWoW_QuestEN[39940] = { title = "Runes of Power", description = "Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again.\n\nStudy these runes.", objectives = "Study 8 Fel Power Runes.", completion = "As I'm sure you sensed, these runes hold quite a bit of energy.\n\nGreater knowledge of the Legion is your best weapon against it." }
WordHunterWoW_QuestEN[39941] = { title = "Control is Key", description = "We demon hunters ritualistically remove our eyes in order to see the demons more clearly.\n\nDown below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check.\n\nDestroy his warding crystal, then slay him.", objectives = "Destroy the crystal protecting Overseer Felorax, then slay him.", completion = "I commend you, scribe. You would make an excellent demon hunter.\n\nTake this ink as payment for your efforts. I have no need of it." }
WordHunterWoW_QuestEN[39942] = { title = "Aethrem Crystal", description = "<Most aethril has a sharp crystalline fiber in the center of the bloom, but this one is particularly well-developed.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "Bring the Aetherem Crystal to Professor Pallin in Dalaran.\n\nProvided item:", completion = "A crystal... inside the flower? That gives me an idea.\n\nI dabbled in jewelcrafting in my younger years. Take a look at this technique..." }
WordHunterWoW_QuestEN[39943] = { title = "The Burdens of Hunting", description = "There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.", objectives = "Report back to Professor Pallin.", completion = "<Professor Pallin looks over the demon hunter glyphs you've designed.>\n\nHuh! Apparently I don't have to hold your hand as much as I thought.\n\nLook at this glyph you've made right here. If you flip this symbol around, and adjust the stroke width here..." }
WordHunterWoW_QuestEN[39944] = { title = "Mysterious Messages", description = "The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they're written in ancient vrykul, but I lent my codex to one of my students, so I'm unable to decipher them here.\n\nHis name is Nicholo Swiftfuse, and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated.\n\nThat is all.", objectives = "Deliver the tablets to Nicholo Swiftfuse in Stormheim.", completion = "Seriously? Pallin wants me to do what now?!\n\nThat old bag of wind thinks he's so great, but he's always making me do all his work. It's a surprise I'm not running that shop.\n\nBut fine, I'll help you. As long as you help me too." }
WordHunterWoW_QuestEN[39945] = { title = "Runes Within the Ruins", description = "Unfortunately, Pallin's codex isn't complete. There are many symbols here that simply cannot be deciphered with what we've learned.\n\nLooks like we'll need to go and collect more tablets down in the area that the vrykul call Haustvald.", objectives = "Collect 10 Ancient Vrykul Rune Tablets within Haustvald.", progress = "We need those tablets if we're to progress any further in deciphering their language.", completion = "I believe these have enough information for us to finish the codex. Excellent work, <name>.\n\nIf you don't mind me saying, it's nice to finally not be the one running errands." }
WordHunterWoW_QuestEN[39946] = { title = "Right Tool for the Job", description = "From what little I have been able to decipher, I know that the tablets are created using a special carving tool.\n\nIf we had one of those tools, along with a complete codex, we could easily create our own tablet.\n\nThat would also serve to prove that my deciphering of their language has been successful.\n\nRetrieve one of those tools for me, {name}.", objectives = "Acquire a Runic Bone Knife.", progress = "The knife is the final key to my research. Any luck finding one?", completion = "Wow. It's much... bigger than I had expected.\n\nThen again, vrykul are very large and I'm... well, I am not.\n\nStill though, I believe I can work with this." }
WordHunterWoW_QuestEN[39947] = { title = "Not So Complex?", description = "Alright, I believe I've finished adding the missing entries into the codex. And we have the machete... err, knife.\n\nAll that's left is to make our own tablet and verify my other suspicion about these tablets:\n\nI believe that they're not just simple texts, but a sort of magical device.", objectives = "Assist Nicholo with the creation of a rune tablet.", completion = "It was a good thing you were here to help me with that.\n\nI surely would have been killed by those spirits!" }
WordHunterWoW_QuestEN[39948] = { title = "The Ink Flows", description = "{name}, I need you to make a quick delivery for me.\n\nYes, I've learned by now that such trivial tasks are beneath your skills... but I'm rather busy right now and we both know my time is much more important than yours.\n\nDeliver these contracts to Raethan, the Guard Captain in Dalaran's Underbelly.", objectives = "Deliver the contracts to Raethan in the Underbelly.", completion = "These all seem to be in order.\n\nIf you have a moment, scribe, I have a proposition for you that you may be interested in..." }
WordHunterWoW_QuestEN[39949] = { title = "Once a Scribe Like You", description = "These sewers are something of a... \"settling place\" for many who can't cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract.\n\nHis name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad.\n\n<Raethan hands you the contract.>\n\nThis says he's stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.", objectives = "Kill Inkrot and obtain the Stolen Shadowruby.", progress = "Did he give you much trouble?", completion = "You, <name>, are a godsend. I thought I'd never be rid of that nuisance.\n\nAs promised, here is the bounty for the contract." }
WordHunterWoW_QuestEN[39950] = { title = "An Odd Trinket", description = "Wait, {name}, before you leave... did you not notice this?\n\n<Raethan peels a small piece of paper from the bottom of the jewel.>\n\nThis wasn't reported stolen. It appears to be a card of some kind. Must be a scribe thing.\n\nPerhaps it may be of some use to you.", objectives = "Give the Rotting Tarot Card to Professor Pallin.", progress = "What's that you have there?", completion = "I... I know this work. My old apprentice, what's-his-name, was trying to prove he could create something as great as I could.\n\nImpressively, he seemed to have succeeded in this one case.\n\nWe should learn from what he created and make our own, less putrid version." }
WordHunterWoW_QuestEN[39951] = { title = "Roseate Essence", description = "<The pigment milled from this flower is of an exceptionally high quality.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "Bring the Roseate Essence to Professor Pallin in Dalaran.\n\nProvided item:", completion = "How did you get an extract so pure? Show me exactly what you did, step by step.\n\nFascinating. Do you mind if I write this down, so I can show my other students?" }
WordHunterWoW_QuestEN[39952] = { title = "Sallow Essence", description = "<The felwort is reduced to a thick, clotted pigment. While all felwort-begotten pigment is somewhat offensive, this batch practically glows with a malevolent energy.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "Bring the Sallow Essence to Professor Pallin in Dalaran.\n\nProvided item:", completion = "We've ventured into undiscovered territory, <name>. There isn't anyone out there in ANY academic circles I'm aware of that is milling felwort this effectively.\n\nWell done, student. Or, should I say... well done, junior deputy assistant scribe?\n\nNah... I still prefer \"student\"." }
WordHunterWoW_QuestEN[39953] = { title = "Halls of Valor: Vision of Valor", description = "I think it's time for another field trip, {name}. To the Halls of Valor!\n\nThe Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.", objectives = "Retrieve 5 Valarjar Rune-Sigils from the Halls of Valor.", progress = "Did you see any gods while you were there?", completion = "My stars... these are very nice indeed! In fact, this gives me an idea..." }
WordHunterWoW_QuestEN[39954] = { title = "Mass Milling Techniques", description = "A number of my previous students have been vocal in their displeasure regarding milling. They find the process \"repetitive\", \"mindless\", and even \"painful\". Have they no respect for the time-honored traditions of inscription?\n\nI suppose you count yourself among their number. Am I right? Very well. You've been a fine student so far, so I suppose there's no harm.\n\nI have a book about mass milling somewhere around the shop here. Find it, and it's yours.", objectives = "Find The Masterful Miller's Manual in Dalaran's inscription shop.", progress = "Try not to make too big a mess.", completion = "That's it! Hmm... let's see...\n\n<Pallin looks quickly through the pages of the old book.>\n\nNot much in here that will help you with our Broken Isles herbs.\n\nWait, hold that thought. Look at this here..." }
WordHunterWoW_QuestEN[39955] = { title = "The Plot Thickens", description = "Very well, I won't deny it. The Steamy Romance Novel is mine.\n\nI only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s!\n\nIn fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge.\n\nStop reading, student. You are dismissed. And give me my book back!", objectives = "Go to Ironforge and look for B. Spearshaker.", completion = "Hello! Ye must be one of me many fans here for an autograph.\n\nOh, yer here about the romance novels, are ye? I see ye've discovered my little secret.\n\nYe know, I've grown tired of writing those. I've moved on, ye see. Wrote me last one yesterday.\n\nBut perhaps ye'd like to carry on the tradition...?" }
WordHunterWoW_QuestEN[39956] = { title = "The Legacy Passed On", description = "I've lost my passion, scribe. I just can't get into the voice o' the characters anymore.\n\nTake a look at that unfinished book over there on the table. I can't seem to finish it. Maybe ye'll have an easier time with it.", objectives = "Complete the Unfinished Steamy Romance Novel.", progress = "Dang-blasted writer's block!", completion = "Hmm... yes, ye seem to have gotten the hang of it. I particularly like that line: \"Oh, Lord Gravesbane!\" That would make a nice catchphrase...\n\nHere, take this list o' story prompts. I certainly don't need them anymore." }
WordHunterWoW_QuestEN[39957] = { title = "Demon Ink", description = "These sigils would make for a fantastic new tarot card. Quite powerful, in fact. We simply require an ink sturdy enough to inscribe them.\n\nFortunately, I have students like you that excel at fetching hard-to-get items.\n\nFor this project, I require ink mixed from demonic blood. The blood of the demons at Felsoul Hold will serve as a suitable base. You will also need Blood of Sargeras, of course.", objectives = "Collect 25 Vials of Felsoul Blood and 1 Blood of Sargeras, then mix them into Felsoul Ink.", progress = "If you're unsure where to get demon blood, go to Suramar and look around. You're bound to trip on a demon sooner or later.", completion = "This is more than enough. Excellent work!\n\n<Professor Pallin produces a small quill, dips it in the ink and begins scribbling on a small card.>\n\nJust as I thought, easy enough to make.\n\nAs is usually the case with tarot cards, you'll have to make a complete set in order for them to yield their full potential." }
WordHunterWoW_QuestEN[39958] = { title = "Skin Deep", description = "Welcome, {name}. It's an honor to be working with someone of your caliber.\n\nIn order for us to begin our work together, we'll first need to collect some materials.\n\nThe Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We'll need scales to make mail armor with as well.\n\nGo and collect some materials for us so we may begin working.", objectives = "Acquire 20 Stonehide Leather and 5 Stormscales. If you are not a skinner, you may acquire them from the auction house or other players.", progress = "I trust you gave the creatures a merciful death?", completion = "These materials have my mind racing. I can't wait to see what we can make with them!\n\nI'm just going to keep some to study. You can have the rest back." }
WordHunterWoW_QuestEN[39959] = { title = "The Plot Thickens", description = "Very well, I won't deny it. The Steamy Romance Novel is mine.\n\nI only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s!\n\nIn fact... you might benefit from a penmanship lesson. The author of these books is one F. Serbacon. I believe he can be found in the library in Undercity.\n\nStop reading, student. You are dismissed. And give me my book back!", objectives = "Go to the Undercity and look for F. Serbacon.", completion = "Come for an autograph, have you? Very well, you may present your chest to me.\n\nOh, you're here about the romance novels? I see you've discovered my little secret.\n\nYou know, I've grown tired of writing those. I've moved on, you see. Wrote the last one yesterday.\n\nBut perhaps you'd like to carry on the tradition...?" }
WordHunterWoW_QuestEN[39960] = { title = "The Legacy Passed On", description = "I've lost my passion, scribe. I just can't find the voice of my characters anymore.\n\nTake a look at that unfinished book over there on the table. I can't seem to finish it. Maybe you'll have an easier time with it.", objectives = "Complete the Unfinished Steamy Romance Novel.", progress = "Confound this accursed writer's block!", completion = "Hmm... yes, you seem to have gotten the hang of it. I particularly like that line: \"Oh, Lord Gravesbane!\" That would make a nice catchphrase...\n\nHere, take this list of story prompts. I certainly don't need them anymore." }
WordHunterWoW_QuestEN[39961] = { title = "An Embarrassing Revelation", description = "This doesn't appear to be an inscription textbook at all... it's more of a steamy romance novel. The pages are just FILLED with tawdry tales of carnality.\n\nCould it have something to do with inscription? Either way, Professor Pallin should be confronted.", objectives = "Bring the Steamy Romance Novel to Professor Pallin.", completion = "Get your hands off of... err, I mean... that's not my...\n\nWhere did you...\n\n<The professor makes a sputtering sound.>\n\nSomeone must be playing a trick on me!" }
WordHunterWoW_QuestEN[39962] = { title = "Trouble for Okuna", description = "<You open the bottle and find a message inside.>\n\nHelp! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard.\n\nI was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!", objectives = "Search for Okuna Longtusk." }
