WordHunterWoW_QuestEN[39978] = { title = "Meet the Recruits", description = "Highlord, my mission in Dalaran was successful. I have recruited paladins truly worthy to carry your banner.\n\nThey await your return at the Sanctum of Light.", objectives = "Use the Guiding Light spell to return to Light's Hope Chapel." }
WordHunterWoW_QuestEN[39979] = { title = "DEPRECATED", description = "Archmage Khadgar sent word about Val'Sharah not long ago.\n\nHis Kirin Tor have opened a gateway between here and Dalaran - you can find it in the alcove behind you if you wish to make use of it, Highlord.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Archmage Khadgar in Dalaran.Archmage Khadgar sent word about Val'Sharah not long ago.\n\nHis Kirin Tor have opened a gateway between here and Dalaran - you can find it in the alcove behind you if you wish to make use of it, Highlord.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[39980] = { title = "Highlord Darion Mograine Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39981] = { title = "Thassarian Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39982] = { title = "Koltira Deathweaver Slotted", description = "", objectives = "" }
WordHunterWoW_QuestEN[39983] = { title = "Huln's War - The Arrival", description = "Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes.\n\nLive his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.", objectives = "Defeat 25 Legion.", completion = "[In broken Common] Feathered one said you come. Unng Ak not hope for you come. Tauren have thanks." }
WordHunterWoW_QuestEN[39984] = { title = "Remnants of the Past", description = "<The journal entry appears hastily written.>\n\nI do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed.\n\nSome have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return.\n\nIn these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well.\n\nI do not know what will become of me. For now, I can only stay at my post and remain vigilant.", objectives = "Locate clues to discover the fate of Tideskorn Harbor.", completion = "The mists of this bay rot not only the wood of the ships, but the very souls of its inhabitants.\n\nBut it seems you have already discovered this." }
WordHunterWoW_QuestEN[39985] = { title = "Khadgar's Discovery", description = "Champion! Please come to the Violet Citadel immediately.\n\nI have made a discovery that I would like to share with you before the Council of Six.", objectives = "Speak with Archmage Khadgar in Dalaran.", completion = "Thank you for coming, <name>." }
WordHunterWoW_QuestEN[39986] = { title = "Magic Message", description = "For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was.\n\nThat barrier has come down.\n\nSince then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern.\n\nA spell, encrypted among the chaos.\n\nI have recreated the spell here. It's not dangerous, but beyond that... I have no idea what it does!", objectives = "Examine the Arcane Anomaly in Dalaran.", progress = "Go ahead and take a look.", completion = "A magical message in a bottle, slipped right beneath the Legion's nose... Clever." }
WordHunterWoW_QuestEN[39987] = { title = "Trail of Echoes", description = "The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can.\n\nWe should be able to find her by tracking her magical echoes, the same way I found her distress call.\n\nI can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself.\n\nMy wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.", objectives = "Use Khadgar's Wand to find Arcane Echoes and track down First Arcanist Thalyssra.", progress = "Who are you?", completion = "An outlander...\n\nYou received my message?" }
WordHunterWoW_QuestEN[39988] = { title = "Huln's War - Stormrage", description = "<Eche'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>", objectives = "Meet Malfurion.", completion = "You bring with you Eche'ro, and... what is this? The blessing of Cenarius?!" }
WordHunterWoW_QuestEN[39989] = { title = "Keepers of the Hammer", description = "High Chieftain Ulan has requested your presence.\n\nWe have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid.\n\nOur people have in our possession a great titan relic: the Hammer of Khaz'goroth.\n\nWe intend to lend it to you for this task.\n\nWhen you are ready, join me at our stronghold of Thunder Totem in Highmountain.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Meet the High-Chieftain at Thunder Totem in Highmountain." }
WordHunterWoW_QuestEN[39990] = { title = "Huln's War - Reinforcements", description = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed.\n\nBut now, I ask for your help, Huln Highmountain. I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.", objectives = "Defend Malfurion.", progress = "This shouldn't take long. Please do not allow them to interrupt my spell.", completion = "The ritual is complete. Reinforcements will be able to push through the portal and assist against the demonic horde." }
WordHunterWoW_QuestEN[39991] = { title = "Blessing of Cenarius", description = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle.\n\nSpeak with him in the grove to the south.", objectives = "Meet with Cenarius.Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle.\n\nSpeak with him in the grove to the south." }
WordHunterWoW_QuestEN[39992] = { title = "Huln's War - The Nathrezim", description = "I am fully occupied here organizing my troops and planning for the battle to come.\n\nWhile I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain.", objectives = "Defeat Tichondrius.", completion = "You see now, that Huln was mighty? He united the tribes and defeated terribly powerful foes." }
WordHunterWoW_QuestEN[39993] = { title = "Abandoned Fishing Pole", description = "", objectives = "" }
WordHunterWoW_QuestEN[39994] = { title = "Crab Rider Grmlrml", description = "", objectives = "" }
WordHunterWoW_QuestEN[39995] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39996] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39997] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[39998] = { title = "Drive Back the Tideskorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[39999] = { title = "Rockaway Coast Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40000] = { title = "A True Hunter", description = "I don't know why Hemet hunts with Razik. His contraptions are unreliable at best! \n\nA true hunter doesn't need gadgets to hunt. They rely on instinct, skill, and agility.\n\nSo tell me, {name}, do you have the skills of a true hunter? Better yet, prove it.\n\nTake down some of the Bonebeak Hawks that circle the nearby meadow.", objectives = "Prove you're a worthy hunter by hunting Bonebeak Hawks in Sunfrost Glade.", progress = "You can't be huntin' hawks if you're here chattin' at me.", completion = "Now that's how a real hunter does it." }
WordHunterWoW_QuestEN[40001] = { title = "Knocking on Valor's Door", description = "The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness.\n\nYour dragon allies have come to Halls' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir.\n\nFree your dragon friend, champion, and wash the Felskorn from the Gates of Valor!", objectives = "Find Vethir in the Felskorn Camp.", completion = "What is this... I see? \n\nA friendly face... in a sea of foes?" }
WordHunterWoW_QuestEN[40002] = { title = "A Familiar Fate", description = "We had come to defend the Halls of Valor... I was taken from the sky...\n\nI cannot break free of my bindings. Find the jailer who made this cell...\n\nSet me free, friend...", objectives = "Collect the Jailer's Shard from Dravax and free Vethir from his prison.", progress = "The jailer has... the key...", completion = "You still manage to surprise me, outsider. Your trials are complete, and yet you still have challenges to face. \n\nThe God-King's forces are many, but in your weapon you possess the powers of Stormheim herself! Approach the gates, and these powers will lay low the enemies of this land!\n\nNow, let us take the fight to the God-King, and cleanse the Gates of Valor of his fel taint!" }
WordHunterWoW_QuestEN[40003] = { title = "Stem the Tide", description = "Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. \n\nIf we wish to stem this tide, these portals must be destroyed. \n\nI will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!", objectives = "Use the Stormforged Horn to destroy the three Felbound Portals in Gates of Valor.", progress = "The portals must be closed if we wish to stop Skovald's forces!", completion = "I do not understand, the portals are closed and yet Skovald's demonic forces still assault the gates! \n\nWe must find where they are coming from!" }
WordHunterWoW_QuestEN[40004] = { title = "Break the Spine", description = "To lead his tainted forces,  the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders.\n\nThese demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. \n\nTake them down, and shatter the spine of Skovald's offensive!", objectives = "Defeat Garzareth, Karuas, Muorg and Ravathes in Gates of Valor.", progress = "Are the leaders slain?", completion = "With their fel leaders slain, the God-King's forces will scatter. \n\nStill, we are not finished here. So long as the demons continue to assault the gates, Stormheim will not be safe." }
WordHunterWoW_QuestEN[40005] = { title = "Stormheim's Salvation", description = "It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor's edifice, summoned by the God-King himself!\n\nI cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat!\n\nFor Stormheim!", objectives = "Defeat God-King Skovald in the Gates of Valor.", completion = "It's unfortunate that the God-King escaped, but his defeat has stemmed the flow of the Legion into Stormheim.\n\nNow, the Halls of Valor await you." }
WordHunterWoW_QuestEN[40006] = { title = "Sylvan Falls Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40007] = { title = "Fields of An'she Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40008] = { title = "The Only Way Out is Through", description = "I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever.\n\n<Thalyssra lifts a delicate flask to her lips. Her eyes shimmer as she takes a sip.>\n\nIf we push through, we may find shelter up ahead.", objectives = "Escort Thalyssra to safety.", progress = "There is no turning back.", completion = "You fight well.\n\nPerhaps it is time for a proper introduction." }
WordHunterWoW_QuestEN[40009] = { title = "Arcane Thirst", description = "My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there.\n\n<Thalyssra holds her flask aloft, gently shaking free the last precious drops.>\n\nI'm afraid I have been rather reckless today. \n\nAlready, my senses are dulling. Without magic to feed upon, I will turn. \n\nPlease... find me something to feed upon... anything...", objectives = "Enter Shal'Aran and find something to sate Thalyssra's thirst.", progress = "<Thalyssra's eyes have dulled and her body is shaking uncontrollably.>", completion = "<Thalyssra takes the crystals with a trembling hand.>" }
WordHunterWoW_QuestEN[40010] = { title = "Tapping the Leylines", description = "The arcways were built to tap into the magical leylines beneath Suramar. As we learned to subsist on the Nightwell, the old facilities fell out of use.\n\nThis chamber is clearly receiving power from elsewhere.\n\nThere is only a trickle now, but if you can direct more leyline energy here it will help to sustain us.\n\nThe closest source is to the north, near Anora Hollow.", objectives = "Explore Anora Hollow and find the Ley Station there.", completion = "And just who might you be?" }
WordHunterWoW_QuestEN[40011] = { title = "Oculeth's Workshop", description = "We need to make contact with Chief Telemancer Oculeth, the man who developed Suramar's teleportation network. \n\nOculeth had a workshop in old Suramar, from the age before the Sundering. He may be taking refuge there.\n\n<Thalyssra presses a small coin into your palm.>\n\nIf you find him, show him this. Hopefully you see him before he sees you...", objectives = "Give the First Arcanist's Token to Chief Telemancer Oculeth.", progress = "If we are to put up any resistance against the combined forces of the Legion and the Grand Magistrix, we must secure a means of traversing the region quickly.", completion = "You may deliver me to Thalyssra once my work here is complete." }
WordHunterWoW_QuestEN[40012] = { title = "An Old Ally", description = "I was on my way to Ambervale in hopes of finding an old colleague.\n\nArcanist Kel'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them.\n\nWhen one of his subjects escaped and ran amok in the royal gardens, Kel'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled.\n\nIf Kel'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.", objectives = "Find Arcanist Kel'danath's hideout in Ambervale.", completion = "<Somebody has been living here recently. This scroll bears strange lettering that glows warmly, beckoning your hand.>" }
WordHunterWoW_QuestEN[40013] = { title = "Aethril Sample", description = "This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "Bring the Aethril Sample to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "From the look of it, I would expect such an herb to be fragile and delicate, but... it's quite sturdy.\n\nOooh, look at these!" }
WordHunterWoW_QuestEN[40014] = { title = "Spayed by the Spade", description = "The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together.\n\nI suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts.\n\nStill, it looks like this bloom has been damaged. I need undamaged parts if I'm to be sure.", objectives = "Obtain a Pristine Pistil and a Stainless Stamen.", progress = "It may seem wrong to remove these most... \"intimate\" flower parts, but do not fret. They will grow back.\n\nMuch like the parts of a troll.", completion = "<Your trainer looks over the pistil and stamen, clearly impressed.>\n\nThe Earthmother must have been feeling generous when she created the aethril.\n\nContinue to focus on this part of the flower, <name>." }
WordHunterWoW_QuestEN[40015] = { title = "Ragged Strips of Silk", description = "Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered.\n\nThe feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?", objectives = "Speak with Kuhuine Tenderstride about aethril and the withered.\n\nProvided item:", completion = "You found withered implements near an aethril bloom?\n\nHmm... you're the third one today." }
WordHunterWoW_QuestEN[40016] = { title = "Desperation Breeds Ingenuity", description = "I believe we may be able to use this clue to our advantage, {name}.\n\nThe withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.", objectives = "Obtain 6 Chewed Aethril Stems from Withered in Azsuna.", progress = "I am glad you continue to come to my shop, <name>. I am useless with a weapon. We need adventurers like you to solve cases like this.", completion = "<Your trainer examines the stems, fingering the individual bite marks.>\n\nIf you'll pardon my language, they really gnawed the crap out of these things.\n\nLook more closely, though. You can see that they focused on extracting the energy from the stem's central filament..." }
WordHunterWoW_QuestEN[40017] = { title = "A Slip of the Hand", description = "As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction.\n\nYou may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.", objectives = "Speak with Kuhuine Tenderstride about the quick-reproducing property of aethril.", completion = "<Kuhuine listens to your story about the aethril.>\n\nWhat you're saying rings true, <name>. I have heard tales of herbalists that could coax flowers into quickly reproducing, but I was never able to master the technique myself.\n\nWell done, herbalist. I feel great pride." }
WordHunterWoW_QuestEN[40018] = { title = "Dreamleaf Sample", description = "The herb is brilliantly green, paper-thin, and somewhat sticky.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "Bring the Dreamleaf Sample to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "I know this herb. I've seen it once before, in the Pandaria's Valley of the Four Winds.\n\nThis is dreamleaf." }
WordHunterWoW_QuestEN[40019] = { title = "An Empathetic Herb", description = "Something is different about this dreamleaf, though. It is less than pure.\n\nI have a theory.\n\nThe wilds of Val'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight.\n\nI need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.", objectives = "Obtain 15 Healthy Dreamleaf and 5 Blight-Infested Dreamleaf.", progress = "Those poor plants...", completion = "It is just as I suspected. The infested herb is dying... but this may be turned to our advantage.\n\nLook, herbalist. The dying dreamleaf has swollen with herbaceous extract. While harvesting the healthy dreamleaf is trivial, you can harvest enormous amounts of product from the infested ones." }
WordHunterWoW_QuestEN[40020] = { title = "Twisted to Death", description = "The corruption has completely taken this herb.\n\nThis blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what's really going on here.", objectives = "Find someone in Lorlathil to teach you about the blight's effects on herbs.\n\nProvided item:", completion = "Another plant, fallen...\n\n<The druid attempts to blink back tears, and fails.>\n\nDAMN YOU, NIGHTMARE! DAMN YOUUUUU!!!" }
WordHunterWoW_QuestEN[40021] = { title = "One Dead Plant is One Too Many", description = "We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it's corruption has gone TOO FAR!\n\nSatyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!", objectives = "Slay 20 satyrs within Val'sharah.", progress = "Exact your bloody vengeance, <class>. Show them the might of an herbalist.", completion = "I feel the blight subsiding. Good.\n\nOur respite will not last forever, but look... even now, the dreamleaf has succumbed more of its bounty." }
WordHunterWoW_QuestEN[40022] = { title = "Choked by Nightmare", description = "Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight.\n\nYou should bring it to Wildcrafter Osme in Lorlathil. He won't be happy.", objectives = "Bring the Blight-Choked Herb to Wildcrafter Osme in Val'sharah.\n\nProvided item:", completion = "<Osme looks at the herb.>\n\n<He is silent for a moment.>\n\nNOOOOOOOOOOOOOOO!!!!!!" }
WordHunterWoW_QuestEN[40023] = { title = "The Last Straw", description = "We cannot falter in our crusade against this corruption, {name}.\n\nIt is our duty as heroes. As herbalists.\n\nAs hero-balists.\n\nSlaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala'nir, in the northeast. Find Tur'xoran's summoning stone, and place this herb in front of it. Then... rip off his head.\n\nDo it for the plants.", objectives = "Use Tur'xoran's Summoning Stone to summon and slay Tur'xoran.", progress = "<The druid seethes.>", completion = "I thank you for your bravery, <name>.\n\nThe next time you approach a sprig of dreamleaf, you may just find that the land thanks you, too." }
WordHunterWoW_QuestEN[40024] = { title = "Foxflower Sample", description = "Something about this herb catches your eye... and your nose.\n\nYour herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.", objectives = "Obtain 20 samples of Foxflower, then bring them to Kuhuine Tenderstride in Dalaran.", progress = "<The tauren sniffs the air.>", completion = "I like this herb you've brought me, <name>. In a way, it reminds me a bit of the Gorgrond Flytrap: both of them have a habit of attacking your nose.\n\nLook. If you collect the herb this way, your yield should be a bit higher..." }
WordHunterWoW_QuestEN[40025] = { title = "Teeny Bite Marks", description = "This herb has been chewed by some of the local wildlife.\n\nWhat kind of animal would eat foxflower? A bear?\n\nPerhaps your trainer in Dalaran will know.", objectives = "Bring the Nibbled Foxflower Stem to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "You're right, <name>. Something has been chewing on this herb." }
WordHunterWoW_QuestEN[40026] = { title = "Chase the Culprit", description = "This is a powerful herb, {name}. Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency.\n\nI'm intrigued. What kind of animal would eat foxflower? A moose?\n\nYou should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.", objectives = "Find out what creature has been eating Foxflower, then chase it and catch 12 Chewed Foxflower Bits.", progress = "Did you find out what was eating the foxflower? Was it a goat? A beaver? A nightsaber?", completion = "Foxes.\n\nHuh.\n\nThat... that makes sense. I suppose I should have guessed that.\n\nWell, now that I feel sufficiently stupid, let's look at these bits of flower, to see if there's anything we can learn..." }
WordHunterWoW_QuestEN[40028] = { title = "The Pied Picker", description = "As you finish gathering the foxflower, a particular part of the bloom catches your eye.\n\nOne of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from.\n\nYour herbalism trainer would be interested in seeing this.", objectives = "Bring the Foxflower Scent Gland to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "<Kuhuine sniffs the small gland.>\n\nThat's certainly a scent gland, alright. It seems to be mostly inert from an alchemical point of view... but I'd guess that this is what is attracting those foxes.\n\nExpress this gland when you can, and you may find yourself attracting a friend or two." }
WordHunterWoW_QuestEN[40029] = { title = "Fjarnskaggl Sample", description = "To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed.\n\nYour herbalism trainer in Dalaran will want to see some more samples of this.", objectives = "Bring 20 Fjarnskaggl to Kuhuine Tenderstride in Dalaran.", progress = "What do you have there, herbalist?", completion = "What a fantastic find, <name>. This must be the celebrated vrykul herb, fjarnskaggl. I've only read about it in books!\n\nHere, I'll share what I remember with you..." }
WordHunterWoW_QuestEN[40030] = { title = "Ram's-Horn Trowel", description = "The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist.\n\nApparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past.\n\nPerhaps she might be interested in seeing the tools that the vrykul use to harvest it.", objectives = "Bring the Ram's-Horn Trowel to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "You found this near a snarl of fjarnskaggl?" }
WordHunterWoW_QuestEN[40031] = { title = "Vrykul Herblore", description = "<Kuhuine studies the trowel further.>\n\nThis is a standard digging tool. There is not much to be learned here, except...\n\n...this DOES suggest that the vrykul are still actively gathering this herb.\n\nThe vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.", objectives = "Find three vrykul Herbology books in Stormheim.", progress = "Any luck finding those books, <name>?", completion = "This book: \"Herblore of the Ancients\", seems promising, but several pages are ripped out. Shame.\n\nStill, there is much to learn in the others.\n\n<Kuhuine turns to a random page, flips a few pages back and...>\n\nSee, look at this technique here!" }
WordHunterWoW_QuestEN[40032] = { title = "The Missing Page", description = "<The page appears to be ripped out of a larger book. It reads:>\n\n\"...the Cairn of the Sea, a place long-known to be beloved by the gods.\n\nHe placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\"\n\nThis may be related to the books you brought back to your herbalism trainer.", objectives = "Bring the Runed Journal Page to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "What good fortune! This page matches perfectly with the book you retrieved for me. We just need to piece them together, and..." }
WordHunterWoW_QuestEN[40033] = { title = "Fjarnskaggl", description = "There! It seems that there was a vrykul herbalist, Torgus, who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors.\n\n<Kuhuine shrugs.>\n\nIt's worth a shot, though without knowing what you're getting into, you may want to bring friends with you.", objectives = "Bring 20 Fjarnskaggl to the Wind-Worn Cairn in Stormheim, then earn the Blessing of Fjarnskaggl." }
WordHunterWoW_QuestEN[40034] = { title = "Starlight Rosedust", description = "Despite all your training, the rose disintegrated in your hand.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "Bring the Starlight Rosedust to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "This herb just disintegrated in your hand?\n\nFascinating..." }
WordHunterWoW_QuestEN[40035] = { title = "The Gentlest Touch", description = "Sadly, I don't have any special techniques that can help you here. You'll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.", objectives = "Attempt to harvest 15 more Starlight Roses.", completion = "Any success? None?\n\nEven if you haven't found success, your skills are improving. Don't give up, herbalist." }
WordHunterWoW_QuestEN[40036] = { title = "Jeweled Spade Handle", description = "An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off.\n\nYour herbalism trainer may be interested in seeing this.", objectives = "Bring the Jeweled Spade Handle to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "You say you found this near a starlight rose?\n\nYou adventurers, always finding such interesting things out there in the wilds..." }
WordHunterWoW_QuestEN[40037] = { title = "The Spade's Blade", description = "Did you notice the script along the base of the handle, {name}? It says \"Herbalist Tharillon,\" in the writing of the nightborne.\n\nThe handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often.\n\nI would start my search for it in Suramar.", objectives = "Find the Broken Herbalist's Blade.", progress = "How goes your search?", completion = "The blade is enchanted - of course it would be. I'm certain that we can replicate this enchantment here in Dalaran.\n\nShame that that herbalist wasn't more agreeable. There may have been more that we could have learned from him. At least he's still alive out there, somewhere..." }
WordHunterWoW_QuestEN[40038] = { title = "Insane Ramblings", description = "Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye:\n\n     \"thinks HE knows how to gather herbs\n {name}{name}\n{name}{name}    steal my blade\n  slit his THROAT when I\n\n        just need\n      a bit more mana\n    maybe aethril, yes...\"\n\nYour herbalism trainer may be interested in seeing this.", objectives = "Bring the Scribbled Ramblings to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "My word. This person really hates you.\n\nSay - do you think this is written by that nightborne herbalist you... encountered?" }
WordHunterWoW_QuestEN[40039] = { title = "Tharillon's Fall", description = "He mentions your name... his blade... aethril...\n\nI'd say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he's looking for aethril, he's probably in Azsuna somewhere.\n\nTharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won't go without a fight.", objectives = "Bring 20 piles of Starlight Rosedust to Azsuna, use them to taunt Herbalist Tharillon out of hiding, then search him for information about herbalism.", progress = "May the Earthmother walk with you, <name>.", completion = "Fantastic work, <name>! With this knowledge, we may never have to suffer a handful of starlight rosedust again!" }
WordHunterWoW_QuestEN[40040] = { title = "Felwort Sample", description = "This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch.\n\nYour herbalism trainer in Dalaran will want to see this.", objectives = "Bring the Felwort Sample to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", completion = "Oh. I don't like this herb at all. I'm fascinated, but I don't like it.\n\n<Kuhuine peers into the center of the plant.>\n\nLook at the size of these seeds, <name>. We can use these. Make sure you harvest them carefully next time." }
WordHunterWoW_QuestEN[40041] = { title = "Felwort Analysis", description = "I sent felwort samples to some of my fellow herbalists, but haven't heard back from them yet. Could you please follow up with them and collect their analyses.\n\nRyno Bloomfield is currently working in Un'goro Crater.\n\nDani Earthtouch is researching Freya's influence in Sholazar Basin.\n\nFinally, Lohor has been working in the overgrown portion of Gorgrond.", objectives = "Collect Ryno Bloomfield's Analysis, Dani Earthtouch's Analysis, and Lohor's Analysis.", progress = "Thank you for your willingness to travel, <name>.", completion = "Much of this is very technical and mundane, but Ryno's analysis can be applied right away.\n\nLook at this, here..." }
WordHunterWoW_QuestEN[40042] = { title = "The Emerald Nightmare: Felwort Mastery", description = "I have a theory on how we can better harvest this felwort, {name}. You see, sometimes in order to understand how something comes into being, you have to work backwards.\n\nI've recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now.\n\nIf you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.", objectives = "Travel to the Emerald Nightmare and cleanse Cenarius of his affliction. Bring back anything you discover to Kuhuine in Dalaran.", progress = "I hope you bring some friends with you on this journey, for this may be your greatest lesson.", completion = "<Kuhuine carefully takes the seed from you and listens to your tale of Cenarius' cleansing.>\n\nFascinating! If what you're saying is true then that means we can harvest Felwort in a similar manner. Now listen..." }
WordHunterWoW_QuestEN[40043] = { title = "The Hunter of Heroes", description = "Helya has made a mockery of my order by creating her own \"helarjar\", powerful undead tasked with hunting down heroic warriors and taking their souls before my val'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago.\n\nHe has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.", objectives = "Deal with Vigfus Bladewind's warband and claim his blades.", progress = "Ah, you have returned...", completion = "Curse Helya, she's corrupted the blades! Still, her champion defeated, her helarjar skulking back to Helheim, and my weapons in the hands of my chosen champion! She even made them more powerful than before. Wield them well, <name>, smite the enemies of this world!" }
WordHunterWoW_QuestEN[40044] = { title = "Shadows in the Mists", description = "Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time.\n\nThe ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade.\n\nSo tell me, how kind is your soul?", objectives = "Defeat Captain Sten, Sigrid, Kjell and Halvir in Helmouth Shallows.", completion = "Their toil is ended, and fewer kvaldir walk the lands of Stormheim.\n\nBoth are blessings, I would say." }
WordHunterWoW_QuestEN[40045] = { title = "Nature vs. Nurture", description = "I appreciate murloc-kind far too much to tell you to go kill all the adults.\n\nWhat we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. \n\nBring him to talk to the murloc tadpoles. He'll get them on our side.", objectives = "Talk to 10 Swamprock Tadpoles.", progress = "Getting the support of the tadpoles is very important for our mission.", completion = "Murky's gained quite the following, hasn't he? Perhaps they can help him out." }
WordHunterWoW_QuestEN[40046] = { title = "Scavenging the Shallows", description = "The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions.\n\nThey bring them here to transport to Helya, though the mists obscure any indications of how.\n\nYou seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.", objectives = "Search the Shipwreck Debris in Helmouth Shallows for Havi's clue.", progress = "Have you found answers, or more questions?", completion = "The Naglfar...\n\nSo Helya's kvaldir can navigate the mists?" }
WordHunterWoW_QuestEN[40047] = { title = "I'll Huff, I'll Puff...", description = "Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities.\n\nThere are a lot of pufferfish around in the water, and I think that they could be a good resource for him. \n\nKill a few and collect their eggs for Murky.", objectives = "Collect 5 Pufferfish Eggs.", progress = "Pufferfish have this impressive ability of... exploding. They could be a powerful tool for Murky.", completion = "The pufferfish will be a perfect resource for Murky! I'll just whip up a spell to make them grow more quickly.\n\nAll he'll have to do is throw, then boom!" }
WordHunterWoW_QuestEN[40048] = { title = "Strings of the Puppet Masters", description = "I understand you were just here to deliver the vellums, but we could use your skills as a {class}. Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy's camp.\n\nThe stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons.\n\nI would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.", objectives = "Acquire a Rune of Dominance from the demons at Legion Camp: Chaos.", progress = "Have you found any runes yet?", completion = "Yes, this is it.\n\n<Jace turns the rune over in his hands, studying the intricate markings.>\n\nExcellent work, <name>. I'll make sure Nalthanis is made aware of your contribution." }
WordHunterWoW_QuestEN[40049] = { title = "Slime Time", description = "Murky's a growing boy, he needs to eat! What better than slimeweed for a young murloc?\n\nThere's plenty of it around in the water amongst the murlocs; swim through it and feed Murky!", objectives = "Feed Murky 6 Bunches of Slimeweed by swimming through them.", completion = "Murky seems to have gotten a very strong slime ability due to this slimeweed. Fantastic!" }
WordHunterWoW_QuestEN[40050] = { title = "Shipwreck Cove", description = "", objectives = "" }
WordHunterWoW_QuestEN[40051] = { title = "Fel Secrets", description = "The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent.\n\nBut there's only enough to enact one of the rituals. After that, the book will be consumed.\n\nIt's up to you to choose which secrets we want to use against the Burning Legion.", objectives = "Read the Tome of Fel Secrets to choose between the Havoc and Vengeance specializations.", progress = "Have you made up your mind?", completion = "Surprising. I agree. Well chosen, <name>.\n\nNow, you must teach the rest of us." }
WordHunterWoW_QuestEN[40052] = { title = "Ancient Vrykul Mastered", description = "Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I'll start getting my things ready for when he calls me back to Dalaran.\n\n<Nicholo sighs.>\n\nLearn from my example, {name}. If I were you, I'd break free from Pallin's \"requests\" as soon as you can.", objectives = "Return the tablets and codex to Professor Pallin.", completion = "So, Nicholo was able to complete the codex? And the tablets are deciphered!\n\nHmm... that's interesting. These tablets have some interesting spells that we could use to our benefit... although I find working with stone to be a bit archaic. I'll just put these down on parchment and let you test for any side effects." }
WordHunterWoW_QuestEN[40056] = { title = "Our New Allies", description = "Student! Your fellow demon hunters in Azsuna have sent for you.\n\nI can certainly appreciate your time being spent fending off the Legion, but it doesn't excuse you from your studies.\n\nWhile you're down there, I'd like you to come up with some new glyphs for your abilities.\n\nSurely my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", objectives = "Report to Allari the Souleater in Azsuna.", completion = "<name>, good to see you again. We could certainly use your strength." }
WordHunterWoW_QuestEN[40057] = { title = "The Price of Power", description = "I see, you wish to augment your powers through script. I believe we can kill two birds with one stone then.\n\nI need help here reducing the demon threat. Perhaps some more engagement with our enemy will inspire you.", objectives = "Slay 15 demons to help lessen the invasion.", completion = "I wish I had more like you, <name>. You fight with a great passion.\n\nAnd I see you also learned a bit more about how to augment our abilities. I'm sure your master in Dalaran will be pleased." }
WordHunterWoW_QuestEN[40058] = { title = "Defense Symbology", description = "As you know, {name}, we demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves.\n\nUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. He could use your assistance with his ritual.", objectives = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", completion = "You've come to help me with my ritual? I thank you, <name>.\n\nIn this time, allies are more important than ever." }
WordHunterWoW_QuestEN[40059] = { title = "Opposites Repel", description = "The ruins nearby have had an eruption of ley energies. Twisted night elves deemed \"Nightfallen\" are scavenging the area as we speak.\n\nCollect ley dust for me from the nightfallen in the ruins up ahead. The dust is infused with arcane energy that I'll need to complete my ritual.", objectives = "Collect ley dust from the nightfallen in Zarkhenar.", progress = "Even though they are opposites, one can not exist without the other.", completion = "If you can believe it, that was the easy part.\n\nThe next part will be a bit more challenging, at least for me it will." }
WordHunterWoW_QuestEN[40060] = { title = "Containing the Demon Within", description = "Now that we have all the essential pieces, let's begin the ritual.\n\nI'll instruct you on how to help me throughout it. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", objectives = "Assist Baric in completing the ritual.", completion = "It is done. I fear that I had waited any longer to improve my wards, the demon in me may have taken over.\n\nThank you again, <name>." }
WordHunterWoW_QuestEN[40061] = { title = "To Know Your Enemy", description = "As we fight the demons, we've also been studying them.\n\nGreat understanding can come from gathering intel. I have a demon hunter near the Felblaze Ingress now gathering intel on the demons there.\n\nGo to her and see what she has learned from the demons invading that region.", objectives = "Find Zaria Shadowheart near the Felblaze Ingress.", completion = "Good to see you again, <name>. Kayn has sent you to see what I have learned?\n\nIn that case, I have much to tell." }
WordHunterWoW_QuestEN[40062] = { title = "Bulging Nightmare Pod", description = "<The flower has folded inward, to protect itself from the nightmare energy trapped within.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "Bring the Bulging Nightmare Pod to Professor Pallin in Dalaran.\n\nProvided item:", completion = "Pods like this contain tremendous amounts of energy. Milling one incorrectly can be catastrophic to the front of one's robes.\n\nLearn to mill them correctly, though, and you can dramatically increase your milling speed. Watch and learn, student!" }
WordHunterWoW_QuestEN[40063] = { title = "Control is Key", description = "I trust you remember why you removed your eyes?\n\nEven though we can see more clearly now, the demons have found ways to mask even their fel energies from us.\n\nA demon commander walks amongst the troops below, commanding them from the shadows. His cloak is powered by an energetic crystal.\n\nFind and destroy that crystal, then kill the commander.", objectives = "Destroy the crystal providing protecting Overseer Felorax, then slay him.", completion = "I commend you, scribe. You are an excellent hunter.\n\nTake this ink as payment for your efforts. I have no need of it." }
WordHunterWoW_QuestEN[40064] = { title = "Woody Seed Cluster", description = "<Attempting to mill this flower has proven more difficult than usual. Located in the bushy center of the bloom is a densely-packed cluster of seeds.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "Bring the Woody Seed Cluster to Professor Pallin in Dalaran.\n\nProvided item:", completion = "This came from a foxflower? Fascinating.\n\nYou know, we can use these woody cores to our advantage. If you mill a woody flower along with several softer flowers, you can speed up your process dramatically! Watch this..." }
WordHunterWoW_QuestEN[40065] = { title = "Fjarnsk", description = "<A goopy substance seeps from the interior of the bloom. It's not ink... it is something else entirely.>\n\n<Professor Pallin would be interested in seeing this.>", objectives = "Bring the Fjarnsk to Professor Pallin in Dalaran.\n\nProvided item:", completion = "<The Professor dips his finger into the fluid and tastes it.>\n\nOh! I know what this is. The herbalists were talking about this. It's called fjarnsk.\n\nYou know, stranglekelp often contains pockets of fluid not unlike this. Let's see if we can carry an old milling technique forward..." }
WordHunterWoW_QuestEN[40066] = { title = "7.0 Stormheim - Treasure 032 - Blackbeak Overlook - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[40067] = { title = "7.0 Stormheim - Vignette: Boulderfall - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[40068] = { title = "7.0 Stormheim - Vignette: Egyl the Enduring - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[40069] = { title = "Fledgling Worm Guts", description = "The drogbar use these caves as a place to train fledgling worms.\n\nThe rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle.\n\nTheir guts are also known to be quite useful, and I have need of them. Two worms, one stone.", objectives = "Collect Worm Guts from Fledgling Rockcrawlers within Rockcrawler Chasm.", progress = "What are their guts for? Well, you'll see. You might not like it, but you will soon find out.", completion = "Those worm guts will be perfect for a special sort of rope." }
WordHunterWoW_QuestEN[40070] = { title = "Eagle Egg Recovery", description = "Eagles are revered by the Skyhorn tribe, but their numbers are dwindling.\n\nThe drogbar feed their fledgling worms eagle eggs so they'll grow strong enough to ride into battle. \n\nIf the drogbar continue to pilfer these eggs, the eagles may become extinct.\n\nHead deeper into the cave and recover any eagle eggs you can find.", objectives = "Head into Rockcrawler Chasm and recover eagle eggs.", progress = "If the pilfered eggs are not recovered, the eagle may go extinct.", completion = "These eggs are in poor condition, <name>. Some are cracked and spoiled, while others are cold to the touch.\n\nYet there is still hope. I believe a few of the eggs you recovered can be saved." }
WordHunterWoW_QuestEN[40071] = { title = "Tamer Takedown", description = "The drogbar will continue to breed vicious worms as long as their tamer lives. \n\nKorgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle.\n\nHead deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.", objectives = "Kill Tamer Korgrul within Rockcrawler Chasm.", progress = "Put an end to Tamer Korgrul, so that we may also put an end to the training of siege worms.", completion = "Korgrul deserved his fate. Thank you, <name>." }
WordHunterWoW_QuestEN[40072] = { title = "Halls of Valor: Securing the Aegis", description = "The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked.\n\nYou, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald's broken bones!\n\nThe Halls of Valor await!", objectives = "Defeat God-King Skovald in the Halls of Valor and claim the Aegis of Aggramar.", completion = "With the God-King's defeat, the Aegis of Aggramar is yours to claim." }
