WordHunterWoW_QuestEN[40077] = { title = "The Invasion Begins", description = "Our advance force of demon hunters is here and has engaged the Legion.\n\nMake our presence known. Let's send a shiver down every demon spine. Raise our colors with pride, {name}.", objectives = "Slay 15 demons and change the Legion banner to take control of Despair Ridge.", completion = "That ought to get their attention.\n\nNow, onto the business of summoning in the rest of our forces." }
WordHunterWoW_QuestEN[40078] = { title = "A Heavy Burden", description = "With Ashildir's judgment, your final trial is complete. \n\nBut even Valhallas can wait, for now we must eat! Being dead works up quite an appetite.\n\nCome now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.", objectives = "Take the fish from Havi's Fish Barrel and skewer it on the spear above the fire.", completion = "It is clear that your cooking prowess is only matched by your might in combat. \n\nNow, on full bellies, we ride to Valhallas!" }
