WordHunterWoW_QuestEN[40112] = { title = "Huln's War - Malorne's Favored", description = "[In broken Common] Shan'do ask for you. Sent Eche'ro beast with message on rack.\n\nUnng Ak hear Eche'ro sound fighting. You find beast? Give help, maybe feathered night elf be relieve.", objectives = "Rescue Eche'ro.", completion = "<Eche'ro looks up briefly, then lowers its head before you. This creature is thankful for your aid.>" }
WordHunterWoW_QuestEN[40113] = { title = "Vignette: Grrvrgull the Conquerer", description = "", objectives = "" }
WordHunterWoW_QuestEN[40114] = { title = "Prepfoot Compound Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40115] = { title = "Prepfoot Compound Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40116] = { title = "Prepfoot Compound Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40120] = { title = "A Murky Fate", description = "You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end.\n\nThe creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites.\n\nThis is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.", objectives = "Use the Smoldering Torch to burn 8 Decaying Corpses in Morheim.", progress = "Have you done this task?", completion = "It is good to know that our warriors remains have been honored.\n\nMay they now celebrate their victories in the halls of Valhallas." }
WordHunterWoW_QuestEN[40121] = { title = "Ley Line Influences", description = "", objectives = "" }
WordHunterWoW_QuestEN[40122] = { title = "Cenarius, Keeper of the Grove", description = "Ahh, Val'sharah.\n\nIt has been an age since I have set foot in these sacred woods. Too long...\n\nOur work here is simple, {class}. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion.\n\nYou have many treacherous tasks in front of you. Consider your visit here a brief respite.\n\nCome, this will not take long.", objectives = "Speak to Malfurion Stormrage at Lorlathil in Val'sharah.", progress = "Cenarius!", completion = "This corruption - I've never seen it before.\n\nAnd yet, it seems somehow familiar..." }
WordHunterWoW_QuestEN[40123] = { title = "The Nightborne Pact", description = "<Thalyssra winces and holds her abdomen.>\n\nNgh... I can ignore this wound no longer.\n\nHelp me patch this up. I will explain everything.", objectives = "Bandage Thalyssra.", completion = "We must find a way to reclaim Suramar City." }
WordHunterWoW_QuestEN[40124] = { title = "Gift of the Storm Cooldown", description = "", objectives = "" }
WordHunterWoW_QuestEN[40125] = { title = "Branch of the Arcan'dor", description = "You have used the spellstone of Kel'danath to soothe countless withered. Yet it contains merely a shade of the arcan'dor's power, drawn from its slumbering seed. \n\n<Thalyssra holds aloft a gleaming white branch.>\n\nThis fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan'dor together.\n\nI have enchanted this branch with a new iteration of Kel'danath's charm spell. With it, you can mend the arcane essence of even more withered. Use it well.", objectives = "Speak with Thalyssra.", completion = "I never imagined I would spend my time in exile studying withered. Through them, I have learned a great deal about my own people, and the nature of our relationship with the Nightwell." }
WordHunterWoW_QuestEN[40126] = { title = "Vignette: Grelda", description = "", objectives = "" }
WordHunterWoW_QuestEN[40127] = { title = "Da-Nel's Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40129] = { title = "Repairing the Source", description = "<A glint catches your eye in the dirt. A brief excavation yields a mostly intact piece of an arcane construct's power core. The breaks appear to be clean, perhaps you could repair it if you find the other fragments.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "You have found a damaged power core for an arcane construct. It seems like you could repair the device." }
WordHunterWoW_QuestEN[40130] = { title = "Washed Clean", description = "Mighty though the Legion is, theirs is not the strongest power in Azeroth.\n\nThere is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, {name}.\n\nGo to the Nor'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well.\n\nI will meet you there.", objectives = "Meet the Fallen Priestess at the Nor'Danil Wellspring. Watch as the priestess attempts the purification ritual.", progress = "It... it worked! I am myself again at last!", completion = "The demon I was is no more. I believe I am ready to return." }
WordHunterWoW_QuestEN[40131] = { title = "Stonehide Leather Sample", description = "The quality of this leather scrap appears representative of the beast hides found in the Broken Isles.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", objectives = "Bring the Stonehide Leather Sample, along with 10 additional pieces of Stonehide Leather, to Kondal Huntsworn in Dalaran.", progress = "How may I help you?", completion = "Greetings, <name>. What have you brought for me today?" }
WordHunterWoW_QuestEN[40132] = { title = "In One Piece", description = "<Your trainer looks over the hide.>\n\nThis hide is usable, but it is mournably small. You disrespect the beast by chopping it up like this, {name}. You make light of the gift that it gave to you.\n\nGo out into the wilds again. Skin the leathery beasts below us, and this time, bring me hides in one piece.", objectives = "Obtain 20 Undivided Hides by skinning the beasts of the Broken Isles.", progress = "<Kondal sternly watches you approach.>", completion = "Mm. This is better.\n\nKeep my advice in mind the next time you take out your skinning knife." }
WordHunterWoW_QuestEN[40133] = { title = "Scrap of Pants", description = "The mouth of this particular beast contained a piece of handsewn cloth. The fabric bears the word \"singwa\".\n\nWhile the term \"singwa\" is unfamiliar, it DOES happen to be the middle of the last name of a fairly notable Azerothian skinner.", objectives = "Bring the Scrap of Pants to Hemet Nesingwary in Highmountain.\n\nProvided item:", completion = "Ye found me extra set o'pants!" }
WordHunterWoW_QuestEN[40134] = { title = "Highmountain Hides", description = "So, ye're a skinner too, aye?\n\nThat's great news, {name}! I don't think I ever knew we shared that in common.\n\nYe've GOT ta see some o'the hides we've got here in Highmountain. Why, I'd give me spare monacle just t'get me hands on some o'those fine, silky hides...", objectives = "Obtain 5 Bear Hides, 5 Elderhorn Hides, and 5 Saber Hides by skinning the creatures of Highmountain.", progress = "<Hemet looks lustfully at the horizon.>", completion = "Y'got these fer me, laddie? I... I don't know what ta say!\n\nHere, take this. It's the least I can do.\n\n<Hemet buries his nose deep into the bear hide.>" }
WordHunterWoW_QuestEN[40135] = { title = "The Freedom to Roam", description = "I remember bein' young, {name}. D'ye remember it? So much less responsibility... I could just run around as I pleased. Now, I'm pretty much stuck with my hunting crew, here in Highmountain.\n\nThere're so many interestin' creatures in the other regions o'the Broken Isles, though. I'll mark yer map, you get out there and do some skinnin'!", objectives = "Obtain 5 Musken Hides, 5 Lion Seal Hides, 5 Boar Hides, and 5 Wolf Hides.", progress = "Once ye're done, I'll show ye a trick or two.", completion = "These are marvelous, <name>. Well done.\n\nI can show ye how t'get better results from yer skinnin'. Take a look at this wolf hide, here..." }
WordHunterWoW_QuestEN[40136] = { title = "Immaculate Stonehide Leather", description = "You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored...\n\nYour trainer in Dalaran would be VERY interested in seeing this.", objectives = "Bring the Immaculate Stonehide Leather to Kondal Huntsworn in Dalaran.\n\nProvided item:", completion = "<name>, you return. What can I do for you today?" }
WordHunterWoW_QuestEN[40137] = { title = "Leather for Ske'rit", description = "This hide certifies that you have learned everything about leather that I can teach you, {name}. My skills have dulled since I set up shop here in town.\n\nI have a former protege who skins the creatures of Suramar. His name is Ske'rit. His skills remain as sharp as his blade, and if there is anyone out there who can teach you, it is him.", objectives = "Report to Ske'rit in Suramar.", completion = "Ey dere. You be a skinna'?" }
WordHunterWoW_QuestEN[40138] = { title = "Trial of the Crusader: Hides of Legend", description = "Ya, I can train you. Ting is, I'm still workin' on my techniques 'ere in Suramar. In fact, you can probably help.\n\nI need ta look at a few special skins, for comparison. I need a strong white yeti pelt, a really big demon skin, and da thickest direhorn skin you can find.\n\nDo that, and I'll share my results with you and' ol' Kondal up in de city.", objectives = "Obtain the Hide of Icehowl from the Trial of the Crusader.\n\nObtain the Hide of Occu'thar from Baradin Hold.\n\nObtain the Hide of Horridon from the Throne of Thunder.", progress = "Any luck findin' dose hides?", completion = "Ya gone and outdid y'self. Look at dese hides, bruddah!" }
WordHunterWoW_QuestEN[40139] = { title = "Halls of Valor: The Hide of Fenryr", description = "While you be here, I got a favor t'ask you.\n\nI been hearin' whispers about one big, nasty wolf dat's been causin' all kinds of trouble up in de vrykul lands. His name be Fenryr.\n\nI want his hide.", objectives = "Obtain the Hide of Fenryr by skinning Fenryr in Valhallas.", progress = "Is it done? Let me see it!", completion = "I seen wolf hides before, but dis be sometin' else." }
WordHunterWoW_QuestEN[40140] = { title = "Ske'rit's Leather Handbook", description = "An' wit dat, my research be done.\n\n<Ske'rit hands you a scroll casing.>\n\nDis is what I been workin' on here in Suramar. Bring it to Kondal, so dat he can teach it to all you other skinnahs.\n\nSince you been helpin' so much, I put your name on it, {name}. Hope you don't mind.", objectives = "Bring Ske'rit's Leather Handbook to Kondal Huntsworn in Dalaran.", completion = "You've returned, and with Ske'rit's book, I see.\n\nLet's look through this together, <name>..." }
WordHunterWoW_QuestEN[40141] = { title = "Stormscale Sample", description = "This scale shimmers with electrical energy.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", objectives = "Bring the Stormscale Sample to Kondal Huntsworn in Dalaran.\n\nProvided item:", completion = "Yes, skinner?" }
WordHunterWoW_QuestEN[40142] = { title = "The Core of the Stormscale", description = "Ahh, yes. The elusive stormscale.\n\nI have seen similar scales in Northrend, and some in Skywall, but it would appear that such a scale is common here. My colleagues that specialize in mail armor will be happy to learn this.\n\nTo more efficiently harvest this type of scale, you must first understand its power. Look for broken, unusable scales on your quarry, and remove the sparks within them. Once you have seen the sparks, you will better understand the stormscale.", objectives = "Obtain 20 Stormscale Sparks by skinning scaled creatures in the Broken Isles.", progress = "Have you seen the sparks?", completion = "Very good, <name>. Greater understanding of the stormscale leads to more efficient skinning, which in turn leads to fewer unnecessary animal deaths." }
WordHunterWoW_QuestEN[40143] = { title = "Unfinished Treatise on the Properties of Stormscale", description = "Tucked between the folds of this animal's hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use.\n\nPerhaps your skinning trainer in Dalaran could help you find its owner.", objectives = "Bring the Unfinished Treatise on the Properties of Stormscale to Kondal Huntsworn in Dalaran.\n\nProvided item:", completion = "<Kondal looks over the paper, brows furrowed.>\n\nI know of only two people who may have written this, <name>. I can tell you where they both are located, if you so desire." }
WordHunterWoW_QuestEN[40144] = { title = "Glielle", description = "One skinner makes the wilds of Azsuna her home. Her name is Glielle, and she is a night elf - or at least, she was, in life.\n\nPerhaps the scroll was hers.", objectives = "Find Glielle in Azsuna.", completion = "What? No, that scroll isn't mine. I don't do much writing these days." }
WordHunterWoW_QuestEN[40145] = { title = "Under Down", description = "I can train you, though.\n\nEveryone knows about the bright stormscales on the hippogryph's hindquarters, but did you know that they also have a few scales beneath their feathers? You just need to know where to look.\n\n<The night elf spirit indicates a few places near the hippogryph's wing joints.>\n\nNow go see if you can get some on your own.", objectives = "Obtain 20 Hippogryph Scales.", progress = "Remember to check the entire beast, not just what's visible on the surface.", completion = "Looks like you've got the hang of it. Well done." }
WordHunterWoW_QuestEN[40146] = { title = "Seymour and Agnes", description = "The other skinner - pair of skinners, to be honest - that comes to mind when you show me this scroll is a student of mine, named Seymour, and his mother Agnes.\n\nLast I heard, they were in Stormheim, hunting the storm drakes.", objectives = "Find Seymour in Stormheim.", completion = "Yes, yes, that's my manuscript, but there's no time for that.\n\nLook what they've done to my MOTHER!" }
WordHunterWoW_QuestEN[40147] = { title = "Mother's Prized Knife", description = "The other day, Mother and I were up at the top of the nearby mountain, and she threw her skinning knife at me because the view wasn't good enough.\n\nHer knife is still up there, somewhere. I'd feel horrible just leaving it.", objectives = "Obtain Agnes' Skinning Knife.", progress = "Mother always wanted to live long enough to see me die. Why did this have to happen!?", completion = "This is it - look, you can still see some of me on it." }
WordHunterWoW_QuestEN[40148] = { title = "Red-Eyed Revenge", description = "It came out of nowhere. I was waiting for mother to finish skinning her half of the drake when the biggest storm dragon I'd ever seen came and... and...\n\n<Seymour finds his resolve.>\n\nI want you to kill as many of them as you can. Skin them, don't skin them, I don't care. Just get revenge for mother!", objectives = "Slay 15 Adult Squallhunters.", completion = "Thank you. I don't know why, but your murder spree helps me feel a little bit better." }
WordHunterWoW_QuestEN[40149] = { title = "Drakol'nir Must Die", description = "The dragon that took Mother's life was named Drakol'nir.\n\nMother always wanted to wear his scale as a pendant, but we never got a chance to skin him because I couldn't kill him alone, and she didn't care much for killing. Only skinning.\n\nYou... you wouldn't mind bringing it for her, would you?", objectives = "Obtain the Scale of Drakol'nir.", progress = "Even if I COULD have killed Drakol'nir, I never would have been able to drag him all the way down here.", completion = "<Seymour places the scale lovingly upon his mother's chest. Even in death, she seems to disapprove.>\n\nThank you, <name>. Here, you take her skinning knife. It's not much, but she won't be needing it anymore." }
WordHunterWoW_QuestEN[40151] = { title = "Immaculate Stormscale", description = "You have been skinning for a long time now, but never have you seen a scale specimen as fine as this.\n\nYour trainer in Dalaran would be VERY interested in seeing this.", objectives = "Bring the Immaculate Stormscale to Kondal Huntsworn in Dalaran.\n\nProvided item:", completion = "What do we have here, <name>?" }
WordHunterWoW_QuestEN[40152] = { title = "Scales for Ske'rit", description = "Your skills surpass mine, {name}. I have never even SEEN a scale such as this... let alone remove one so expertly.\n\nIf you still wish to learn more, you will need to seek an even greater skinner than I. His name is Ske'rit, and he was once my student.\n\nYou will find him in the wild areas of Suramar.", objectives = "Find Ske'rit in Suramar.", completion = "What do we got here?" }
WordHunterWoW_QuestEN[40153] = { title = "Return to Karazhan: Scales of Legend", description = "I know a ting or two about scales, but I'm losin' my edge. I been starin' at stormscales so long, I be forgettin' what de other kinds look like.\n\nI need ta look at a few special scales, for comparison. I need a nether dragon scale, a nice hot black dragonscale, and da thickest piece o' insect chitin you can find.\n\nGotta get dese stormscales outta my head, bruddah.", objectives = "Obtain the Scale of Netherspite from Karazhan, the Scale of Sartharion from the Obsidian Sanctum, and the Scales of Garalon from the Heart of Fear.", progress = "You been gone a while. You get de scales?", completion = "Dese'll do, skinnah.\n\nDese'll do." }
WordHunterWoW_QuestEN[40154] = { title = "Eye of Azshara: The Scales of Serpentrix", description = "I got ta ask you a favor.\n\nI haven't been ta Azsuna, and I don't see myself leavin' Suramar anytime soon. Problem is, dere's a big ol' serpent out dere dat's just beggin' ta be skinned. Just BEGGIN' for it.", objectives = "Obtain the Scales of Serpentrix by skinning Serpentrix in the Wrath of Azshara dungeon.", progress = "You got dis, skinnah.", completion = "Very nice. You got a good knife hand, <name>." }
WordHunterWoW_QuestEN[40155] = { title = "Ske'rit's Scale-Skinning Suggestions", description = "Now dat I got all dese scales, I tink I know what I need to know.\n\n<Ske'rit hands you a few pages of handwritten notes.>\n\nHere's my latest findin's on stormscales. Bring 'em to Kondal, an' read through em' togethah.", objectives = "Bring Ske'rit's Scale-Skinning Suggestions to Kondal Huntsworn in Dalaran.", completion = "You've been working together with Ske'rit? I should've known. You two are cut from the same hide.\n\nLet's see what he has written here." }
WordHunterWoW_QuestEN[40156] = { title = "Felhide Sample", description = "This demonic hide is completely unlike any standard beast hide you are accustomed to.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", objectives = "Bring the Felhide Sample to Kondal Huntsworn in Dalaran.\n\nProvided item:", completion = "I know very little about demonic hides, <name>. I prefer to stay away from them.\n\nThat said, I will share with you what I do know..." }
WordHunterWoW_QuestEN[40157] = { title = "An Unseemly Task", description = "I'm quite impressed with what you've been able to skin in these lands, felhide in particular.\n\nBut as my knowledge is limited in this area of skinning, I know of one who may have increased his skill in skinning such beasts.\n\nYou can find my old apprentice, Ske'rit in Suramar. Ask him if he knows how to yield better results from skinning demons.", objectives = "Find Ske'rit in Suramar.", completion = "What'cha be needin' from me, mon?" }
WordHunterWoW_QuestEN[40158] = { title = "Darkheart Thicket: Demons Be Different", description = "Oh yes, I've seen me fair share of demons while in dese lands. And skinnin' dem ain't no easy task.\n\nTheir hides are tougher than normal animals, fibrous, see? But if you be wantin' to make da most of their skins, den ya need to be practicin' more.\n\nThere be a creature I've heard of in da Darkheart Thicket whose hide's as tough as a demon's. When ya go ta skin him, try cutting with da grain in one even stroke.\n\nBring me his skin to show me you be picking up on what I'm sayin'.", objectives = "Go to Darkheart Thicket and kill Dresaron. Skin him and bring his hide back to Ske'rit in Suramar.", progress = "Any luck on gettin' dat skin?", completion = "<Ske'rit takes the hide from you and looks it over.>\n\nYou definitely got da hang of it, bruddah." }
WordHunterWoW_QuestEN[40159] = { title = "The Emerald Nightmare: The Pestilential Hide of Nythendra", description = "There is one more demon hide to gather... but it isn't that of a demon. It's a dragon.\n\nNythendra, great green dragon, has nearly been eaten up by the Nightmare. Only a master skinner would be able to remove what bits of bug-eaten hide remain on her body.\n\nGo on then, {name}. Show me what you've learned.", objectives = "Obtain the Pestilential Hide of Nythendra.", progress = "Any luck with the dragon?", completion = "You have done it, <name>. You've earned the last of my knowledge.\n\nNow get out there, and get skinning!" }
WordHunterWoW_QuestEN[40160] = { title = "Magic Clams", description = "<The clam resonates with a arcane energy.>\n\nWhat are murlocs doing with arcane clams?\n\nPerhaps your Nightfallen allies could make use of them.", objectives = "Collect Infused Clams from Seerspine murlocs in the Murloc Shoals." }
WordHunterWoW_QuestEN[40161] = { title = "Tapping the Underground", description = "Have you seen them, {name}?\n\nThese are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. \n\nSomehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes.\n\nThese disturbances must be stopped if the ley line is to remain intact.", objectives = "Destroy Seerspine Conduits in the Murloc Shoals." }
WordHunterWoW_QuestEN[40162] = { title = "Snowblind Mesa Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40163] = { title = "Snowblind Mesa Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40164] = { title = "REUSE", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40166] = { title = "Leying with Murlocs", description = "I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river.\n\nI doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus.\n\nBlargrrrl will be deeply entranced if he is trying such a feat. We'll need something powerful to halt his ritual.\n\nInfuse yourself with ley energies and return to me.", objectives = "Infuse yourself with ley energies located in the Murloc Shoals." }
WordHunterWoW_QuestEN[40167] = { title = "The Story of Huln", description = "You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain.\n\nHuln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.", objectives = "Speak with Spiritwalker Ebonhorn to learn about Huln Highmountain.", progress = "The history of this place extends beyond our limited memory.", completion = "You have seen only a taste of what Huln Highmountain accomplished during his lifetime. Let us delve deeper into the past..." }
WordHunterWoW_QuestEN[40168] = { title = "The Swirling Vial", description = "As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A'dal's light shining behind you. Despite your best efforts however, you can't pinpoint when that might have been - maybe it hasn't been, and is yet to be?", objectives = "Bring the Swirling Timewarped Vial to the central dome in Shattrath.", completion = "Oh, interesting! \n\n<Cupri quickly grabs the vial and studies it intensely.>  \n\nPerhaps Zeph was right to keep investigating here. This vial certainly didn't originate from any currently known timeline. Most curious! Thank you for bringing it to me. Or did you already bring it once before?" }
WordHunterWoW_QuestEN[40169] = { title = "Crossroads Rendezvous", description = "An old apprentice of mine left during the war, shortly before we were all cursed.\n\nI've recently heard that she's been seen near the Felblaze Ingress. I would very much like to speak to her once more.\n\nGo and find her. Take her journal to her and let her know that I don't blame her for what she did.\n\nAnd if she's willing, please bring her back to me.", objectives = "Search for signs of the priestess near the Felblaze Ingress.\n\nProvided item:", completion = "<The satyr takes the journal you offer and sobs.>\n\nYou bore the book of someone lost long ago, stranger. Better that you leave me in my misery than linger in this fel-cursed place." }
WordHunterWoW_QuestEN[40170] = { title = "Amateur Hour", description = "The hunters' lodge has attracted a lot of amateurs who call themselves hunters. They're scarin' away all the prize game with their antics.\n\nWhile I'm a known expert with my rifle, I've yet to manage the art of negotiation.\n\nHow about ya do us all a favor and tell those novice hunters to head for the hills?", objectives = "Confront Amateur Hunters within Pinerock Basin.", progress = "Have those amateur hunters scattered? Don't be afraid to use your fists if words don't do the job.", completion = "Ya seem to have a gift when it comes to dealin' with amateurs. Maybe ya can help my ghostwriter, Addie?\n\nI've promised to teach her how to hunt, but I don't have time to show her the basics." }
WordHunterWoW_QuestEN[40173] = { title = "The Unstable Prism", description = "As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.", objectives = "Deliver the Frigid Timewarped Prism to an interested mage in Dalaran.", completion = "Let me see that. \n\n<Auzin ponders the prism for a while, before turning back to you.>\n\nHmm... Cupri could run tests on this for an eternity. This certainly qualifies as further evidence of meddling by a third party... or is it a sixth party...\n\nDo you mind if I keep it?" }
WordHunterWoW_QuestEN[40174] = { title = "Raising the River", description = "You are brimming with raw energy, my friend. Let me see if I can refine it just a little.\n\n<Saylanna draws the energy from you and channels it into an ornate rod.>\n\nThere. I have concentrated the ley energies into this rod. The burst of energy should easily disrupt Blargrrrl and cease the summoning of Torrentus.", objectives = "" }
WordHunterWoW_QuestEN[40175] = { title = "Sleeping Bear", description = "", objectives = "" }
WordHunterWoW_QuestEN[40176] = { title = "From Head to Toe", description = "You've been busy, {name}. And you have some new patterns in your repertoire, I see!\n\nHow about we add another?", objectives = "Craft a pair of Sturdy Stonehide Boots.\n\nYou will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers.", progress = "I'm very excited to see how this turns out.", completion = "I'm still amazed at how easily this leather takes shape. It's so flexible, yet keeps its strength.\n\nI think from here you can take my pattern and make it your own." }
WordHunterWoW_QuestEN[40177] = { title = "Leather Lady", description = "I'd like you to start working with my apprentices.\n\nThe first is Diane Cannings, who has focused her expertise on the softer leather armors. She's just not that into mail armor, like the twins are.\n\nGo talk to her about this new type of leather.", objectives = "Meet with Diane Cannings.", completion = "You're the one Namha's been talking to. Pleased to meet you.\n\nHopefully we can expand our pattern list beyond the helm you've made." }
WordHunterWoW_QuestEN[40178] = { title = "Vestment Opportunity", description = "While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest.\n\nGo to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.", objectives = "Obtain a Hideshaper's Vestment.", progress = "How's your search going?", completion = "<Diane examines the chest piece thoroughly.>\n\nThis has some very interesting design. I think we can easily copy what they've achieved with this piece.\n\nHere, try this pattern out." }
WordHunterWoW_QuestEN[40179] = { title = "Stormheim Savagery", description = "There's a land below - Stormheim, they call it - that's inhabited by vrykul. I remember the vrykul from my days in Northrend.\n\nWhat I remember most was how well-crafted their armor was.\n\nIf the vrykul here are as skilled as the ones in Northrend, then I'm certain we can learn something by studying their armaments.", objectives = "Obtain 7 Vrykul Leather Bindings.", progress = "Are the vrykul giving you much trouble?", completion = "Well now, this is a good variety of equipment you've brought me. Let's see what we have here...\n\n<Diane studies the armor pieces very carefully for a while.>\n\nLook here, <name>. See how they've strengthened the leather by over-stitching the seams..." }
WordHunterWoW_QuestEN[40180] = { title = "Mail Men", description = "The two dwarves behind me are the Glowergold brothers. They're my resident mail armor experts.\n\nWhile Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade.\n\nIntroduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.", objectives = "Meet with Thanid Glowergold.", completion = "Pleasure to meet ye! Now, I'll be needing ye to do one very important thing fer me.\n\nIgnore anything me brother tells ye. He's been out of practice fer years, but still thinks he's better than me.\n\nIt's a lie, lad." }
WordHunterWoW_QuestEN[40181] = { title = "Black Rook Bandit", description = "I've heard rumors of a grand castle in Val'sharah that's known to house an impressive army. Surely, the armor they wear ain't made of sticks and hay.\n\nI'm willing to bet they've fashioned some mail armor at some point fer their troops and it's just sitting there, ripe for the taking.\n\nHow about ye head over there and see what ye can \"borrow\" from their armory.", objectives = "Obtain 5 pieces of Black Rook Armor.", progress = "Make sure ye don't get captured now, lad.", completion = "I knew ye had it in ye! Good work, lad.\n\n<Thanid looks the pieces over with a careful eye.>\n\nVery clever. The elves certainly know their trade.\n\nWe should be able to copy this method with little to no problem." }
WordHunterWoW_QuestEN[40182] = { title = "Too Good To Pass Up", description = "All types of Black Rook Hold armor are intriguing, but I'm most interested in their chest pieces.\n\nIf ye can, try to find someone of importance there and... relieve them of their shirt.\n\nIf it makes ye feel any better, I've heard they're all cursed, so puttin' them out of their misery is the least ye could do.", objectives = "Obtain a Black Rook Hauberk.", progress = "Chest armor is the best armor, I always say!", completion = "Oh, this is a beauty. Just look at that craftsmanship.\n\n<Thanid looks the piece over very carefully.>\n\nAnd looking at how it's pieced together, this should be a snap to replicate.\n\nHere, lad, give this pattern a try and see how that works for ye." }
WordHunterWoW_QuestEN[40183] = { title = "Over Your Head", description = "Alright, {name}, I'd like you to assist me with creating a helm.\n\nFirst we'll need to shave the hides, then tan them, and finally cut them into usable pieces.\n\nFollow my lead.", objectives = "Craft a Rough Warhide Mask.\n\nYou will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers.", progress = "I'm starting to think we make a pretty good team.", completion = "Well done, <name>. Here's a copy of that pattern to add to your collection.\n\nI personally specialize in softer leather armor. If you want to make a MAIL helm, talk to Ranid... although I'm sure he'll charge you a pretty penny for it." }
WordHunterWoW_QuestEN[40184] = { title = "Tauren Tanning", description = "Have you heard of the Highmountain tauren tribes? They're not unlike the tauren we know on Kalimdor.\n\nI've heard they have a leatherworking master there who might be able to help us come up with some new patterns.\n\nTravel to Highmountain and see if they're willing to teach you how they craft their armor.", objectives = "Report to Hrul Sharphoof.", completion = "I can smell the leather on you, stranger.\n\nIt's in your skin, your bones, your spirit. It's also clear to these eyes that you wish to know about the leather of these lands.\n\nIf that's the case... then I must test your grain." }
WordHunterWoW_QuestEN[40185] = { title = "Shoulder the Burden", description = "During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar.\n\nYou would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.", objectives = "Obtain Lohrumn's Shoulderguard.", progress = "My brother's armor... have you found it?", completion = "Thank you, <name>. As promised, let me teach you one of our crafts." }
WordHunterWoW_QuestEN[40186] = { title = "Drogbar Durability", description = "We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves.\n\nSlay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.", objectives = "Kill 15 drogbar to prove your worth to Hrul.", completion = "If you can take down the drogbar, then perhaps you are worthy of my knowledge.\n\nI'll start you with a couple simple patterns to start." }
WordHunterWoW_QuestEN[40187] = { title = "Links in the Chain", description = "Well, lad, I'm afraid I'm at me wits' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set.\n\nHowever, I've heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist.\n\nGo there and search fer a master. Maybe they can fill in the missing patterns fer us.", objectives = "Find a leatherworking master in Azsuna.", completion = "Yes, <class>? You seek to know the techniques of crafting elven mail?\n\nI see. Perhaps a bargain can be struck to benefit us both." }
WordHunterWoW_QuestEN[40188] = { title = "Best Served Cold", description = "My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend.\n\nThat \"friend\" has recently appeared in the ruins to the east. His name is Ranaris.\n\nGo to and take revenge for us and I will grant you some of my wisdom.", objectives = "Kill Ranaris in the El'dranil Shallows.", completion = "You are a man of your word, <name>. I thank you for your service to us.\n\nAnd as we agreed, I shall pass on some of my wisdom to you." }
WordHunterWoW_QuestEN[40189] = { title = "Naga Know-How", description = "The naga of this region wear little armor, but what they do wear is particularly durable.\n\nIf you wish to make a strong shoulder piece, I would first study the naga's armor and then create a pattern of similar construct.\n\nThe city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.", objectives = "Obtain 7 Naga Shoulderguards.", progress = "They may be vile, but they still know how to craft as well as any master.", completion = "These are good pieces. Look here...\n\n<Celea begins to explain the armor's construction to you.>\n\n...and with that, I trust you can create something of equal quality." }
WordHunterWoW_QuestEN[40190] = { title = "Hardening the Hide", description = "Back to Highmountain for you, {name}! I hear they know even more efficient ways to craft our patterns.\n\nWhen you get there, put in a good word for me, will ya? I'd like to start a relationship the tauren, so I don't have to keep sending you back and forth.", objectives = "Return to Highmountain and talk to Hrul Sharphoof.", completion = "Come for more lessons, <name>?\n\nVery well. Let us begin." }
WordHunterWoW_QuestEN[40191] = { title = "Stamped Stories", description = "Stamped onto the leather of the tanning racks behind me are the ancient ways of our tribe's leatherworkers.\n\nThey tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking.\n\nRead the stories and learn from them. Perhaps you'll find some insight on how to better your own methods.", objectives = "Learn from the stories of each of the tanning racks.", completion = "I see hope in your eyes, <name>. I take it our lessons of the past will aid you with your future?" }
WordHunterWoW_QuestEN[40192] = { title = "Claw of the Land", description = "Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don't need quite as many of them.\n\nFor example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.", objectives = "Obtain 100 Stalker Claws.", progress = "Their claws are some of the strongest I've ever come across.", completion = "You've gathered enough here to last me for many moons.\n\n<Hrul begins to work with the claws. It's clear that he's using very little of each, but still able to make an excellent armor piece.>\n\nI hope you were able to learn something from this, <name>." }
WordHunterWoW_QuestEN[40193] = { title = "Getting the Kinks Out", description = "Now listen, lad. Everything ye make can always be done better. I just haven't quite worked out the way to do it with these fancy new scales.\n\nPerhaps that ghost-like elf friend of yours can help ye. An' if she DOES know somethin', perhaps ye can relay that information back to us.\n\nIt would certainly go towards making the shop more lucrative.", objectives = "Go back to Celea in Azsuna.", completion = "Back so soon, <name>?\n\nAhh... you wish to master your existing patterns. That's the characteristic of a true leatherworker.\n\nYes, I can help you." }
WordHunterWoW_QuestEN[40194] = { title = "Reclaimed Cargo", description = "The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves.\n\nIf you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.", objectives = "Obtain 5 Mail Armor Shipments.", progress = "Were you able to recover any of the shipments?", completion = "They're a bit rusty, but at least they're intact. Let me explain how these were made...\n\n<Celea begins to describe the method in which the armor was constructed.>\n\nTedious, yet efficient." }
WordHunterWoW_QuestEN[40195] = { title = "A Daring Rescue", description = "My brother, Taldranis, was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive.\n\nI believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please.\n\nTake this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.", objectives = "Find Taldranis in Oceanus Cove, and deliver the armor to him.", completion = "Wait, Celea sent you? I thought she had been lost ages ago." }
WordHunterWoW_QuestEN[40196] = { title = "Adventuring Anxieties", description = "{name}! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted.\n\nI'd like you to go and discuss this idea with her further.\n\nReturn to me when you're finished. Perhaps we can solve this issue together.", objectives = "Speak with Mei Francis about her barding idea.", completion = "I see.\n\nThat shouldn't be too difficult to make." }
WordHunterWoW_QuestEN[40197] = { title = "The Necessary Materials", description = "In order to make this barding, we'll need a lot of leather. And I mean a LOT of leather.\n\nI'll solidify our plans on fitting the pieces together. You go gather the leather.\n\nOnce that's done, we can begin crafting.", objectives = "Gather 100 Stonehide Leather.", progress = "This is probably the biggest project I've ever been a part of. It's quite exciting!", completion = "I've got the plans. You have the leather?" }
WordHunterWoW_QuestEN[40198] = { title = "Rats!", description = "I tell you, {name}, I have the worst luck sometimes.\n\nA package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers!\n\nProbably building nests with them as we speak. Please, {name}, can you go down there and see if you can retrieve any of them?", objectives = "Go into the Underbelly and recover 3 Highmountain Leatherworking Patterns.", progress = "I hope they're not too badly damaged.", completion = "Nice work stitching these back together. Too bad you couldn't get all the rat saliva off of them.\n\nLet's read them together, shall we?" }
WordHunterWoW_QuestEN[40199] = { title = "Leather Legwork", description = "Good news, {name}! Langrom's Leather and Links recently delivered a shipment of mail armor to me.\n\nIt's of the finest quality and I'd love to show it to ye, but it seems I've lost me crowbar and can't open the crate.\n\nIf ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.", objectives = "Get a crowbar for Thanid.", progress = "Fer the life of me, I dunna know where I left the blasted thing!", completion = "Well wouldn't ye know it, <name>. While ye were out, I found me crowbar! Isn't that great news?\n\nOh, ye were able to acquire one too? Ha ha!\n\nWell why don't ye hold onto that fer yerself and have a look at these armor pieces with me." }
WordHunterWoW_QuestEN[40200] = { title = "Battle Bonds", description = "Do you like pets, {name}? I love pets. They're so cute!\n\nBut what I really want is more things with which to play with them.\n\nI'm sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", objectives = "Talk to Lio the Lioness at the Magical Menagerie shop. Then return to Namha.", completion = "Oh, those are good ideas! Let's get started." }
WordHunterWoW_QuestEN[40201] = { title = "Playthings", description = "Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?!\n\nIt sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you're ready.\n\nWhy don't you work on making the bed, and I'll work out the details for the flaming hoop.", objectives = "Craft a prototype for the pet bed.", progress = "Make sure it's nice and cozy!", completion = "Awww, my pets are going to look so cute sitting on this. Well, most of them will. Probably not all of them." }
WordHunterWoW_QuestEN[40202] = { title = "The Final Lessons", description = "{name}, Hrul has requested your presence. From his message it seems as though he's ready to impart to you all the wisdom he has gained from working with the skins of this land.\n\nI envy you, {name}... but I'm also proud to see that you've gained so much respect with him.\n\nGo now, and good luck!", objectives = "Go to Hrul Sharphoof in Highmountain.", completion = "This will be the last of what I have to teach.\n\nAre you ready for the trials that await you?" }
WordHunterWoW_QuestEN[40203] = { title = "Strength of the Past", description = "As you know, the durability of your armor is only as strong as the materials you use to make them.\n\nLong ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds.\n\nHis natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me.\n\nThis will take all your strength to accomplish.", objectives = "Return a scale of Deathwing to Hrul.", progress = "True strength isn't determined by how much you can endure, but by continuing to endure when you lack the strength.", completion = "You never cease to disappoint me, <name>.\n\nAnd now I impart to you sacred knowledge which was once passed unto me." }
WordHunterWoW_QuestEN[40204] = { title = "Evolution of the Past", description = "As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again.\n\nFor centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them.\n\nGo, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.", objectives = "Obtain 5 Basilisk Hides.", progress = "Do not fear change, for change is the only way to move forward.", completion = "See this, <name>? What was once a soft, simple scale...\n\n\n\n...has evolved into a jagged weapon that can kill!\n\n<He then indicates to the spined scales at the base of the creature's neck.\n\nI trust you now understand the purpose of change." }
WordHunterWoW_QuestEN[40205] = { title = "Respect for the Past", description = "We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes.\n\nScattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell.\n\nGo to these locations, pay your respect, and learn their lessons.", objectives = "Go to the four tanning racks around Highmountain and hear their stories.", completion = "You look wiser, <name>. The ancestors clearly deemed you worthy of their lessons...\n\n...as do I." }
WordHunterWoW_QuestEN[40206] = { title = "A Debt Paid", description = "Now, I've never heard of a ghost sending a letter before, but I'll be damned if'n I didn't just receive one now.\n\nCelea has sent fer ye, lad. I'd best be on me way if I were ye. Might be bad luck to keep a spirit waiting.", objectives = "Go to Celea in Azsuna.", completion = "Thank you for coming, <name>. I wish to impart to you the remainder of my wisdom." }
WordHunterWoW_QuestEN[40207] = { title = "Scales of the Arcane", description = "In my experience, dragon scale has been the strongest material I've ever had the privilege of working with. It's hard, durable and very little can go a long way.\n\nI wish to work with it again, {name}. Being in this form, I'm bound to this area, unable to experience the world any longer.\n\nI've heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.", objectives = "Speak with the blue dragonflight and acquire one of their scales.", progress = "To work with dragon scale again would be a great honor.", completion = "Yes, these are perfect, <name>. As is fair, I will return this grand favor and impart more of my leatherworking knowledge to you." }
WordHunterWoW_QuestEN[40208] = { title = "Eye of Azshara: Scales of the Sea", description = "When we first met, I spoke of the naga, and the armor they're able to craft. No grander armor is worn, however, than by their top warlords.\n\nOne in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend.\n\nRepel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.", objectives = "Go to the Eye of Azshara and obtain Warlord Parjesh's Hauberk.", progress = "He will not just hand it over, <name>. You're in for a rough fight.", completion = "You've taken down a mighty adversary, <name>. The naga no doubt will be on the hunt for you.\n\nBefore they get to you though, allow me to show you a few things..." }
WordHunterWoW_QuestEN[40209] = { title = "Scales of the Earth", description = "While leather armor is strong on its own, integrating scales into the design is what truly sets it apart.\n\nThe type of scales you use will determine how many you'll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales.\n\nA fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.", objectives = "Obtain the Axetail Basilisk Matriarch Scales.", progress = "You may have to fight past a few of her brood to get to her.", completion = "The basilisk scale is thick. Even a thinned version of this is enough to repel any sword or spear attack.\n\nThat strength is what makes these scales so valuable to our craft." }
WordHunterWoW_QuestEN[40210] = { title = "Time Well Spent", description = "Unfortunately, {name}, you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership.\n\nGo now and share what you've learned with your allies in Dalaran. I'm sure they'd be eager to share in your training.", objectives = "Tell Namha of your time with the night elves in Azsuna.", completion = "<Namha listens to your tales with wide eyes and an eager ear>\n\nThat's it, <name>. You've inspired me. I've been stuck in this floating city for far too long. It's time to get out there and see the world again." }
WordHunterWoW_QuestEN[40211] = { title = "Demon Flesh", description = "Something we haven't really explored yet, {name}, are the creatures of Suramar. Specifically, the demons.\n\nNow I certainly don't praise what they are, but you can't ignore the fact that some of their creatures have especially tough hides.\n\nWe could take a lesson from the demon hunters and use those hides to our advantage against the demons. I'll be damned though if I know the first thing about working with demon hide.\n\nPerhaps there's someone in Suramar who can help...", objectives = "Search for a master leatherworker in Suramar.", completion = "I says to him, I go, \"The world is on the cutting edge of the knife, and we, we're just the shavings!\"\n\nAnd he says to me, he says, \"But then who'll feed the sabers?!\"\n\nWait... who are you? Leatherworking? Oh... right. I, I was once a great leatherworker..." }
WordHunterWoW_QuestEN[40212] = { title = "Wrong End of the Knife", description = "There he is! The man that isn't there! He's... he's...\n\nWait... no, I'm sorry. My thoughts, they're just all over place lately. Ever since my exile, things have been a bit fuzzier than normal.\n\nIf you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.", objectives = "Kill the traitor leatherworkers, Feorias, Tallian, and Syana.", completion = "Green is good. Green is good. Green is good? No way!\n\nOh, it's you <name>. Right, you needed something?\n\nWait, they're dead? And you slew them? Fantastic!" }
WordHunterWoW_QuestEN[40213] = { title = "Hounds Abound", description = "I'll invite him to tea. That'll show him! He'll see the leather doll and say, \"When did SHE get here?!\"\n\nI mean... sorry, {name}. My mind goes to strange places. You want to know about the demons, the ones with durable hides?\n\nBefore I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses.\n\nWe can discuss their hides afterwards.", objectives = "Obtain 5 Fel Hound Corpses.", progress = "We met on the lake. It was spring and she wore ley lilies...", completion = "Hey <name>! Come here and listen. You hear it don't you? Come on, I know you hear it!\n\nWhat are those infernal things you're dragging behind you? Fel hounds? For me?\n\nYou have a strange taste in gifts for your friends, <name>." }
WordHunterWoW_QuestEN[40214] = { title = "Fel Tanning", description = "Listen, you. I'm not sure when the crazy side of me will come out again, so let's make our time together short.\n\nYou want to learn how to make armor to rival the demons? Follow my instructions and you'll have an excellent grasp on the procedures.", objectives = "Craft a pair of bracers for Stalriss using the tanning rack.", progress = "You're really here, right?\n\n<Stalriss reaches out and pinches you>", completion = "Yes, you've done it, <name>. Good work.\n\nNow go, before I do or say something I'd regret, but probably won't remember." }
WordHunterWoW_QuestEN[40215] = { title = "Mounting Made Easy", description = "{name}, I'm glad you're here. I confess: I've been working on a secret project behind your back. Behold: the Stonehide Leather Harness! Now, we simply need to find a mount worthy of such a piece of art.\n\nThe vrykul sing songs of a snow-white elderhorn with endless stamina. Find it, place the harness on it, and tame it.", objectives = "Capture the Great Northern Elderhorn.", completion = "Now that's a beast worth riding. Here's the pattern for that harness, if you want one for yourself." }
WordHunterWoW_QuestEN[40216] = { title = "A Hunter at Heart", description = "Addie's one heck of a writer, but I've never seen her hold a rifle. She's keen on learning how to hunt, but who's ever heard of a gnome hunter? \n\nYou seem to have a knack dealin' with amateurs, so maybe you'd be willin' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill.\n\nYa best start off with some small game. We don't want the lass to get discouraged.", objectives = "Help Addie learn to hunt by killing wildlife in Pinerock Basin.", progress = "Keep an eye on the gnome while you're huntin'. She's never held a rifle before.", completion = "You haven't got any holes in ya, I guess that means Addie's aim isn't as bad as I thought!" }
WordHunterWoW_QuestEN[40217] = { title = "An Offering of Ammo", description = "The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions.\n\nOur leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin.\n\nThey hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow.\n\nWhile I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.", objectives = "Deliver the Quiver of Arrows to Hemet Nesingwary at Nesingwary's Retreat.\n\nProvided item:", completion = "We gave up usin' that kind of ammo long ago! Don't worry though, we won't let the gift go to waste. I'm sure we can use the arrows for kindling." }
WordHunterWoW_QuestEN[40218] = { title = "Debt Repaid", description = "I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning.\n\nYou should warn Ritssyn to keep his distance. I'll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.", objectives = "Speak to Ritssyn Flamescowl.", completion = "It appears Kira travels faster than your word. She arrived moments ago, though her eyes purposely avoided mine.\n\nIn gaining her trust, you accomplished something I could not. With her help, we should be able to summon the gateway." }
WordHunterWoW_QuestEN[40219] = { title = "In Defiance of Deathwing", description = "It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing.\n\nToday we shall re-live moments of that day through the eyes of our ancestors.\n\nFor this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.", objectives = "Witness 3 Visions.", progress = "You are learning parts of our history few outsiders have ever known.", completion = "And so it was that Huln Highmountain came to this mountain, freeing the drogbar slaves of Deathwing, and came into possession of the Hammer of Khaz'goroth." }
WordHunterWoW_QuestEN[40220] = { title = "Thorny Dancing", description = "The Thistleleaf sprites have gone completely mad.\n\nI suspect they are being manipulated by some very mischievous Thorndancers.\n\nPlease, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.", objectives = "Defeat 3 Thistleleaf Thorndancers in the Lunarwing Shallows.", progress = "Have you dealt with those Thorndancers yet?", completion = "That should set those vexing Thorndancers on their way." }
WordHunterWoW_QuestEN[40221] = { title = "Spread Your Lunarwings and Fly", description = "These poor faerie dragons are being tortured!\n\nWhat's worse, when the thistleleaf become bored they ensnare their victims to continue their torment later.\n\nThis behavior is simply unacceptable.\n\nPlease free any trapped Lunarwings you can find.", objectives = "Save 8 Trapped Lunarwings in the Lunarwing Shallows.", completion = "On behalf of the Lunarwings, thank you." }
WordHunterWoW_QuestEN[40222] = { title = "The Imp Mother's Tome", description = "See this giant cave? There's a terrifyingly powerful imp mother inside.\n\nBut that's not the good part. The good part is what she has.\n\nApparently, she's some kind of keeper of fel secrets. She's in there performing profane Legion rites and scribing them into a book.\n\nWe need that power! We need her tome!", objectives = "Obtain the Tome of Fel Secrets.", progress = "Do you have it?", completion = "Can you feel the power emanating from the book? I cannot wait to learn its secrets." }
WordHunterWoW_QuestEN[40223] = { title = "7.0 DH-Mardum - Small Treasure Chest 008", description = "", objectives = "" }
WordHunterWoW_QuestEN[40224] = { title = "The Hammer in the Deep", description = "<Thrall listens intently.>\n\nYou found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth'xun and retrieve the hammer before any more of this realm is corrupted.\n\nTherazane will open a portal directly there. Let's go!", objectives = "Use Therazane's Portal to travel to the Crumbling Depths. Accompany Stormcaller Mylra and Thrall to recover the Doomhammer.", progress = "What of the Doomhammer?", completion = "The orcs had a prophecy about the Doomhammer. It was said that a stranger will raise the hammer high, and with it, justice shall reign. Maybe... maybe YOU were meant to be that stranger all along.\n\nCome, <name>. The Earthen Ring needs you. And Azeroth needs us." }
WordHunterWoW_QuestEN[40225] = { title = "A Ring Reforged", description = "Speak with Nobundo, and take your place around the circle, {name}. The Earthen Ring will rise again, with you as its leader!\n\nWithin these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...", objectives = "Speak with Nobundo and take your place as the head of the Earthen Ring.", progress = "The Alliance and Horde are in chaos. If we are to save Azeroth, we <class> must bind together!", completion = "The Earthen Ring rises once more to defend Azeroth. You will be our Farseer, <name>, and we will be your instruments. Only by working together can we preserve our world.\n\nWe are yours to command, Farseer." }
WordHunterWoW_QuestEN[40226] = { title = "Remnants of the Sashj'tar", description = "", objectives = "" }
WordHunterWoW_QuestEN[40227] = { title = "Bad Intentions", description = "Suramar is lost.\n\nOur leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them.\n\nBut cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here...\n\nI rejected both of these options and found myself here. I will find a third way.", objectives = "Speak with Thaedris Feathersong in Tel'anor.", progress = "Why do you seek to dissuade me?", completion = "Honeyed words from a stranger. While comforting, they do not shake my resolve. Come, at this rate I will wither before we are through." }
WordHunterWoW_QuestEN[40228] = { title = "Scout It Out", description = "You've proven that a gnome can shoot a rifle, and that's no easy feat, but a true test of Addie's skill will be to see if she can track down an elusive beast.\n\nRumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one's seen the beast up close.\n\nTake this flare, and shoot it into the sky once you've spotted the roc. When we see the signal, the huntin' party will rush in and help bring down that magnificent bird!", objectives = "Kill Irewing after sending up a flare, signaling his location.", progress = "Don't just stand there, head out into the basin and find that bird!", completion = "That was a kill I won't soon forget!\n\nAddie will write the tale of our adventures here today, but not many will believe that a gnome hunter took down a beast ten times her size." }
WordHunterWoW_QuestEN[40229] = { title = "Step into the Dark", description = "With the threat to my people quelled, I believe it is time to introduce you to my kin.\n\nMeet me at Stonedark Grotto, and you will see where we live.", objectives = "Speak with Navarrogg at Stonedark Grotto.", completion = "Welcome to our humble home. You are free to move about here from now on." }
WordHunterWoW_QuestEN[40230] = { title = "Oh, the Clawdacity!", description = "The leader of the Cavemoss makrura, Clawdayshus, has been ordering raids into the Cavemoss village to steal the young for snacks.\n\nThis isn't going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well!\n\nThis is a job for murlocs.\n\nMindmeld with Murky in his egg and show him how it's done!", objectives = "Mindmeld with Murky and defeat Clawdayshus.", progress = "Clawdayshus is ruthless. Murky must stop him.", completion = "You did it! Murky will make a great leader for the next generation of the murlocs here.\n\nI can't help but feel sad over losing my little buddy, but you've got to let them go sometime." }
WordHunterWoW_QuestEN[40231] = { title = "The Brood Queen's Court: Count Nefarious", description = "", objectives = "" }
WordHunterWoW_QuestEN[40232] = { title = "The Brood Queen's Court: King Voras", description = "", objectives = "" }
WordHunterWoW_QuestEN[40233] = { title = "The Brood Queen's Court: Overseer Brutarg", description = "", objectives = "" }
WordHunterWoW_QuestEN[40234] = { title = "The Brood Queen's Court: General Volroth", description = "", objectives = "" }
WordHunterWoW_QuestEN[40235] = { title = "Abrogator Arbitrator", description = "Da bums in Highmaul refuse to see dey are on da way out. Me, I'm gettin' while da gettin' is good. Da sooner youse bring me a bunch of Apexis Crystals, da sooner I can get off dis stupid island. Da amount required is very precise!", objectives = "Kluk'kluk wants you to bring him 14958 Apexis Crystals.", progress = "I can feel da power of da crystals! Give dem to me!", completion = "Finally! Today is da day I can get out of here!\n\nIf not I'll need more of dem to try again." }
WordHunterWoW_QuestEN[40236] = { title = "The Dawning Light", description = "It was a miracle that you were able to survive, {name}. It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors.\n\nNow we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this.\n\nWe all agree that new leader should be you, {name}. You have shown strength, wisdom, courage, and kindness beyond measure.\n\nWalk with us to the temple and we will announce our decision.", objectives = "Accompany Fearsome Jang and await the masters' announcement.", completion = "Congratulations, Grand Master <name>!" }
WordHunterWoW_QuestEN[40237] = { title = "Work Work Stoppage", description = "We've had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat.\n\nI've had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals.", objectives = "Bring 20000 Apexis Crystals to the Renegade Ironworker.", progress = "It's a good thing you took care of Mar'gok or nobody would be available for hire. Ogre security is still effective, right?", completion = "I'd say thanks, but I'm pretty sure that us shutting down the Foundry helps you out more than it helps us. So you're welcome." }
WordHunterWoW_QuestEN[40238] = { title = "A Grim Equation", description = "They were waiting for us when we crashed. It was all we could do to establish our small outpost.\n\nEven now they drain the souls of our fallen to fuel their attacks.\n\nDestroy their soul coffers. Free our comrades and let them join the Light.\n\nWhen you have finished, find Y'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.", objectives = "Destroy the three Soul Coffers on the Shattered Fields.", completion = "Good work. They will return in time, but we can use this advantage." }
WordHunterWoW_QuestEN[40240] = { title = "Looted Blacksmith Defender's Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[40241] = { title = "Battle Bonds", description = "Do you like pets, {name}? I love pets. They're so cute!\n\nBut what I really want is more things with which to play with them.\n\nI'm sure Serr'ah over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", objectives = "Talk to Serr'ah at the Magical Menagerie shop. Then return to Namha.", completion = "Oh, those are good ideas! Let's get started." }
WordHunterWoW_QuestEN[40242] = { title = "Mellok, Son of Torok", description = "", objectives = "" }
WordHunterWoW_QuestEN[40243] = { title = "Break Weapon Racks", description = "", objectives = "" }
WordHunterWoW_QuestEN[40244] = { title = "That Guy in the Costume", description = "Aye, when we were out huntin' on the coast, we ran into this ridiculous lad in in a costume. He says he's tryin ta blend in with the murlocs... but I'm pretty sure he's just not right in the head.\n\nOne of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin' it out?\n\nYe can ask Tamara over there for a ride.", objectives = "Speak to Tamara and fly to Shipwreck Cove.", completion = "Hello, adventurer! Here to help me and Murky out?" }
WordHunterWoW_QuestEN[40245] = { title = "Looted Tailoring Defender's Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[40246] = { title = "Looted Leatherworking Defender's Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[40247] = { title = "Asking a Favor", description = "Caria Felsoul was one of our best... before she answered the Legion's foul call.\n\nShe now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race's greatest champion, who fell only to Sargeras himself.\n\nWe sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source.\n\nCould you ask Khadgar for assistance? Our friends in this world are few.", objectives = "Ask Khadgar for a source to power the Legion communicator.", completion = "It's good to see you again. If there's anything I can do to help you take the fight to the Legion, just let me know." }
WordHunterWoW_QuestEN[40249] = { title = "Vengeance Will Be Ours", description = "We aren't going to get our forces anywhere near the Broken Shore without getting knocked out of the sky.\n\nI think it best if you handle this matter yourself - there are none among us more capable on the field of battle.\n\nSave Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.", objectives = "Take the Aldrachi Warblades from Caria Felsoul.", completion = "What of the others? Did they...?\n\nI see. They gave their lives for a worthy cause - the Warblades will change the tide of this war, mark my words." }
WordHunterWoW_QuestEN[40250] = { title = "Suramar - Demon Hunter Daily - Choice Reward Summary - 1", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40251] = { title = "Vignette: Kethrazor", description = "", objectives = "" }
WordHunterWoW_QuestEN[40252] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40253] = { title = "Stop Gul'dan!", description = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens.\n\nGul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse.\n\nEven in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", objectives = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", completion = "Excellent. You have absorbed the powers of these brutes. Look how strong you have grown!" }
WordHunterWoW_QuestEN[40254] = { title = "Forged in Fire", description = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. \n\nSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.\n\nThe demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.\n\nI believe that person could be you, {name}.", objectives = "Kill Immolanth and take his power.", progress = "Do you have Immolanth's power, <name>?", completion = "Yes... just look you... surging with new power and knowledge!" }
WordHunterWoW_QuestEN[40255] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "Kill Bastillax and take his power.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar." }
WordHunterWoW_QuestEN[40256] = { title = "Between Us and Freedom", description = "The last of our survivors have fought their way into the final chamber ahead.\n\nOnly one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax.\n\nKill him, take his power, and claim our freedom.", objectives = "Kill Bastillax and take his power.", completion = "We escaped the Vault, but our work is far from over.\n\nThe Legion's assault on this world is just beginning.\n\nIf Azeroth is to survive, we may have to work with this... Archmage Khadgar." }
WordHunterWoW_QuestEN[40257] = { title = "Demon Hunter Choice 1", description = "PLACEHOLDER", objectives = "PLACEHOLDERPLACEHOLDER" }
WordHunterWoW_QuestEN[40258] = { title = "Suramar - Demon Hunter Daily - Choice Reward Summary - 2", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40259] = { title = "Demon Hunter Choice 2", description = "PLACEHOLDER", objectives = "PLACEHOLDERPLACEHOLDER" }
WordHunterWoW_QuestEN[40260] = { title = "Suramar - Demon Hunter Daily - Choice Reward Summary - 3", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40261] = { title = "Demon Hunter Choice 3", description = "PLACEHOLDER", objectives = "PLACEHOLDERPLACEHOLDER" }
WordHunterWoW_QuestEN[40265] = { title = "A Touch of Magic", description = "I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin.\n\nI can sense the power of a potent enchanter in you, {name}. If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I'm sure you can bring them to life again.", objectives = "Sprinkle Arkhana on dormant objects in Tigrid's house.", progress = "Just the presence of such a vibrant enchanter gives my home the spark of life!", completion = "It pleases me that you have brought life to my beloved enchantments.\n\nOnce I could accomplish much more than mere parlor tricks... until the source of my power was stolen from me." }
WordHunterWoW_QuestEN[40266] = { title = "The Lost Advisor", description = "You may as well assist me while you are here. I require a potion to be made, one that will set things right.\n\nI must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon.\n\nThe harpies around here cannot resist cliffthorn. It is what drew them to Tel'anor in the first place. \n\nYou should find plenty just outside this building.", objectives = "Collect 8 Cliffthorn.", progress = "<Thaedris seems lost in thought as he gazes towards the city of Suramar.>", completion = "<Thaedris stirs from his thoughts as you approach.>\n\nThese will be sufficient, <race>.\n\n Cliffthorn is a deadly poison, and will be perfect for my needs." }
WordHunterWoW_QuestEN[40267] = { title = "An Unexpected Message", description = "Ah, Felo'melorn. I am familiar with this weapon. \n\nFor ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. \n\nAs luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her.\n\nI suggest you start your search there. The portal over there will bring you back to the city.", objectives = "Discover Archmage Modera's message by using the Glowing Resonate Crystal.", completion = "<name>, I'm glad you came.\n\nI've found information on just the thing we need to turn this war in our favor." }
WordHunterWoW_QuestEN[40268] = { title = "Neltharion's Vault Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40269] = { title = "Torok's Bluff Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40270] = { title = "The Path of Atonement", description = "Felo'melorn, the runeblade of the kings of Quel'Thalas. It was said to harness the very essence of flame and after being reforged by Kael'thas could even stand against the legendary Frostmourne.\n\nWe thought that the blade was lost with Kael'thas's death but an associate of mine has a lead on where it may be located.\n\nWe need every advantage we can get and with Felo'melorn in your hand the Legion surely will tremble!\n\nAh, our company is here.", objectives = "Speak to Archmage Modera's associate at the Dalaran Crater within Hillsbrad Foothills", completion = "Our next journey will be to Icecrown, <name>.\n\nThere, in the heart of the Scourge, we will find Felo'melorn." }
WordHunterWoW_QuestEN[40272] = { title = "7.0 Val'sharah - Village - Medium Treasure 001 - twh", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40273] = { title = "7.0 Val'sharah - Temple of Elune - Medium Treasure 001 - bic", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40274] = { title = "7.0 DH-Mardum - Small Treasure Chest 010", description = "", objectives = "" }
WordHunterWoW_QuestEN[40276] = { title = "The Maelstrom Beckons", description = "Can you feel it, shaman? Here, in the heart of Azeroth, where earth and wind and waves clash together - it is as if one can speak directly with the world.\n\nThe artifact you wield houses great power but even greater potential. Carry it below and seek out the ancient elemental altar overlooking the fury of the maelstrom. From there, you can commune with Azeroth and imbue your artifact with even greater abilities. Do so, and then share with me what you have learned!", objectives = "Locate the Ancient Elemental Altar and imbue your artifact with a new power.", completion = "I sense that your work here has only begun. As you get more familiar with your artifact, you will be able to continue augmenting its power.\n\nThe others are watching you carefully. You have become a symbol of hope in our struggle against the Legion!" }
WordHunterWoW_QuestEN[40277] = { title = "Fight Night: Tiffany Nelson", description = "", objectives = "" }
WordHunterWoW_QuestEN[40278] = { title = "My Beasts's Bidding", description = "", objectives = "" }
WordHunterWoW_QuestEN[40279] = { title = "Training with Durian", description = "Show me that you truly have gained the trust of your companions.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Durian Strongfruit in a pet battle." }
WordHunterWoW_QuestEN[40280] = { title = "Training with Bredda", description = "", objectives = "Defeat Bredda Tenderhide in a pet battle." }
WordHunterWoW_QuestEN[40282] = { title = "Tiny Poacher, Tiny Animals", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
