WordHunterWoW_QuestEN[40296] = { title = "Tracking Quest: Corridor", description = "", objectives = "" }
WordHunterWoW_QuestEN[40297] = { title = "Lyana Darksorrow", description = "<A captive demon hunter floats in stasis in front of you; her soul slowly draining into the harvester crystal.>\n\n<In order to release her from stasis, you will need to destroy the soul harvester.>", objectives = "Destroy the Soul Harvester.", completion = "My name is Lyana. What is yours, <class>?\n\nYou have my gratitude for releasing me.\n\nI do not know how long I have been held captive... but I sense an overwhelming number of demons nearby.\n\nWe have much to do here, you and I." }
WordHunterWoW_QuestEN[40298] = { title = "Fight Night: Sir Galveston", description = "", objectives = "" }
WordHunterWoW_QuestEN[40299] = { title = "Fight Night: Bodhi Sunwayver", description = "", objectives = "" }
WordHunterWoW_QuestEN[40300] = { title = "Tools of the Trade", description = "I used to visit here before the barrier was raised. While the ruling council and the Grand Magistrix argued and politicked I watched the caretakers  perform their rituals and venerate the dead.\n\nI would honor the spirits here one last time. I am headed to the tombs. If some of the sacred oils, burial shrouds, or incense survived the ages then bring them to me.", objectives = "Retrieve burial objects for Thaedris.", progress = "Did you find anything?", completion = "Truly a testament to our preservation techniques. I had lost hope that anything would have survived looting and the sands of time.\n\nThe ancestors will be pleased with this." }
WordHunterWoW_QuestEN[40301] = { title = "Vignette: Phalanx Captain", description = "", objectives = "" }
WordHunterWoW_QuestEN[40302] = { title = "FLAG - Prospecting 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[40303] = { title = "FLAG - Prospecting 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[40304] = { title = "FLAG - Prospecting 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[40305] = { title = "Barracks Drop 01 Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[40306] = { title = "The Last Chapter", description = "The next step of my journey requires a tome, but I find that I am still unable to idly sit by as this place continues to fall into disrepair.\n\nI will tidy up the memorials while you go fetch me the tome. It is called the Encyclopedia Botanica and you can find it in the library near the main plaza.", objectives = "Find the Encyclopedia Botanica.", progress = "Do you have the tome, <race>?", completion = "Hmph. I suppose if you're assisting me with my task, I should learn your name.\n\n<Thaedris reaches into the book and pulls out an unfamiliar, dried plant.>\n\nThank you for fetching me another one of the ingredients. Your assistance is... welcome, <name>." }
WordHunterWoW_QuestEN[40307] = { title = "Glaive Circumstances", description = "I came here on a mission to slay the demon eredar, Azoran. During my infiltration, I was shot down from my felbat and captured.\n\nI'm not going to mince words, {name}. Azoran plans to use the Burning Legion command ship to destroy Dalaran.\n\nTo stop him, I will need my warglaives that were lost during my fall from the sky. I would retrieve them myself, but I'm still weakened from my imprisonment.\n\nSearch for the warglaives on the northern side of the crater, where I was shot down.", objectives = "Retrieve Lyana Darksorrow's glaives.", progress = "Do you have my glaives, <race>?", completion = "Thank you. Now that my warglaives are returned, I will bring ruin upon Felsoul Hold.\n\nMy wrath is unending and my vengeance swift." }
WordHunterWoW_QuestEN[40308] = { title = "Fragments of Memory", description = "<The beautiful elven burial urn is shattered carelessly on the ground. It was clearly handled roughly, but not scratched by the talons of the harpies.>\n\n<You find a trail of shards leading towards a cave. Those responsible are certainly within. Thaedris would be interested in the relics and their safe return.>", objectives = "Retrieve 15 Tel'anor Mementos.", progress = "What do you have there?", completion = "These relics are tokens and mementos of the former lives of those interred here. They like to be remembered and these offerings keep them in their eternal peace.\n\nThe spirits of the fallen will be at rest now. You have my gratitude." }
WordHunterWoW_QuestEN[40310] = { title = "Shipwrecked Captive", description = "I spent my life playing the pet in other peoples battles. Now it's my time to be the pet tamer! Best part of being dead is I can do this forever!", objectives = "Defeat Shipwrecked Captive in a pet battle.", completion = "I'll get better. I have all eternity to train!" }
WordHunterWoW_QuestEN[40311] = { title = "Titanic Showdown", description = "The greatest time scar of all is just ahead.\n\nKhaz'goroth was the titan who shaped the world. Using his hammer against Deathwing, the aspect of earth, had dire consequences.\n\nGo, speak with Huln and witness the reason why the name \"Highmountain\" is feared amongst dragons to this day.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find and aid the spirit of Huln Highmountain." }
WordHunterWoW_QuestEN[40312] = { title = "A Timely Opportunity", description = "Now that the whole \"spirit journey\" thing is out of the way we can get down to business.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Assist Spiritwalker Ebonhorn in Neltharian's Vault." }
WordHunterWoW_QuestEN[40313] = { title = "Barracks Drop 02 Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[40314] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40315] = { title = "End of the Line", description = "I cannot call Suramar my home any more, and I refuse to become a withered abomination. There is no place for me anymore, don't you understand?\n\nWe only need one last ingredient to complete the elixir. You will help me, won't you?", objectives = "Speak with Thaedris at the upper landing of Tel'anor.", progress = "Please let me fulfill my wishes, <name>.", completion = "Your arguments are not without merit, <name>. But I remain steadfast." }
WordHunterWoW_QuestEN[40316] = { title = "The Screeching Crag", description = "", objectives = "" }
WordHunterWoW_QuestEN[40317] = { title = "Tree Destroyed", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40319] = { title = "The Final Ingredient", description = "The potion is complete, {name}. Soon our journey will be over. There is one last thing I would have you do for me, then you shall have your reward.\n\nMy wife's bow was kept here, but I have not been able to find it after searching everywhere. There is potent magic in it.\n\nI fear one of the restless spirits may have taken it, but it would take a powerful force to pick up an item such as this. Be careful.", objectives = "Find Latara's bow.", progress = "What was that? I heard a familiar voice... it couldn't be.", completion = "You saw Latara? What happened?\n\n... I see. I am so sorry I failed you, my love." }
WordHunterWoW_QuestEN[40320] = { title = "Band of Blood Brothers", description = "You are the one that Toryl was bellowing about? Perhaps you can help me.\n\nWhen I set out to search for Throndyr, I was not alone. Three vrykul loyal to Throndyr also accompanied me. As you can plainly see, I now stand alone.\n\nFind my kin, {name}.\n\nI cannot bear to think that they also share Throndyr's fate.", objectives = "Locate Katarine, Fjolrik, and Stokalfr in Muddledeep Cavern.", progress = "I must know what has befallen my kin.", completion = "My kin are safe. Let us see to these serpents!" }
WordHunterWoW_QuestEN[40321] = { title = "Feathersong's Redemption", description = "I must confess I was not entirely honest with you, {name}. I meant to drink the potion and join my wife.\n\nAnd even she was taken from her rest... I cannot fail her again. I must live and do what I can to stop this coming storm to be worthy of joining her.\n\nCome, young one. Let us take care of the harpy matriarch and restore Tel'anor to its former glory. We cannot let this poison go to waste, eh?", objectives = "Slay the Cliffclutch Matriarch.", progress = "It will take time, but Tel'anor will flourish again. I swear it on my life.", completion = "Thank you, <name>. You have given me clarity of purpose and a reason to live again. Together we will save Suramar and atone for the sins of my people." }
WordHunterWoW_QuestEN[40322] = { title = "Bloodhunt Highland Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40323] = { title = "Cave of the Blood Trial Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40324] = { title = "Arcane Communion", description = "All of Kel'danath's experiments to connect with the withered failed, and some even made them more dangerous.\n\nUntil he found Theryn.\n\nHis arcane essence - the very soul of the shal'dorei - had been touched by something special. But what? \n\nBy weaving my arcane essence together with Theryn's, I can create an empathic bond. This communion will bare his soul to us all - or what's left of it. \n\nWe need only to feed him mana, and lots of it, in order to begin.", objectives = "Feed Theryn 300 Ancient Mana.", progress = "Feed Theryn as much as he will take.", completion = "Good. Let us see what we can learn." }
WordHunterWoW_QuestEN[40325] = { title = "Scenes from a Memory", description = "Theryn is at the mercy of his own mind. Whatever we find in there, it may be difficult to control.\n\nI will need your help to sort through the visions, so be ready for anything.\n\nWith any luck, we will discover what makes Theryn special. And... whether there is anything left of who he used to be.", objectives = "Help Thalyssra complete the arcane communion with Theryn.", completion = "The withered... Not only do they suffer a burning thirst for the Nightwell, but their own memories torture them as well.\n\nTruly a fate worse than death..." }
WordHunterWoW_QuestEN[40326] = { title = "Scattered Memories", description = "<As your fingers trace the elegant symbols on the page, a voice dictates the words in your mind.\n\nIt seems the nightborne have elevated even simple note-taking to a sorcerous art.\n\nArcanist Kel'danath was definitely working in this area. There must be more of his notes scattered around.>", objectives = "Inspect 6 pages of Kel'danath's Notes.", completion = "<A bag containing countless pages of technical notes. Flipping through them, you find Kel'danath's last journal entry.>" }
WordHunterWoW_QuestEN[40327] = { title = "Testing the Metal", description = "Alright, if we're going to get out of here, we're going to have to maneuver around the naga and the sea giants.\n\nThe naga probably won't pose much trouble for someone of your skill, but those sea giants are strong beyond belief.\n\nJust get me out of this cave safely and I can find my own way home.\n\nHopefully this armor Celea made for me will protect me long enough to see this through.", objectives = "Escort Taldranis to safety.", completion = "He made it out safely? Praise Elune, and you, <name>.\n\nYour heroics continue to earn my trust and my tutelage, <name>. Here are some more efficient ways of crafting your armor." }
WordHunterWoW_QuestEN[40328] = { title = "A Fate Worse Than Dying", description = "When the Burning Legion takes a prisoner, it is not an act of mercy.\n\nWhile death is the destruction of the mortal body... if you are captured by the Legion, they will seek to destroy your soul.\n\nThe Burning Legion uses sacrificial souls to power their demonic machinations of war. The soul engine is where the harvested souls are collected and stored.\n\nThough countless have already perished in the soul engine, you may yet save those still alive inside.\n\nHurry and release them before it is too late!", objectives = "Open 8 Soul Engine Cages.", progress = "Have the soul engine cages been opened?", completion = "The destruction of the soul is a fate far worse than death. You have done a great service to those you saved." }
WordHunterWoW_QuestEN[40329] = { title = "Battle Pet Tamers: Warlords", description = "You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison.\n\nBy defeating them will show your dominance in Draenor.", objectives = "Defeat 5 pet battle trainers in Draenor.", progress = "Have you been able to defeat most of the tamers?", completion = "Your dominance of the pet battlers of Draenor are unmatched. You are now better prepared to challenge other heroes like yourself." }
WordHunterWoW_QuestEN[40331] = { title = "Bite of the Sashj'tar", description = "If I had been by Throndyr's side when he fought the naga, he might still be alive.\n\nThese serpents will regret the day that they decided to slither from their watery hole!\n\nKilling them is not enough. No! I will honor Throndyr with a necklace of naga fangs!", objectives = "Collect 8 Sashj'tar Fangs from Sashj'tar naga in Azuregale Bay.", progress = "We will slay them all!", completion = "I will wear this in honor of Throndyr!" }
WordHunterWoW_QuestEN[40332] = { title = "Beach Bonfire", description = "Do not let... my body lie in... the mud.\n\nSet my flesh... aflame.", objectives = "Collect 6 Driftwood in Azuregale Bay and build a funeral pyre for Jarl Throndyr.", progress = "Throndyr deserved a more honorable death.", completion = "Hail Jarl Throndyr. May your soul find its place in Valhalas." }
WordHunterWoW_QuestEN[40333] = { title = "Spiritwind Summit Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[40334] = { title = "Fisherman's Tonic", description = "If you detest these serpents as much as we do, I ask that you continue the fight against them.\n\nThat will mean fighting them in their watery domain. I don't see any gills on you, so we're going to have to concoct an old tonic used by vrykul fishermen.\n\nThe ingredients are plentiful around here, taken that you do not mind picking through entrails.", objectives = "Collect 4 Axetail Eyes from Axetail Basilisks, a Sashj'tar Air Bladder from Sashj'tar Naga, and a Sample of Siren Blood from Siren Naz'jul in Azuregale Cove.", progress = "I will help you collect what we need.", completion = "<Brandolf mixes the concoction together.>\n\nWell, I never said that it would taste good. Bottom's up." }
WordHunterWoW_QuestEN[40335] = { title = "Sashj'tar Accord DISABLED", description = "<This stone tablet appears to be a contract between Tidemistress Sashj'tar and King Forgalash.\n\nAs far as you can decipher, the naga are recruiting the sea giants on behalf of Queen Azshara.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Show the stone tablet to Toryl.<This stone tablet appears to be a contract between Tidemistress Sashj'tar and King Forgalash.\n\nAs far as you can decipher, the naga are recruiting the sea giants on behalf of Queen Azshara.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40336] = { title = "Turning the Tidemistress", description = "The Tidemistress has fallen back to the elven ruins and is licking her wounds.\n\nHer guard is undoubtedly protecting her. To best her, you will have to break her defenses.\n\nConstruct a ballista using the parts that you salvaged and end her once and for all.", objectives = "Construct a Makeshift Ballista and kill Tidemistress Sashj'tar in the Sashj'tar Ruins.", progress = "We finally have the advantage against the Sashj'tar.\n\nNow is the time to kill the Tidemistress.", completion = "You have done it, <name>. You have slain the Tidemistress and saved Jandvik from the Sashj'tar." }
WordHunterWoW_QuestEN[40337] = { title = "Flummoxed", description = "", objectives = "" }
WordHunterWoW_QuestEN[40338] = { title = "7.0 DH-Mardum - Small Treasure Chest 009", description = "", objectives = "" }
WordHunterWoW_QuestEN[40339] = { title = "Candle of Command", description = "You no come in yet! Give orders to other kobold on Throne of Ordering Around if you want in, then maybe we talk.", objectives = "Sit upon the Throne of Ordering Around and give orders to kobolds that approach.", progress = "What you lookin' at, stink head?", completion = "What you doing back so soon?" }
WordHunterWoW_QuestEN[40340] = { title = "Alard Schmied Greeting Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[40341] = { title = "Throne of the Tides: Azshara's Power", description = "Wavespeaker Adelee tracked Sharas'dal to the Throne of Tides within the Abyssal Maw, then disappeared. {name}, if we go after her, we are almost certainly walking into a trap.\n\nBut the elements are with us, my friend. The naga will not expect a shaman of your caliber!\n\nSwim to the Throne of Tides to the Northwest, within the Abyssal Depths. I will join you once you are inside. Let's find our missing shaman and get that artifact!", objectives = "Travel to the Throne of Tides and acquire Sharas'dal.", progress = "What news from the deeps, <class>?", completion = "So the legends of the Scepter of Tides were true, <name>!\n\nIt lifts our spirits to have such a powerful artifact in the hands of the Earthen Ring." }
WordHunterWoW_QuestEN[40342] = { title = "Surprise the Sashj'tar", description = "The naga are preoccupied with recruiting the sea giants for Queen Azshara's battles in other lands.\n\nNow is the time to strike!", objectives = "Kill 12 Sashj'tar Champions or Sashj'tar Deep Witches in Azuregale Bay." }
WordHunterWoW_QuestEN[40343] = { title = "Magni/Eitrigg Meetup Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[40345] = { title = "Burn the Candle at Both Ends", description = "Why you come back already? Have to wait until jobs are done or I no let you through!\n\nGo back to Throne of Ordering Around and make sure they finish!", objectives = "Ensure that all of the kobold jobs are done.", progress = "You come in when jobs are done.", completion = "What that?! You have Candleking's Special Candle!" }
WordHunterWoW_QuestEN[40346] = { title = "Pilfered Provisions", description = "The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.", objectives = "Collect 8 Pilfered Provisions from shipwrecks in Azuregale Bay." }
WordHunterWoW_QuestEN[40347] = { title = "Gurbog da Basher", description = "", objectives = "" }
WordHunterWoW_QuestEN[40348] = { title = "Something in the Water", description = "There is something fouling these waters, {class}.\n\nWe will need to purify the waters in order to restore balance to the elemental forces below this ruin.\n\nThe magic here has warped the elementals and they are beyond restoration. Release their corrupted forms so that they may be reborn pure.", objectives = "Slay 12 Mana-corrupted Waterspawn.", progress = "Is it done?", completion = "Now that we have cleared out the corruption the fresh water elementals will be able to flourish." }
WordHunterWoW_QuestEN[40349] = { title = "Pristine Violetglass Vessel", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in Dalaran's archaeology shop.", objectives = "Put the artifact on display." }
