WordHunterWoW_QuestEN[40364] = { title = "Bubble Trouble", description = "{class}! The sea giants have already eaten half of my kin.\n\nWe are helpless in these accursed bubbles. I beseech you to get us out of here.\n\nTake heed. These bubbles are strong. You will need something that is extremely sharp to pierce them.", objectives = "Collect a piece of Needle Coral and then rescue 5 Captured Vrykul in Azuregale Bay.", progress = "Move quickly, <class>! These sea giants have an insatiable appetite!", completion = "There is no glory or honor in being digested." }
WordHunterWoW_QuestEN[40368] = { title = "Turtle Powered", description = "In order to locate and purify the source of the corruption I am going to need an elemental focus.\n\nThe turtles around here have developed scales that can focus and amplify their innate magics. Bring back some snapper scales and we will have these waters purified in no time!", objectives = "Collect 7 Shimmering Snapper Scales.", progress = "Remember, the scales need to be whole to be of any use as a focus.", completion = "These will do nicely." }
WordHunterWoW_QuestEN[40369] = { title = "Artifact XP - Ironbranch", description = "", objectives = "" }
WordHunterWoW_QuestEN[40370] = { title = "Purge the Unclean", description = "Do you feel it in the air, {race}? The stage is set for us to make things right.\n\nWhile you were busy I was able to track down the elder elemental that rules these waters. Its name is the Azurefall Guardian and it resides within the channels below Tel'anor.\n\nTake the ritual focus, it should help you during the battle.", objectives = "Defeat the corruption in the Azurefall Guardian.", progress = "Did you find the source of the corruption?", completion = "It is done. Already I can feel the corrupting presence washing away.\n\nThank you, <name>. You have done this place a great service." }
WordHunterWoW_QuestEN[40372] = { title = "The Tidemistress", description = "The forces of the Tidemistress have been shattered. All that remains is to confront the her and push back the naga for good.", objectives = "" }
WordHunterWoW_QuestEN[40373] = { title = "A New Direction", description = "{name}, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command.\n\nKayn or Altruis. You can only choose one.\n\nThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.\n\nIf you need a reminder of our past, gaze into the Pool of Judgment. Remember the sacrifices that forged us into demon hunters. Speak to me when you are ready to choose.", objectives = "Choose between Kayn and Altruis.", progress = "Have you made a choice?", completion = "I see. I support you no matter your choice. With this new beginning, we shall rebuild the Illidari." }
WordHunterWoW_QuestEN[40374] = { title = "A New Direction: Obtained Kayn", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40375] = { title = "A New Direction: Obtained Altruis", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40378] = { title = "Enter the Illidari: Ashtongue", description = "Lord Illidan has placed you in charge. Now, we just need the rest of our Illidari attack force.\n\nThere are three Burning Legion gateways ahead. Activate them and our Illidari will pour through from the Black Temple.\n\nLike most Legion constructs, the gateways are powered by souls. I think we have provided enough to activate this first one, don't you? Let us bring in our Ashtongue forces.", objectives = "Summon in your Ashtongue forces by activating the Legion Gateway.", progress = "<name>, I remind you that we need our Ashtongue forces to be brought through the gateway back on Despair Ridge.", completion = "I saw them run by. Not the most impressive of our troops, but the Ashtongue have proven effective in the past." }
WordHunterWoW_QuestEN[40379] = { title = "Enter the Illidari: Coilskar", description = "The next gateway's down on the Molten Shore. Our Coilskar forces are waiting at the Black Temple on the other side.\n\nPersonally, I wouldn't have chosen to bring our naga allies. But, their leader did swear fealty to Lord Illidan. I suppose we'll see.\n\nWe'll have to find a way to power the gateway's activator. Like this last gateway, it runs on souls.\n\n<Allari the Souleater grins as Sevis says this.>", objectives = "Feed a soul into the Legion Gateway Activator and then use it to summon in your Coilskar forces.", completion = "Grim business, but we've all sacrificed just about everything to get to where we are.\n\nWe will do ANYTHING it takes to defeat the Burning Legion. Anything." }
WordHunterWoW_QuestEN[40380] = { title = "Artifact XP - Thondrax", description = "", objectives = "" }
WordHunterWoW_QuestEN[40381] = { title = "Artifact XP - Darkfiend Assassin", description = "", objectives = "" }
WordHunterWoW_QuestEN[40382] = { title = "Artifact XP - Jinikki the Puncturer", description = "", objectives = "" }
WordHunterWoW_QuestEN[40383] = { title = "Artifact XP - Kiranys Duskwhisper", description = "", objectives = "" }
WordHunterWoW_QuestEN[40384] = { title = "Needs of the Hunters", description = "The eagle appears to have a message for you:\n\n             To: {name}\n\nThe time has come to strike back at the Legion.\n\nMeet me at Hunter's Reach in Dalaran as soon as you can.\n\n             -Emmarel Shadewarden", objectives = "Speak with Emmarel Shadewarden in Dalaran.", completion = "Your reputation precedes you, <name>.\n\nIt is important that we speak." }
WordHunterWoW_QuestEN[40385] = { title = "The Spear in the Shadow", description = "Many years ago, a corrupted nightsaber hunted my people. Our chieftain, Dorro Highmountain, took Talonclaw and pursued the beast, but never returned.\n\nI have heard tales of a fearsome nightsaber that now stalks the mists of Stormheim. My brother and I believe this to be our ancient foe.\n\nThe weapon must be there too! If we kill the beast and reclaim the spear, it will be of great use against the Legion.", objectives = "Hunt down Highmountain's Bane.", completion = "So the Bane of the Highmountain is dead and Talonclaw is recovered! Well done, <name>!\n\nI mourn the loss of Apata and Wuho. They will be greatly missed in the conflict to come." }
WordHunterWoW_QuestEN[40386] = { title = "Tracking Quest: Khadgar Arrival", description = "", objectives = "" }
WordHunterWoW_QuestEN[40388] = { title = "Huln's War - Shadowsong", description = "Someone with whom I believe you are familiar commands in the battlefield below.\n\nJarod Shadowsong speaks highly of you, and has requested that you join him in battle.\n\nHe has plans to put an end to this fight.", objectives = "Meet with Jarod Shadowsong in the battlefield.", completion = "I am happy to see you, great ally." }
WordHunterWoW_QuestEN[40389] = { title = "7.0 Highmountain - Treasure - Skyhorn Kite Created", description = "", objectives = "" }
WordHunterWoW_QuestEN[40390] = { title = "Hallowed Ground", description = "", objectives = "" }
WordHunterWoW_QuestEN[40391] = { title = "Take Me To Your Leader", description = "I am glad you are here, {name}.\n\nThis... Khadgar, the archmage who found my message, has called a meeting.\n\nHe wishes to meet us at the entrance to the city as soon as possible.\n\nWill you accompany me? I have the strangest feeling that he will not be alone.", objectives = "Meet with Khadgar in Suramar.", completion = "Hello again, champion. I see we are all here now." }
WordHunterWoW_QuestEN[40392] = { title = "Call of the Marksman", description = "Time is of the essence! If Alleria and Thas'dorah are in Legion hands, it is only a matter of time until both are forfeit.\n\nIf you are ready, head to the Broken Shore to meet with Ranger-General Windrunner.\n\nShe has lent her personal hippogryph to fly you down to the surface.", objectives = "Take the hippogryph from Krasus' Landing down to the Broken Shore and meet with Vereesa Windrunner.", completion = "The Farstriders have been interrogating captured demons.\n\nOne of the vile creatures claims to know the whereabouts of someone... crucial to our cause." }
WordHunterWoW_QuestEN[40393] = { title = "Axes for Arrows", description = "The scales of these naga are as strong as any armor. My arrows can barely pierce them. I need something better to strike these naga down.\n\nThe spines of the nearby Axetails make excellent arrowheads. I will watch over the camp while you are gone.", objectives = "" }
WordHunterWoW_QuestEN[40394] = { title = "Fish and Supplies", description = "Hail, {name}.\n\nWe need to restock our supplies after the naga attack. Too many of us are injured to properly hunt and forage.\n\nYou have helped us in the past. Would you help us yet again?", objectives = "" }
WordHunterWoW_QuestEN[40395] = { title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[40396] = { title = "That's the Spirit", description = "<Fjolrik motions for you to come closer.>\n\nHey {name}. I have heard stories of these naga distilling some concoction.\n\nI do not know what they use it for, but I have heard rumors that it provides a vrykul with a might kick, if you follow me.\n\nAsta will thank you for it.", objectives = "" }
WordHunterWoW_QuestEN[40397] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40398] = { title = "Shaman Shrine - Stormheim Water 01 - DGK", description = "", objectives = "" }
WordHunterWoW_QuestEN[40399] = { title = "7.0 Suramar - Vignette: Sailor's Nightmare - twh", description = "", objectives = "" }
WordHunterWoW_QuestEN[40400] = { title = "Clandestine Operation", description = "You have long been a trusted hero of the Alliance, {name}. And like the rest of us, you have endured many hardships to reach this point.\n\nNow, I must ask even more of you. Will you hear me out?", objectives = "Speak to Vereesa Windrunner.", progress = "Now you must decide whether you will stand with me.", completion = "The time to make our move is now." }
WordHunterWoW_QuestEN[40401] = { title = "A Way Back In", description = "I must get back into Suramar.\n\nI was exiled unfairly! I cannot live out here like this. I need the Nightwell's energies...\n\nI saw a message carved into a wall a few days ago. There is someone in the Water Gardens who can smuggle people into the city.\n\nIt said \"We shall drink of the Well again.\"\n\nI cannot survive a confrontation with the guards again. Will you go in my stead? Once I am back in the city I can repay you.", objectives = "Find the smuggler.", progress = "Who are you to seek passage into Suramar?", completion = "I hope for both of our sakes that you were not followed. We must work quickly, considering how close I am." }
WordHunterWoW_QuestEN[40402] = { title = "Clandestine Operation", description = "As you well know, I have opposed the Horde at many turns. The orcs have taken... so much from me. From my family.\n\nYet I have witnessed your deeds firsthand, {name}. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.\n\nNow, I must ask your help. Will you hear me out?", objectives = "Listen to Vereesa Windrunner's tale.", progress = "Now you must decide whether you will stand with me.", completion = "The time to make our move is now." }
WordHunterWoW_QuestEN[40403] = { title = "Clandestine Operation", description = "It is no small matter for me to seek the aid of a blood elf. Your leaders have turned their backs on the sacrifices made by my family and so many others.\n\nYet I have witnessed your deeds firsthand, {name}. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.\n\nNow, I must ask your help. Will you hear me out?", objectives = "Listen to Vereesa Windrunner.", progress = "Now you must decide whether you will stand with me.", completion = "The time to make our move is now." }
WordHunterWoW_QuestEN[40404] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40405] = { title = "Bristlemaul", description = "", objectives = "" }
WordHunterWoW_QuestEN[40406] = { title = "Luggut the Eggeater", description = "", objectives = "" }
WordHunterWoW_QuestEN[40407] = { title = "The Fate of Azeroth", description = "The Burning Legion devastated us at the Broken Shore - the greatest army this world has ever known reduced to cinders in mere moments. Our weapons glanced off of their armor... our spells lost in a sea of fel fire.\n\nWe need weapons capable of destroying Sargeras and his minions while we still have a chance.\n\nThe greatest paladins the world over have gathered at Krasus' Landing to discuss our next move - we're only missing you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Join the greatest paladins of Azeroth at Krasus' Landing.The Burning Legion devastated us at the Broken Shore - the greatest army this world has ever known reduced to cinders in mere moments. Our weapons glanced off of their armor... our spells lost in a sea of fel fire.\n\nWe need weapons capable of destroying Sargeras and his minions while we still have a chance.\n\nThe greatest paladins the world over have gathered at Krasus' Landing to discuss our next move - we're only missing you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[40408] = { title = "Weapons of Legend", description = "Our gathering has identified several weapons of immense power. In the right hands, these holy artifacts give us a fighting chance against the Legion.\n\nWe cannot pursue all of them at once. We risk too much if we spread ourselves that thin. We must agree on where our efforts are best focused.\n\nThat is why I asked you here, {name}. As one of our greatest champions, you must be our voice of reason and decide our next move.", objectives = "Select an artifact weapon to pursue.", completion = "Excellent choice! There's no time to waste." }
WordHunterWoW_QuestEN[40409] = { title = "Ashbringer Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40410] = { title = "Silver Hand Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40411] = { title = "Truthguard Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40412] = { title = "Azoran Must Die", description = "You won't have much time before the Legion is aware of your presence on the ship.\n\nWhen the alarm is raised, countless Burning Legion forces will attempt to board the ship through this portal.\n\nI will not let them succeed.\n\nI will guard this portal from enemy reinforcements until you return. It is up to you to slay Azoran and lay waste to his ship.\n\nWe don't have much time... you must attack swiftly and without mercy.", objectives = "Defeat Azoran in Felsoul Hold.", progress = "Has Azoran been slain?", completion = "With Azoran slain, the Legion has been dealt a crippling blow that they will not soon recover from.\n\nYou have my respect, <name>." }
WordHunterWoW_QuestEN[40413] = { title = "Amateur Hunters", description = "", objectives = "" }
WordHunterWoW_QuestEN[40414] = { title = "Devouring Darkness", description = "", objectives = "" }
WordHunterWoW_QuestEN[40415] = { title = "Well Spent Time", description = "Your respect for our ways has earned you all the knowledge we have to teach. Go now, {name}, and spread our ways to those who fight against the legion.\n\nPerhaps it will help to turn the tide in this war for our world.", objectives = "Tell Namha of your time with the tauren in Highmountain.", completion = "To think that leatherworking has been that ingrained in the highmountain tauren heritage for that long is absolutely amazing.\n\nI suddenly wish I knew more about my own people's past as well as they do." }
WordHunterWoW_QuestEN[40416] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[40417] = { title = "To Tanaan!", description = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.\n\nThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting....", objectives = "Speak with Warchief Vol'jin inside the Town Hall of your garrison.", completion = "<The Warchief studies a map of Tanaan Jungle and its surroundings, his brow creased with worry.>\n\nAh, Commander <name>! Voice of da Horde in Draenor. Ya done well here, bringin' da fight ta our enemies. Thrall tells me ya exceed his every expectation.\n\nIt be time ta finish dis. Are ya ready?" }
WordHunterWoW_QuestEN[40418] = { title = "To Tanaan!", description = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.\n\nThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", objectives = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", completion = "<The King is studying maps of Tanaan Jungle and the surrounding area.>\n\n<name>! The Alliance owes you a great debt for establishing this garrison. Thanks to your bravery and commanding leadership, we've fought this war here on Draenor, instead of amongst our own homes and farmsteads.\n\nIt's time now to finish this. Are you ready for the final campaign?" }
WordHunterWoW_QuestEN[40419] = { title = "Rescue Mission", description = "The demon has told us how to open a portal to the world where he says Alleria is being held. You and I can go through and see if there is any truth to his claims.\n\nIn case it's a trap, Magus Solgaze has given me a portal stone to get us back to Dalaran.\n\nThis demonic magic is anathema to the mage, so we must move quickly. I'm ready when you are, {name}.", objectives = "Travel through the portal and rescue Alleria Windrunner.", completion = "We didn't recover Alleria, but at least we have proof she was there. She will be found... I know it!\n\nThas'dorah has long been symbolic of the Windrunner family, but until Alleria's return, it belongs in your hands.\n\nUse it to rally the greatest hunters of Azeroth and drive the Burning Legion back to the abyss!" }
WordHunterWoW_QuestEN[40420] = { title = "Felsoul Hold", description = "", objectives = "" }
WordHunterWoW_QuestEN[40422] = { title = "Tracking Quest: VotW Started", description = "", objectives = "" }
WordHunterWoW_QuestEN[40423] = { title = "Unethical Adventurers", description = "", objectives = "" }
WordHunterWoW_QuestEN[40424] = { title = "A Desperate Journey", description = "The city's entrances are under heavy guard. He must have another way.\n\nThanks to this wine I am strong enough to make the journey to him. I fear that I will not be able to defend or run if I come under attack.\n\nYou will accompany me, {race}. You and this Astoril are my only chance at surviving now. \n\nI remember when I was leaving the city that there were lamps guiding me here. We should be able to retrace our steps by following them.", objectives = "Follow the lamp posts to take Iadreth to Astoril.", progress = "I was worried something had happened to you in the forest. I am glad that I was wrong.", completion = "Excellent. Your part here is done.\n\nRest assured knowing that you have done me a great service.\n\nHere, take this payment. It is a small token for your service." }
