WordHunterWoW_QuestEN[40469] = { title = "Final Preparations", description = "We will need supplies for our trip into Suramar. We cannot exactly stop for refreshments at the gate with you two in tow, can we?\n\nThe water gardens were a place to socialize and relax. Before the patrols arrived it was rather trivial to hide some mana wine for later retrieval.\n\nThat's where you come in. Fetch some supplies and bring them to your friend, then meet me at the ruins north of the city. We will be ready to depart soon.", objectives = "Recover 6 stashed supplies.", progress = "Did you find the smuggler? What did they say?", completion = "Is that mana wine? For me?\n\n<Iadreth hungrily gulps down the bottle.>\n\nYou and this Astoril have my thanks. I would surely have perished out here." }
WordHunterWoW_QuestEN[40470] = { title = "Quality of Life", description = "I am afraid, {name}. We're so close to home, so close to salvation...\n\nAstoril says he knows the rest of the way through and can get us there safely. I believe him, but you've come this far to see us safe. Will you see this through to the end?", objectives = "Follow Iadreth.", completion = "This is a most troubling tale. \n\nYou have done a good thing, <name>. Now he will no longer torment our people." }
