WordHunterWoW_QuestEN[40704] = { title = "Champion: Li Li Stormstout", description = "", objectives = "You know, I've been thinking about all the fun we've had together. You're great to hang around and I'm sure Uncle Chen wouldn't mind if I stuck around since you're a Grandmaster and all.\n\nWhat I'm trying to say is, I'd be happy to be your explorer, scout, or resident adventurer. So, what do you say?" }
WordHunterWoW_QuestEN[40705] = { title = "Priestly Matters", description = "Master {name}, I come at the behest of one who seeks to organize a stronger resistance to the Legion threat.\n\nIf you would meet him at Faol's Rest in Tirisfal Glades, he will guarantee both your safety and an opportunity to play a pivotal role in the conflict.", objectives = "Attend the secret meeting at Faol's Rest in Tirisfal Glades.", completion = "Can I take that as a yes?\n\nIf you are ready, I'd like to get started immediately.\n\nI know you are immensely capable, but let's not leave anything to chance!" }
WordHunterWoW_QuestEN[40706] = { title = "A Legend You Can Hold", description = "To face the trials ahead, you require a weapon that can enhance your considerable abilities. I have learned of a few possibilities that you might consider.\n\nYou must decide which weapon to pursue first. I have the utmost confidence in your decision.", objectives = "Select an artifact weapon to pursue.", completion = "A wise choice. My brethren and I stand ready to assist you on your next move, <name>." }
