WordHunterWoW_QuestEN[40725] = { title = "Arganax", description = "A satyr known as Arganax has infiltrated the village of Lorlathil in Val'sharah. I believe that Arganax has disguised himself as one of the local residents.\n\nUse the demon Eye of Azzorok on the villagers in Lorlathil. If there is a demon disguised as a local, the Eye of Azzorok will reveal their true identity.\n\nUncover the demon infiltrator Arganax, and slay him without mercy.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find and slay Arganax in Lorlathil." }
WordHunterWoW_QuestEN[40726] = { title = "Test Reward Quest", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[40727] = { title = "All Along the Waterways", description = "I've noticed some wandering eyes, lately.\n\nI am more than happy to continue delivering the goods to Vanthir, but it is getting increasingly dangerous to do so. \n\nThe Duskwatch that walk the bazaar are by far the most observant.\n\nFind and slay the Orbitists so that I may deliver the goods safely.\n\nI will follow behind with the shipment.", objectives = "Slay 3 Duskwatch Orbitists.", progress = "What of Deline?", completion = "Deline was able to deliver the goods safely, thanks to you." }
